import json,re,pathlib,subprocess,os,sys,hashlib
ROOT=pathlib.Path(__file__).resolve().parents[1]
os.chdir(ROOT)
p=pathlib.Path('assets/js/dashboard-help-data.js');s=p.read_text();d=json.loads(s.split('window.SSMPDHelpData=',1)[1].strip().removesuffix(';'))
rows=json.loads(subprocess.check_output(['node','scripts/help-field-inventory.cjs','--json'],text=True));rules=[]
def rule(labels,text,article=None):
 rules.append((set(labels.split('|')),text,article))
file_rules={}
def frule(files,labels,text,article):
 # File-scoped explanation: the same label can mean different things on other screens.
 for f in files.split('|'):file_rules.setdefault(f,[]).append((set(labels.split('|')),text,article))
frule('instinct-assistant.js','لمين','الفريق اللي هتظهر له الملاحظة بعد ما المالك ينشرها: كل الموظفين أو الاستقبال أو خدمة العملاء أو فريق المحتوى أو الحسابات أو الإدارة.','instinct-assistant')
frule('instinct-assistant.js','النص','نص ملاحظة إرشادية من مساعد إنستنكت. ممنوع أي اسم أو رقم أو بيانات مريض؛ السيرفر بيرفض أرقام الموبايل وأكواد الملفات والأرقام القومية.','instinct-assistant')
rule('ملاحظات الخزينة','اكتب وصفًا للعهدة أو تعليمات الاستلام. الملاحظة لا تغير صلاحيات الخزينة.','ledger-guide')
rule('نوع الكشف','اختر كشف ماكينة الفيزا أو البنك أو المحفظة ليقارن النظام الحركات بالحساب المقابل.','ledger-guide')
rule('البنك أو شركة التحصيل|شركة التحصيل أو البنك','اكتب الجهة التي أصدرت الكشف أو الإيصال، مثل فوري أو اسم البنك.','ledger-guide')
rule('رابط أصل الكشف على Google Drive — اختياري|رابط الإيصال على Google Drive — اختياري','ضع رابط المستند الموجود على Google Drive إذا أردت الاحتفاظ بمرجع الأصل. اختيار الملف هنا لا يرفعه تلقائيًا.','ledger-guide')
rule('ملف PDF أو Excel أو CSV','اختر ملفًا حتى20 ميجابايت. راجع كل السطور المستخرجة وعددها وإجماليها قبل الحفظ. الحد500 عملية و50 صفحة للكشف.','ledger-guide')
rule('استخدام قراءة الصور OCR للصفحات الممسوحة على الجهاز','فعّل قبل اختيار الملف لقراءة الصفحات المصورة على جهازك. راجع الأرقام لأن القراءة قد تخطئ.','ledger-guide')
rule('عدد العمليات بعد مقارنته بأصل الكشف','اكتب عدد العمليات بعد مراجعة كل صفحات الكشف. يجب أن يساوي عدد السطور التي ستحفظ.','ledger-guide')
rule('إجمالي المبالغ بإشارتها بعد مراجعته بالكشف','اكتب مجموع الداخل موجبًا والخارج سالبًا بعد المقارنة بأصل الكشف. يجب أن يساوي مجموع المعاينة.','ledger-guide')
rule('راجعت كل الصفحات والمراجع والمبالغ والعدد والإجمالي مقابل أصل الكشف','أكد بعد فحص الصفحات والعمليات والمراجع بنفسك. القراءة الآلية ليست اعتمادًا لصحة الكشف.','ledger-guide')
rule('دليل الربط وسبب التجميع','اشرح مرجع التسوية أو المستند الذي يثبت أن مجموع الحركات المختارة يمثل سطر الكشف.','ledger-guide')
rule('الموظف المكلف بالمراجعة','اختر الموظف المطلوب منه التحقق. التكليف لا يعني أنه مسؤول عن الفرق.','ledger-guide')
rule('موعد الرد','حدد موعدًا قادمًا لرد الموظف على مهمة مراجعة الاختلاف.','ledger-guide')
rule('المطلوب مراجعته','اكتب المطلوب من الموظف ودليل التحقق، دون إدراج بيانات طبية في المهمة.','ledger-guide')
rule('الرقم المرجعي في الإيصال','انقل مرجع عملية الدفع من الإيصال. لا تستخدم رقم الفاتورة بدل مرجع شركة التحصيل.','ledger-guide')
rule('RRN — اختياري','انقل حقل RRN كما يظهر في إيصال الماكينة إن وجد. لا تدخل رقم البطاقة.','ledger-guide')
rule('كود الماكينة — اختياري','انقل كود الماكينة من الإيصال لتمييز الجهاز الذي سجل التحصيل.','ledger-guide')
rule('ابحث في الشجرة|البحث بالكود أو اسم الحساب','اكتب جزءًا من اسم الحساب أو كوده لعرض موضعه في الشجرة. البحث لا يغير الحسابات.','ledger-guide')
rule('نوع الحساب','اختر أصلًا أو التزامًا أو حقوق ملكية أو إيرادًا أو مصروفًا. نوع الابن يجب أن يطابق نوع الأب.','ledger-guide')
rule('المستوى المحسوب من الأب|المستوى','المستوى الأول بلا أب، وكل ابن يزيد مستوى واحدًا. الحد خمسة مستويات. في معاينة الاستيراد يجب أن يتطابق المستوى مع الأب.','ledger-guide')
rule('حالة الحساب','اختر مفعّلًا للسماح باستخدام الحساب أو موقوفًا لمنع الحركات الجديدة. لا يمكن إيقاف حساب نظام أو حساب مرتبط بخزينة أو له أبناء مفعّلون.','ledger-guide')
rule('طبيعة الحساب','الحساب التجميعي يجمع أبناءه ولا يقبل قيودًا مباشرة. حساب الحركة يقبل قيودًا ولا يضم حسابات أبناء.','ledger-guide')
rule('دور الخزينة','اختر الرئيسية للصرف والاستلام، أو خزينة تحصيل لتلقي النقد وتسليمه إلى الرئيسية. يسمح النظام برئيسية واحدة.','ledger-guide')
rule('حساب الخزينة في الشجرة','اختر حساب أصل مفعّلًا قابلًا للحركة ومخصصًا لهذه الخزينة. لا تشارك خزينتان نفس الحساب، ولا يتغير ربط حركة قديمة.','ledger-guide')
rule('الخزينة الرئيسية المستلمة','اختر الخزينة الرئيسية التي تستلم حصيلة خزينة التحصيل. افتح وردية للمستلم قبل اعتماد التسليم.','ledger-guide')
rule('حد النثريات للإذن بالجنيه','أدخل حد الإذن بالصرف. خزينة التحصيل حدها صفر، والصرف من الرئيسية يخضع للرصيد والاعتماد.','ledger-guide')
rule('راجعت الأكواد والأسماء والأب والمستويات قبل الإضافة','حدد هذا الاختيار بعد مراجعة كل صف في المعاينة. أي تعديل أو اقتراح جديد يحتاج مراجعة جديدة. المعاينة لا تحفظ حسابات تلقائيًا.','ledger-guide')
rule('اقتراح الكود تلقائيًا من الأب — يمكنك تعديله','فعّل الاختيار ليقترح النظام كودًا متاحًا تحت الأب. تغيير الكود يدويًا يوقف الاقتراح؛ عند الحفظ يعيد النظام التحقق من عدم التكرار ويحافظ على أكواد الحسابات السابقة.','ledger-guide')
rule('كود الأب','أدخل كود الحساب التجميعي الذي يتبعه هذا الحساب. اتركه فارغًا للمستوى الأول فقط.','ledger-guide')
rule('وردية التحصيل المفتوحة','اختر ورديتك المفتوحة التي ستسلم حصيلتها. لا يمكنك اختيار وردية موظف آخر.','ledger-guide')
rule('المبلغ المسلّم فعليًا بالجنيه','أدخل النقد الذي ستسلمه فعليًا. لا يتجاوز رصيد الوردية بعد طرح التسليمات المعلقة، ولا يتغير الرصيد حتى اعتماد المستلم.','ledger-guide')
rule('رقم مستند التسليم','اكتب رقم سند التسليم الذي يرجع إليه الطرفان عند المراجعة. لا تكرر رقم سند سابق.','ledger-guide')
rule('سبب التسليم','اكتب سبب التحويل مثل تسليم حصيلة اليوم إلى الخزينة الرئيسية.','ledger-guide')
rule('ملاحظة الاستلام أو سبب الرفض','بعد عدّ النقد اكتب ملاحظة الاستلام، أو سبب الرفض عند عدم استلامه. لا يعتمد مقدم الطلب طلبه بنفسه.','ledger-guide')
rule('نص Brief المواعيد','نص للنسخ إلى إضافة منشئ محتوى عيادات سونو. يحتوي اليوم والأسماء والتخصصات والساعات كما أدخلتها، وتعليمات صياغة المنشور دون تغيير الجدول. انسخه للإضافة ثم استورد الرد لاختيار النص.','design-guide')
rule('نوع التصميم والنشر','اختر منشور 1080×1350 أو ستوري فقط 1080×1920. يحفظ الاختيار مع نسخة التصميم ويستخدمه عامل النشر بعد الاعتماد. الستوري لا تنشر بوستًا في الصفحة، والنص المولد يبقى للمراجعة ولا يظهر ككابشن داخل الستوري.','design-guide')
rule('يوم جدول العيادات','اختر اليوم الذي يخصه منشور المواعيد. يظهر اسم اليوم في أعلى التصميم، ولا يغير مواعيد الحجز الفعلية.','design-guide')
rule('اسم الطبيب في جدول اليوم','اكتب اسم الطبيب كما سيظهر للجمهور. راجع الاسم قبل إرسال المادة للاعتماد. هذا الحقل يخص المنشور ولا ينشئ طبيبًا أو عقدًا.','design-guide')
rule('تخصص العيادة في الجدول','اكتب التخصص المختصر الذي سيظهر بجانب اسم الطبيب. راجع أن النص يناسب مساحة المعاينة؛ لا يغير تخصص الخدمات.','design-guide')
rule('بداية موعد العيادة|نهاية موعد العيادة','اختر الساعة والدقيقة مع صباحًا أو مساءً من حقل الوقت. النهاية الأقل من البداية تعني اليوم التالي؛ يجب اختلاف البداية والنهاية. هذه أوقات المنشور فقط وليست حجزًا لمريض.','design-guide')
# Each rule is an authored explanation for the listed source labels, not a word-based runtime guess.
rule('الصفحة|المادة دي لصفحة','اختار الصفحة التي ستنشر باسمها المادة، سونو أو د. دينا. الاختيار يحدد هوية المحتوى والتخصص والذاكرة المستخدمة، ولا يربط حسابًا جديدًا بالسوشيال.','content')
rule('عدد الأفكار','اختار عدد الأفكار المطلوب تجهيزها لخطة الأسبوع القادم. الخيارات الحالية 7 أو 10 أو 14 أو 21. العدد يخص الأفكار التي يطلبها الـBrief من الوكيل، وليس عدد أيام الأسبوع أو أمر نشر تلقائي.','weekly-planning')
rule('هدف البوست|الهدف الإعلاني|الهدف (Objective)','حدد النتيجة المطلوبة من المحتوى أو الحملة، مثل التوعية أو بناء الثقة أو رسائل واتساب. الهدف يوجّه الفكرة والدعوة للتفاعل، ولا يثبت أن النتيجة تحققت.','content-brief')
rule('شكل المحتوى|شكل المحتوى (اختياري)','اختار بوست صورة أو كاروسيل أو فيديو/ريل حسب المطلوب. الاختيار يحدد الحقول وطريقة الإنتاج، ولا يعني أن التصميم أو الفيديو تم إنشاؤه.','content-brief')
rule('الموضوع / الخدمة|الموضوع / الخدمة (اختياري)|الموضوع أو توجيه إضافي','اكتب موضوع المادة أو الخدمة المقصودة مع توجيه محدد، مثل توعية عن الصداع المتكرر. لا تضع بيانات مريض أو وعود علاجية غير معتمدة.','content-brief')
rule('Hook','اكتب الجملة الافتتاحية التي تظهر أو تقال في بداية المحتوى لجذب الانتباه للموضوع، مثل سؤال يعبّر عن مشكلة الجمهور. لا تستخدمها بدل نص المنشور كله.','content-brief')
rule('Angle','اكتب زاوية تناول الموضوع، مثل تصحيح اعتقاد شائع أو شرح متى يطلب الشخص تقييمًا طبيًا. تختلف عن العنوان وعن الجملة الافتتاحية.','content-brief')
rule('سكريبت / Voice-over|نص التعليق الصوتي','اكتب النص الذي سيُقال في الصوت أو الفيديو بالترتيب المطلوب. راجع نطق الأسماء والأرقام، وطابق طول النص مع مدة الفيديو قبل التوليد.','video-guide')
rule('كابشن النشر','اكتب نص المنشور الذي سيظهر مع الصورة أو الفيديو على المنصة. الكابشن يختلف عن الكلام المكتوب داخل التصميم وعن سكريبت الصوت.','content-brief')
rule('نوع CTA','اكتب نوع الإجراء الذي تريد من الجمهور تنفيذه حسب النموذج، مثل save_share أو whatsapp أو book. طابقه مع الهدف ومع نص الدعوة المكتوب.','content-brief')
rule('نص CTA|الدعوة للتفاعل','اكتب الجملة التي تطلب بها الإجراء من الجمهور، مثل «احفظ المنشور» أو «تواصل للحجز». اختر طلبًا واحدًا يناسب هدف المادة.','content-brief')
rule('أقل مدة (ث)|أقل مدة بالثواني','اكتب الحد الأدنى لمدة الفيديو بالثواني، مثل 20، وليس بالدقائق. يجب ألا يزيد عن الحد الأقصى، وتظل المدة النهائية مرتبطة بالنص والمشاهد.','video-guide')
rule('أقصى مدة (ث)|أقصى مدة بالثواني','اكتب الحد الأقصى لمدة الفيديو بالثواني، مثل 45. اجعله مساويًا للحد الأدنى أو أكبر منه وراجع ملاءمة السكريبت.','video-guide')
rule('Video Template','اكتب معرّف قالب الفيديو الذي يقبله مسار الإنتاج، مثل medical_educational إذا كان هو القالب المطلوب. هذا معرّف قالب، وليس عنوان المنشور.','video-guide')
rule('سبب الفرضية / Evidence note','اكتب لماذا تتوقع أن تنجح الفكرة وما الدليل المتاح، مثل نتيجة سابقة أو سؤال متكرر. هذا تبرير للاختبار وليس نتيجة أداء تحققت.','content-brief')
rule('الناتج الخام من الوكيل (اختياري)','احتفظ برد الوكيل الأصلي عند الحاجة للمراجعة. لا تضع فيه كلمة مرور أو بيانات مرضى، وراجع الحقول المنظمة التي سيعتمد عليها التنفيذ.','content-brief')
rule('العنوان','اكتب عنوانًا يميز المادة أو السجل في هذه الشاشة. في المحتوى هو عنوان الفكرة، وفي بيانات المركز هو عنوان المكان. اتبع اسم النموذج قبل الحفظ.','content')
rule('نص المحتوى','اكتب الفكرة والنص المطلوب مراجعتهما. رتّب الرسالة وأضف المراجع الطبية في حقول المصادر، ثم أرسل للمراجعة حسب المرحلة.','content')
rule('التخصص|التخصص / القسم|القسم|فلترة المؤشرات بتخصص معيّن','اختار التخصص أو القسم الذي تخصه الخدمة أو المادة أو التقرير. في الفلترة يغيّر العرض فقط، وفي الحجز يؤثر على ترشيح الطبيب المطابق للقسم.','content')
rule('اسم المصدر','اكتب اسم الجهة أو المجلة التي نشرت المرجع، مثل هيئة صحية أو مجلة علمية. لا تكتب اسمًا من غير مصدر موجود يمكن مراجعته.','medical-sources')
rule('عنوان الصفحة أو الدراسة','انقل عنوان الصفحة أو الدراسة التي تدعم المعلومات المستخدمة، حتى يقدر المراجع يطابقها مع الرابط.','medical-sources')
rule('الرابط (https)|رابط المصدر أو مرجعه','ضع رابط المرجع الفعلي أو بياناته التي تسمح بالرجوع إليه. رابط الصفحة العامة للجهة وحده قد لا يدعم المعلومة المحددة.','medical-sources')
rule('النص الذي يظهر على التصميم (يُترك فارغًا لو المحتوى غير طبي)','اكتب اسم المصدر بصيغة قصيرة مناسبة للتصميم بعد التأكد من المرجع. اترك الحقل فارغًا إذا كانت المادة غير طبية وفق تعليمات النموذج.','medical-sources')
rule('نص المصدر أو ملخصه','ضع النص أو الملخص الذي يعتمد عليه المحتوى، مع المرجع في حقله. حافظ على المعنى وراجع نقل الأرقام دون اختلاق معلومة غير واردة.','medical-sources')
rule('نوع الطلب|نوع المحتوى|أسلوب المحتوى|نوع الإجراء','اختار من القائمة نوع العمل المقصود في عنوان النموذج. النوع يحدد الحقول والخطوات التالية، فراجعه قبل ملء المبالغ أو إرسال الطلب.','content')
rule('الجمهور','حدد لمن تُكتب الرسالة، مثل مرضى بالغين أو أولياء أمور، حتى تتوافق اللغة والتفاصيل مع القارئ المقصود.','content-brief')
rule('القالب|قالب التصميم|تنويعة التصميم','اختار تخطيط القالب المناسب للمحتوى، ثم راجع المعاينة والحقول التي يتيحها. تغيير القالب قد يغيّر أماكن النصوص والصور.','design-guide')
rule('نسخة اللوجو','اختار نسخة الشعار التي تتناسب مع الخلفية، ثم تأكد أنه واضح داخل المعاينة. لا تستبدل هوية صفحة بهوية صفحة أخرى.','design-guide')
rule('العنوان الرئيسي — حتى ٥ كلمات|عنوان الكفر','اكتب عنوانًا يصلح للقراءة داخل التصميم أو الكفر. التزم بالحد المكتوب بجوار الحقل، وراجع ألا يخرج النص عن مساحته.','design-guide')
rule('عنوان ثانوي','اكتب السطر المكمل للعنوان الرئيسي إذا احتاج التصميم توضيحًا. يمكن تركه فارغًا إذا لم تكن له حاجة وكان الحقل اختياريًا.','design-guide')
rule('السطر التوضيحي — حتى ٨ كلمات|السطر التوضيحي','اكتب شرحًا قصيرًا يكمل العنوان داخل التصميم، والتزم بعدد الكلمات إن وُجد. هذا السطر لا يحل محل الكابشن.','design-guide')
rule('ترتيب السطرين|وضع العنوان|مكان العنوان','اختار ترتيب النص ومكانه حسب المعاينة. راجع عدم تغطية الصورة أو الشعار وعدم خروج السطر خارج حدود التصميم.','design-guide')
rule('عرض منطقة النص بالبكسل','عرض المساحة المسموح للنص أن يلتف داخلها بالبكسل. زيادته توسع السطر، وتقليله يوزع الكلام على سطور أكثر.','design-guide')
rule('حجم خط العنوان بالبكسل|حجم خط السطر التوضيحي بالبكسل|حجم خط زر التفاعل بالبكسل|حجم العنوان الثانوي|حجم نص التصميم','اكتب أو حرّك حجم الخط بالبكسل للعنصر المذكور فقط. راجع المعاينة بعد التعديل حتى لا يتداخل النص أو يُقص.','design-guide')
rule('الدكتور أو الدكتورة|اختر الطبيب|الطبيب|الطبيب / مقدم الخدمة|الطبيب المعالج|الطبيب المنفذ','اختار الطبيب الذي يخصه الإجراء فعلًا. في الحجز يلزم تطابق القسم وعقد مؤهل وتواجد، وفي التنفيذ يسجل الطبيب الذي قدم الخدمة.','doctor-missing')
rule('اسم الدكتور|اسم الطبيب|اسم الطبيب الموقّع','اكتب الاسم المعتمد للطبيب كما سيظهر في التصميم أو التقرير أو العقد. لا تستخدم اسم موظف بديلًا عن الطبيب المسؤول عن المستند.','design-guide')
rule('التايتل والتخصص','اكتب الصفة المهنية والتخصص المعتمدين للطبيب كما سيظهران على التصميم، دون إضافة مؤهل أو لقب غير مثبت.','design-guide')
rule('حجم الاسم الأقصى|حجم التايتل الأقصى','حدد أكبر حجم خط مسموح للاسم أو الصفة في المعاينة. راجع الأسماء الطويلة حتى تظل داخل المنطقة المخصصة.','design-guide')
rule('أيام العمل','حدد الأيام التي تخص جدول الطبيب أو التصميم حسب المواعيد المعتمدة. هذا النص في التصميم لا ينشئ تواجدًا في جدول الحجز.','design-guide')
rule('من الساعة|حتى الساعة','حدد بداية أو نهاية الفترة وفق المواعيد المقصودة. عند تجهيز تصميم مواعيد راجعها مع الجدول، فهي لا تعدل جدول الحجز تلقائيًا.','design-guide')
rule('تكبير صورة الدكتور|تكبير أو تصغير الصورة|تكبير الصورة|تكبير صورة بعد','تحكم في تكبير الصورة داخل إطارها، وليس أبعاد الملف النهائي. راجع ألا يُقص الوجه أو الجزء المطلوب من الصورة.','design-guide')
rule('تحريك داخل الدائرة يمينًا ويسارًا|تحريك داخل الدائرة فوق وتحت|موضع أفقي|تحريك صورة قبل أو الديكوبيه يمينًا ويسارًا|تحريك صورة بعد يمينًا ويسارًا|تحريك صورة بعد فوق وتحت|مكان الصورة يمين/شمال|مكان الصورة فوق/تحت','حرّك الصورة داخل الإطار في الاتجاه المذكور، ثم راجع المعاينة. الحركة لا تغير بيانات الصورة الأصلية أو معنى الحالة.','design-guide')
rule('صورة من جهازك|صورة بعد|الصورة (تقدر تاخد لقطة من الفيديو)|نوع الصور|اختيار الملفات|اختيار الملف|رفع ملف لهذا المشهد|نوع الملف','اختار نوع الملف أو ارفع الملف المطلوب للعنصر المذكور. راجع أنه يخص المادة والصفحة وله إذن استخدام، ثم تحقق من ظهور المعاينة.','design-guide')
rule('وصف المشهد|وصف اللقطة المطلوبة','صف الأشخاص والمكان والحركة والإضاءة المطلوبة للمشهد. استخدم وصفًا محددًا دون بيانات مرضى أو طلب تمثيل نتيجة علاج غير موثقة.','video-guide')
rule('الجودة|النموذج','اختار جودة أو نموذج التوليد المتاح. راجع التكلفة المتوقعة والميزانية قبل بدء التوليد، ثم افحص الناتج قبل اعتماده.','video-guide')
rule('بداية الـFade|نهاية الـFade|طول الفيد بالبكسل','حدد منطقة التلاشي التي تمزج الصورة بالخلفية. راجع تدرج الانتقال في المعاينة حتى لا يخفي النص أو تفاصيل الصورة.','design-guide')
rule('نص داخل التصميم — للقوالب ١ إلى ٥','اكتب النص الذي سيُرسم داخل القالب المحدد. راجع عدد الكلمات وفواصل السطور في المعاينة؛ هذا ليس كابشن النشر.','design-guide')
rule('خلفية قالب التجميل|لون خلفية التجميل|خلفية الصورة المولّدة','اختار الخلفية المناسبة للهوية ونوع القالب، ثم راجع تباين النص وحدود الصورة.','design-guide')
rule('كود HEX','اكتب كود لون بصيغة مثل #0F369D. الكود يحدد لون العنصر، وراجع الهوية والتباين في المعاينة.','design-guide')
rule('نوع اللون','اختار لونًا ثابتًا أو تدرجًا حسب الخيارات. التدرج يحتاج ألوانًا واتجاهًا مناسبين للعنصر.','design-guide')
rule('زاوية الجريدينت بالدرجات|زاوية جريدينت العنوان','زاوية اتجاه التدرج بالدرجات، وليست دوران النص نفسه. راجع بداية اللون ونهايته في المعاينة.','design-guide')
rule('لون العنوان الرئيسي','اختار لون العنوان الرئيسي مع الحفاظ على وضوحه فوق الخلفية وهوية الصفحة.','design-guide')
rule('ظهور الكتلة|قوة اللون %','تحكم في ظهور الكتلة أو قوة اللون حسب النسبة المعروضة. راجع النتيجة في المعاينة قبل التصدير.','design-guide')
rule('طول الكتلة بالبكسل','حدد امتداد كتلة اللون بالبكسل في التصميم، ثم راجع عدم تغطية النص أو الصورة.','design-guide')
rule('اتجاه التوسيع','اختار الجهة التي ستُستكمل فيها الصورة عند توسيعها. راجع الحدود والأجزاء المضافة قبل استخدام الناتج.','design-guide')
rule('المعلومات الحالة أو الرسالة|معلومات الحالة أو الرسالة','اكتب سياق المادة أو الرسالة المراد شرحها، مع بيانات عامة وإذن استخدام الصور. لا تضف هوية مريض في توجيه التوليد.','design-guide')
rule('عدد الشرايح','حدد عدد شرائح الكاروسيل المطلوب. طابق العدد مع النص والفكرة وراجع ترتيب البداية والنهاية.','carousel-guide')
rule('أسلوب الكاروسيل','اختار طريقة عرض الفكرة على الشرائح حسب القالب المتاح، ثم راجع ترابط الرسالة بينها.','carousel-guide')
rule('نص كل شريحة (اختياري — سطر لكل شريحة، أو سيبه فاضي والوكيل يكتبه)','اكتب كل شريحة في سطر منفصل بالترتيب. إذا تركته فارغًا وفق الاختيار، سيجهز الوكيل النص وتراجعه قبل الاعتماد.','carousel-guide')
rule('كلمة التصنيف (فوق العنوان)','اكتب التصنيف القصير الذي يظهر أعلى عنوان الكفر، مثل اسم السلسلة أو نوع المحتوى.','design-guide')
rule('الكلمة الملوّنة في العنوان','اكتب الكلمة من العنوان التي تريد إبرازها بلون مختلف. راجع أن نفس الكلمة موجودة في نص العنوان.','design-guide')
rule('طريقة الإنتاج','اختار المسار المطلوب لإنتاج المادة مثل استخدام ملفات مرفوعة أو التوليد حسب القائمة. راجع ما يتطلبه كل مسار قبل البدء.','video-guide')
rule('موسيقى الفيديو','اختار إعداد الموسيقى المتاح، وراجع مستوى الصوت وحق الاستخدام وألا تطغى على التعليق الصوتي.','video-guide')
rule('الانتقالات|الانتقال بين الصور','اختار طريقة الانتقال بين المشاهد، ثم راجع توقيتها مع الصوت والمدة.','video-guide')
rule('حركة الصور|حركة الصورة','اختار حركة الصورة داخل المشهد مثل التكبير أو التحريك إن كان متاحًا. راجع ألا تقص الجزء المطلوب.','video-guide')
rule('مصدر المشاهد|مصدر المشهد','اختار هل المشهد من ملفاتك أو صورة أو فيديو مولد حسب الخيارات. كل مصدر يحتاج مدخلاته قبل الإنتاج.','video-guide')
rule('إطار مقطع الفيديو','حدد طريقة احتواء الفيديو داخل الإطار، وراجع القص والمساحات الفارغة في المعاينة.','video-guide')
rule('بداية مقطع الفيديو بالثواني','اكتب الثانية التي تريد بدء الجزء المستخدم عندها من الفيديو المرفوع، مثل 5. لا تتجاوز مدة الملف.','video-guide')
rule('مدة المقطع المولد|مدة اللقطة','حدد مدة اللقطة حسب خيارات التوليد، ثم راجع اتساقها مع مدة الصوت والمشهد.','video-guide')
rule('الحد الشهري (ج.م)|الميزانية الشهرية بالدولار','حدد سقف ميزانية التوليد للشهر بالعملة المكتوبة في الحقل. هذا حد رقابي للتكلفة، ولا يضيف رصيدًا لحساب مزود الخدمة.','video-guide')
rule('سعر الدولار (ج.م)','اكتب سعر التحويل المستخدم لحساب تكلفة التوليد بالجنيه لكل دولار وفق سياسة المركز. هذا إعداد تكلفة وليس سعر بيع خدمة للمريض.','video-guide')
# Patient records: these instructions describe documentation, not diagnosis or treatment advice.
rule('الاسم بالكامل|الاسم زي ما هيتطبع','اكتب اسم المريض بعد مطابقته مع ملفه ومستنده. راجع تهجئة الاسم قبل حفظ أو طباعة التقرير؛ لا تنشئ ملفًا ثانيًا لتصحيح حرف.','patient-records')
rule('رقم الهاتف|رقم الهاتف|تليفون المركز|واتساب','اكتب رقم التواصل الصحيح مع كود الدولة إذا طلبه النموذج. راجع صاحب الرقم والغرض منه، فقد تستخدم الأسرة رقمًا واحدًا لأكثر من مريض.','patient')
rule('البريد الإلكتروني|الإيميل','اكتب عنوان البريد بصيغته مثل name@example.com حسب صاحب السجل. راجع صحته قبل الحفظ لأنه قد يستخدم للتواصل أو الدخول.','access')
rule('الرقم القومي (اختياري)','سجل رقم الهوية للمريض الصحيح عند وجوده وفق صلاحية النموذج. لا تستخدم رقمًا وهميًا لإكمال الحقل ولا تضع رقم ولي الأمر بدل المريض.','patient-records')
rule('السن','اكتب عمر المريض بالوحدة المطلوبة في النموذج، ولا تستخدم تاريخ الزيارة أو رقم الملف بدل العمر. راجع توافقه مع تاريخ الميلاد إن كان مسجلًا.','patient-records')
rule('النوع','اختار النوع الصحيح للسجل وفق قائمة النموذج. في ملف المريض المقصود بيانات المريض، وفي طلب مالي المقصود نوع العملية.','patient-records')
rule('الرقم الطبي|الرقم الطبي (اختياري)','اكتب الرقم الطبي الخاص بالمريض وفق سجلات المركز. يختلف عن رقم الهوية وعن رقم زيارة منفردة. ابحث عن الملف الموجود قبل إضافة رقم جديد.','patient-records')
rule('جهة التعاقد (اختياري)|جهة التعاقد لهذه الزيارة','اختار الجهة التي ينطبق عقدها على المريض أو الزيارة المعنية، وراجع سريان العقد وأهلية الخدمة قبل استخدام سعر التعاقد.','entities')
rule('تاريخ آخر زيارة','سجل تاريخ آخر زيارة فعلية وفق الملف، وليس تاريخ تحديث البيانات. راجعه مع الزيارات المسجلة.','patient-records')
rule('الأمراض المزمنة|الحالة المزمنة|هل تعاني من أمراض مزمنة؟|أمراض مزمنة','سجل الأمراض المعروفة كما أفاد المريض أو أثبتها الطبيب مع التفاصيل المتاحة. لا تحول عرضًا غير مشخص إلى مرض مؤكد.','patient-records')
rule('العمليات الجراحية','سجل العمليات السابقة وتواريخها إن توفرت وفق الإفادة أو المستند. إذا لم تتوفر المعلومة فوضّح ذلك حسب النموذج.','patient-records')
rule('تاريخ مرضي بالعائلة','سجل الحالات العائلية ذات الصلة كما وردت في الإفادة، مع صلة القرابة إن كانت معلومة، دون وضعها كتشخيص للمريض.','patient-records')
rule('تاريخ الزيارة','حدد تاريخ الزيارة الطبية التي تخصها البيانات. تعديل السجل اليوم لا يغيّر تاريخ الزيارة الأصلية تلقائيًا.','patient-records')
rule('الشكوى|الشكوى (Chief Complaint)|سبب الزيارة|سبب الحضور والشكوى الأساسية|المشكلة الأساسية|الأعراض أو المشكلة الحالية','دوّن سبب حضور المريض وأعراضه بلغته مع البداية والمدة إذا توفرت. هذا وصف للشكوى، أما التشخيص فيسجله المختص في حقله.','patient-records')
rule('ضغط الدم','سجل قراءة ضغط الدم التي قاسها المختص كما هي بوحدة النموذج، مع الانقباضي والانبساطي عند طلبهما. لا تدخل قراءة تقديرية أو قيمة لتجاوز الحقل.','patient-records')
rule('سكر الدم','سجل نتيجة القياس الفعلية ووحدتها ووقت/حالة القياس إن طلبها النموذج، مثل صائم أو عشوائي. لا تضع تشخيصًا أو تعدل النتيجة بالتخمين.','patient-records')
rule('النبض','سجل معدل النبض المقاس بالدقيقة وفق الفحص. اترك غير المقاس وفق قواعد النموذج بدل تسجيل صفر كأنه نتيجة.','patient-records')
rule('الوزن','سجل الوزن المقاس بالكيلوجرام حسب النموذج وتاريخ القياس. لا تستخدم الوزن المستهدف بدل الوزن الحالي.','patient-records')
rule('الطول','سجل الطول المقاس بالسنتيمتر حسب النموذج، مثل 170. راجع الوحدة قبل حساب أي مؤشر مشتق منه.','patient-records')
rule('نسبة الأكسجين','سجل نسبة تشبع الأكسجين المقاسة كما ظهرت في جهاز القياس، مع تفاصيل القياس عند طلبها. هذه خانة توثيق وليست تفسيرًا للنتيجة.','patient-records')
rule('نسبة الدهون','سجل النسبة المقاسة وتاريخها وفق النموذج والطريقة المتاحة. لا تستخدم الوزن بالكيلوجرام مكان النسبة المئوية.','patient-records')
rule('خطة الأدوية|الأدوية|الروشتة|ملاحظات دوائية إضافية|أدوية نفسية سابقة أو حالية','انقل خطة الطبيب أو قائمة الأدوية الموثقة مع الاسم والتركيز والجرعة والتكرار والمدة في حقولها. لا تقترح جرعة أو تستنتج علاجًا من الشكوى.','patient-records')
rule('الأشعة|التحاليل|توصيات أخرى','سجل طلب الطبيب أو التوصية المعتمدة، واربط المستند إن توفر. طلب الفحص يختلف عن رفع نتيجة الفحص أو تفسيرها.','patient-records')
rule('تاريخ المتابعة|يوم المتابعة|وقت المتابعة|موعد الجلسة القادمة','حدد موعد المتابعة المتفق عليه بالتاريخ والوقت في حقليهما. راجع جدول الحجز إن كان مطلوبًا حجز موعد فعلي؛ كتابة توصية متابعة لا تحجزه وحدها.','patient-records')
rule('في حالة تأجيل الموعد، اختر السبب','اختار السبب الذي أدى لتأجيل المتابعة فعلًا من القائمة، وسجل التفاصيل المطلوبة قبل تأكيد التعديل.','patient-records')
rule('كل|وحدة|لمدة|البداية|الساعة','هذه خانات تكرار أو توقيت بحسب النموذج. في جدول دواء انقل عدد الفواصل ووحدتها والمدة وبداية الخطة والساعة من تعليمات الطبيب. وفي تكرار مهمة انقل إعداد التكرار المطلوب، ولا تستخدم نفس القيم للسياقين.','patient-records')
rule('الفئة','اختار تصنيف السجل حسب الشاشة. في رفع مستند مريض مثل أشعة أو تحاليل أو تقرير، وفي المخزن تصنيف الصنف. التصنيف يساعد الفلترة ولا يغير محتوى الملف.','patient-records')
rule('الملف','اختار المستند الذي يخص السجل والمريض الصحيحين، وراجع اسمه وامتداده قبل الرفع. رفع الملف يحفظ مرفقًا ولا يعني اعتماد محتواه.','patient-records')
rule('تاريخ إصدار المستند (اختياري)|تاريخ التقرير|تاريخ الروشتة|تاريخ الطلب','اكتب التاريخ الموجود على المستند أو الطلب المعني، وليس تاريخ رفع الملف إذا كان مختلفًا.','patient-records')
rule('ملاحظات / تفاصيل الملف (اختياري)','اكتب وصفًا يساعد على تمييز المرفق، مثل نوع الفحص وتاريخه، دون تكرار بيانات حساسة لا يحتاجها الوصف.','patient-records')
rule('التخصص (اختياري — لتمييز التقارير لو أكتر من تقرير لنفس المريض)|التخصص (اختياري)','حدد تخصص التقرير أو الطبيب حتى يمكن تمييزه عن تقارير المريض الأخرى. اتركه فارغًا إذا كان اختياريًا وغير معروف.','patient-records')
rule('نص التقرير|Summary|Conclusion','انقل نص التقرير أو ملخصه أو خلاصة الطبيب في الخانة المقابلة. راجع مصدر النص والطبيب والتاريخ، ولا تكتب استنتاجًا طبيًا بدل المستند.','patient-records')
rule('التشخيص (اختياري)|التشخيص المبدئي (اختياري)|Diagnosis (تشخيص الحالة بشكل عام)|التشخيص (الحالة اللي الجدول ده مناسب لها)','سجل التشخيص الذي وثقه المختص، وميّز المبدئي من المعتمد حسب عنوان الحقل. لا تستنتج تشخيصًا لإكمال النموذج.','patient-records')
rule('Others (اختياري)','اكتب الفحص أو الطلب الإضافي الذي حدده الطبيب ولم تجده ضمن الخيارات. لا تكرر فحصًا سبق اختياره في القائمة.','patient-records')
rule('كومنت العميل (اختياري)','سجل تعليق المريض أو العميل كما ورد مع الحفاظ على معناه. ميّزه عن ملاحظة الطبيب أو تشخيصه.','patient-records')
rule('Referred By','اسم الطبيب أو الجهة التي أحالت المريض كما ورد في مستند الإحالة. لا تستخدم اسم من سجل البيانات بدل جهة الإحالة.','patient-records')
rule('Dimensions','سجل القياسات المطلوبة في التقرير مع وحداتها حسب الفحص ونتيجته الأصلية. لا تضع وصفًا عامًا مكان القياسات أو تحول الوحدات بالتخمين.','patient-records')
rule('صور الأشعة المرفقة (عدد مفتوح — اختار كذا صورة مرة واحدة)|أشعة الأسنان المرفقة (عدد مفتوح — اختار كذا صورة مرة واحدة)|صور أشعة/فحوصات مرفقة (عدد مفتوح — اختار كذا صورة مرة واحدة)|مستندات مرفقة','ارفع الصور أو المستندات التي تخص هذا التقرير والمريض. يمكنك تحديد عدة ملفات إذا سمح الحقل. راجع وضوح الصور وتاريخها قبل الحفظ.','patient-records')
rule('علاج الأسنان السابق','سجل إجراءات الأسنان السابقة ذات الصلة كما وردت في الملف أو إفادة المريض، مع التواريخ المتاحة.','patient-records')
rule('خطة العلاج المقترحة|الهدف من العلاج','سجل الخطة أو الهدف الذي حدده المختص بعد التقييم، وليس وعدًا بنتيجة مؤكدة. راجع ربطها بالزيارة والجلسات المعنية.','patient-records')
rule('التركيبة (ثابتة / متحركة)','سجل نوع التركيبة المعتمد في خطة الأسنان والموضع والتفاصيل إن طلبها النموذج. لا تختار نوعًا بدل قرار الطبيب.','patient-records')
rule('مخطط الأسنان (اضغط على السن لتحديد مكانه)','اختار السن أو الموضع الذي حدده طبيب الأسنان على الرسم، ثم سجل الإجراء أو الملاحظة المطلوبة. راجع الجهة والرقم قبل الحفظ.','patient-records')
rule('جدول الجلسات','أدخل الجلسات المعتمدة وترتيبها وتواريخها وحضورها حسب الخطة. الجدول الطبي يختلف عن التحصيل أو إثبات تنفيذ خدمة مالية.','patient-records')
rule('نقاط الألم (اضغط على الرسم لتحديد مكان الألم)','حدد المواضع التي وصفها المريض أو سجلها المختص على الرسم، مع الجهة والدرجة إن طلبهما النموذج. الرسم توثيق لمكان الألم ولا يثبت تشخيصًا.','patient-records')
rule('اسم الجدول','اكتب اسمًا يميز قالب أو جدول الخطة، مثل اسم خطة وجبات أو جلسات. لا تضع رقم ملف مريض كاسم لقالب مشترك.','patient-records')
rule('الوجبات|جدول الوجبات (Daily Meals)','انقل الوجبات والكميات والتوقيتات من خطة أخصائي التغذية في صفوفها. راجع أن الخطة تخص الزيارة الحالية قبل حفظ نسخة المريض.','patient-records')
rule('التوقيت','اكتب توقيت الزيارة أو الوجبة حسب عنوان النموذج. راجع هل الحقل يطلب ساعة أم تاريخًا مع ساعة قبل الحفظ.','patient-records')
rule('تاريخ أول جلسة','اكتب تاريخ بداية الجلسات الفعلية أو المتفق عليها حسب النموذج، وليس تاريخ إنشاء الملف إذا كان مختلفًا.','patient-records')
rule('متى بدأت المشكلة؟','سجل تاريخ أو عمر بداية المشكلة كما أفاد المريض أو ولي الأمر، ووضّح إذا كانت البداية تقريبية.','patient-records')
rule('نوع المشكلة','حدد تصنيف المشكلة من اختيارات التقييم حسب ما سجله المختص. استخدم التفاصيل لتوضيح الاختيار بدل اختيار تشخيص غير مؤكد.','patient-records')
rule('تفاصيل أخرى|تفاصيل تدخل آخر','اكتب التفصيل الذي لا تغطيه الخيارات في هذا الجزء من التقييم، مع توضيح ما حدث أو التدخل الذي وثقه المختص.','patient-records')
rule('هل يوجد تاريخ زواج أقارب؟|هل يوجد أمراض أو اضطرابات وراثية بالعائلة؟|هل حدثت مشاكل أثناء الحمل أو الولادة؟','سجل الإجابة من إفادة ولي الأمر أو المستند، ثم التفاصيل المتاحة. عدم معرفة المعلومة لا يساوي إجابة «لا».','patient-records')
rule('تطور الكلام واللغة: أول كلمة|أول جملة','سجل العمر أو التاريخ الذي ظهرت فيه أول كلمة أو جملة حسب إفادة ولي الأمر، مع توضيح التقريب أو عدم المعرفة.','patient-records')
rule('هل سبق له جلسات تخاطب؟|هل سبق علاج أو جلسات؟','سجل وجود علاج أو جلسات سابقة مع النوع والمدة والنتيجة الموثقة إن توفرت، دون اعتبارها خطة الجلسة الحالية.','patient-records')
rule('مستوى الفهم والكلام حاليًا','سجل ملاحظات التقييم الحالي كما وثقها أخصائي التخاطب، مع أمثلة إن لزم. لا تستنتج مستوى من السن وحده.','patient-records')
rule('الهدف من الجلسات|أهداف الجلسة|هدف الجلسة','سجل الهدف الذي يعمل عليه المختص في الخطة أو هذه الجلسة تحديدًا، بحيث يمكن مقارنة التنفيذ والاستجابة لاحقًا.','patient-records')
rule('ملاحظات الأخصائي','سجل الملاحظات المهنية التي وثقها المختص وربطها بتاريخ التقييم أو الجلسة. ميّزها عن إفادة ولي الأمر.','patient-records')
rule('عدد الجلسات المخطط لها','اكتب عدد الجلسات المعتمدة في الخطة، وليس عدد الجلسات التي حضرها المريض بالفعل أو عدد الدفعات.','patient-records')
rule('الجلسة|رقم الجلسة','اكتب ترتيب الجلسة داخل الخطة الطبية حسب التسلسل المسجل. هذا يختلف عن رقم ملف المريض وعن رقم إيصال السداد.','patient-records')
rule('موعد الجلسة','حدد تاريخ ووقت الجلسة المقصودة وراجع التواجد والحجز إذا لزم. التسجيل في التقرير وحده لا يؤكد موعدًا في نظام الحجز.','patient-records')
rule('مدة الجلسة','سجل المدة المطلوبة بوحدة الحقل. عند توثيق جلسة منفذة اكتب مدتها الفعلية بدل مدة الخطة إذا اختلفتا.','patient-records')
rule('مستوى الاستجابة|مستوى التحسن','اختر التقييم الذي سجله المختص لهذه الجلسة مع دليل أو ملاحظة تفسره. لا تستخدم التقييم كضمان لنتيجة مستقبلية.','patient-records')
rule('ما تم التدريب عليه|التدخل المستخدم','سجل الأنشطة أو التدخلات التي نفذها المختص بالفعل في الجلسة. ميّز بين المنفذ وبين المخطط للجلسة القادمة.','patient-records')
rule('الواجب المنزلي','دوّن التدريب أو التعليمات المنزلية التي اعتمدها المختص بصيغتها، مع التكرار والمدة إذا حددهما.','patient-records')
rule('حضور الجلسة','اختر حالة الحضور الفعلية مثل حضر أو غاب حسب النموذج. لا تعتبر مجرد الحجز حضورًا أو جلسة منفذة.','patient-records')
rule('نوع الجلسة|نوع الزيارة / الخدمة|نوع الزيارة','حدد نوع الزيارة أو الجلسة التي يوثقها هذا السجل وفق القائمة، ثم أكمل النموذج المناسب لها.','patient-records')
rule('سبب الحجز','اكتب سبب طلب الموعد أو الجلسة كما ورد، مع تمييزه عن تشخيص المختص بعد التقييم.','patient-records')
rule('أهم الضغوط أو الظروف الحالية|تأثير المشكلة على الحياة','وثق ما وصفه المريض عن الظروف الحالية أو تأثير الأعراض على حياته في حدود التقييم المطلوب. سجل وقائع وإفادة، ولا تضف تفسيرًا غير موثق.','patient-records')
rule('التزام العميل','سجل الالتزام الذي تم ملاحظته أو الإبلاغ عنه بالخطة أو الواجبات، مع ملاحظة توضح الأساس بدل تقييم بلا دليل.','patient-records')
rule('خطة الجلسة القادمة','سجل الخطوات التي حددها المختص للجلسة التالية بعد مراجعة ما نُفذ واستجابة المريض. هذه خطة وليست إثبات تنفيذ.','patient-records')

rule('الخزينة|اسم الخزينة','اختر الخزينة التي تخص المبلغ والمكان ونوع الحركة، أو اكتب اسمًا يميز الخزينة عند إنشائها. راجع صلاحيتها للاستلام أو الصرف والوردية المرتبطة.','cash-shifts-guide')
rule('وردية الاستقبال المفتوحة|وردية الكاش أو الفيزا|الوردية النقدية|وردية الكاش','اختر وردية مفتوحة للمستخدم والخزينة المناسبة. الكاش والفيزا يحتاجان وردية بحسب المسار، وعدم ظهور وردية لا يعالج بإدخال معرّف يدوي.','cash-shifts-guide')
rule('حد النثريات للإذن','أقصى مبلغ يسمح به حد النثريات لهذا النوع من الصرف حسب الإعداد. الحد لا يضيف كاشًا للخزينة ولا يغني عن وجود رصيد واعتماد.','cash-shifts-guide')
rule('حركات الخزينة|نوع الحركة','حدد هل الخزينة تستلم فقط أو تصرف فقط أو الاثنين حسب خياراتها. التحصيل والصرف يجب أن يتوافقا مع هذا الإعداد.','cash-shifts-guide')
rule('ملاحظات الجرد|ملاحظة الفروق|نتيجة المراجعة وتفسير الفرق','دوّن نتيجة العد والفرق بين الفعلي والدفتر وسبب الفرق أو ما يحتاج مراجعة. الفرق لا يثبت وحده مسؤولية موظف ولا يتحول تلقائيًا لخصم راتب.','cash-shifts-guide')
rule('الكاش المعدود فعليًا','اكتب النقد الموجود بعد العد الفعلي بالجنيه، لا الرصيد الذي تتوقعه من الشاشة. النظام يقارن العد بالحركات لإظهار الفرق للمراجعة.','cash-shifts-guide')
rule('الإقفال حتى تاريخ','حدد آخر تاريخ تريد إقفاله محاسبيًا بعد مراجعة العمليات. الإقفال قد يمنع قيودًا أو تصحيحات داخل الفترة، فلا تستخدم تاريخًا مستقبليًا لإخفاء فرق.','ledger-guide')
rule('المبلغ بالجنيه|القيمة بعد الخصم بالجنيه','اكتب قيمة هذه العملية بالجنيه بعد مراجعة المستحق أو المبلغ المعتمد. إذا كان سدادًا جزئيًا أدخل الجزء المدفوع فقط، ولا تكرر تحصيلًا سبق تسجيله.','collections')
rule('قيمة الخدمة بعد الخصم دون المستلزمات|سعر الخدمة (بدون مستلزمات)','اكتب قيمة الخدمة نفسها بعد الخصم وفق المستند، مع استبعاد المستلزمات التي لها بنود مستقلة. راجع ألا تحتسب نفس المستلزم داخل الخدمة وخارجها مرتين.','invoice')
rule('رقم الإيصال أو مرجع العملية|رقم الإيصال / مرجع العملية|مرجع إيصال / تحويل فريد|مرجع السداد أو التحويل','رقم بيميّز الدفعة ومينفعش يتكرر. في النقدي بيتكتب لوحده (RC-تاريخ-وقت)، ولو عندك إيصال ورقي مرقّم اكتب رقمه بداله. في الفيزا اكتب رقم العملية من إيصال الماكينة، وفي إنستا باي أو التحويل أو المحفظة اكتب رقم العملية من رسالة التحويل.','collections')
rule('مرجع الفاتورة|مرجع الفاتورة من نظام المركز','اكتب مرجع الفاتورة الأصلية التي تمثل الخدمة في نظام المركز كما هو. لا تستخدم رقم إيصال تحصيل أو رقم مريض بدل رقم الفاتورة.','invoice')
rule('مرجع المريض|مرجع المريض فقط|مرجع المريض الذي سيُستخدم على الفاتورة|معرف الملف المختار','اختر أو انقل مرجع ملف المريض المقصود من سجله وفق النموذج. طابق رقم الملف والاسم، ولا تضع اسمًا حرًا إذا كان الحقل يطلب معرّف الملف.','patient')
rule('رقم ملف المريض|رقم ملف التجربة','اكتب رقم الملف المقصود حسب مساحة التشغيل. ملف التجربة منفصل عن الأرشيف الحقيقي، ورقم الملف يختلف عن الهاتف وعن رقم الزيارة.','patient')
rule('الخدمة المستحقة|الخدمة غير المحصلة|الفاتورة وحصة غير محصلة|فاتورة الخدمة المنفذة','اختر مستند الخدمة أو الفاتورة الذي توجد عليه المديونية أو الحصة المطلوبة فعلًا. راجع المريض والمبلغ المتبقي قبل ربط التحصيل أو المعالجة به.','invoice')
rule('الفاتورة|الزيارة','اختر الفاتورة أو الزيارة المرتبطة بالمريض والإجراء الحالي. راجع الرقم والتاريخ، ولا تربط مستلزمًا أو دفعة بزيارة أخرى لنفس المريض.','invoice')
rule('التحصيل الأصلي للاسترداد','اختر إيصال التحصيل الذي سيتم رد جزء منه أو كله. حدود الاسترداد تعتمد على الأصل وما سبق رده، وليس على المبلغ المكتوب في طلب جديد وحده.','requests')
rule('الخدمة المطلوب إلغاؤها','اختر الخدمة التي ستلغيها فعلًا، وراجع هل نُفذت أو حُصلت قبل طلب الإلغاء لأن الأثر المالي يختلف حسب الحالة.','requests')
rule('سبب الطلب|سبب الاسترداد|سبب الطلب / بيان المستند|السبب|السبب (مطلوب)|شرح المستند وسبب العملية|السبب والمستند','اكتب الحدث الذي يستدعي الطلب وسببه والمستند الذي يثبته، مثل رد دفعة عن موعد ملغي. لا تكتب سببًا عامًا لا يسمح للمراجع بفهم العملية.','requests')
rule('مرجع مستند الصرف أو التمويل أو الاسترداد|مرجع الاستخدام / الاسترداد|مرجع المستند|مرجع المستند الفريد|رقم المستند|مرجع التحويل / المستند','اكتب مرجع المستند الحقيقي الذي يثبت هذه العملية. إذا كان المرجع فريدًا فلا تعِد استخدامه لحدث مختلف، وراجع المستند قبل الإرسال للمراجعة.','requests')
rule('سبب القرار|سبب القرار وفحص المستند|نتيجة فحص المستند|نتيجة فحص المستند والحساب|نتيجة فحص المستند والأرصدة|سبب القرار ونتيجة المراجعة|نتيجة المراجعة والأدلة|نتيجة المراجعة والإجراء التالي','اكتب نتيجة ما راجعته ولماذا اعتمدت أو رفضت، مع الإشارة للمستند أو الفرق والإجراء التالي. المراجعة تحتاج حسابًا مستقلًا إذا اشترط المسار ذلك.','requests')
rule('حجز مرتبط — اختياري|الحجز|الحجز قبل الحضور','اختر الحجز الذي تخصه الدفعة أو الرسالة أو الإجراء. إذا كان النموذج يشترط قبل الحضور فلا تستخدم حجزًا بدأ له تنفيذ زيارة.','booking-flow')
rule('النتيجة بعد فحص القناة|دليل فحص القناة ومرجع المراجعة','سجل نتيجة فحص وسيلة التحصيل ودليلها قبل اتخاذ القرار، خصوصًا إذا كانت حالة وصول الدفعة غير مؤكدة. لا تعتبر تجهيز الرسالة أو طلب الدفع دليل تحصيل.','collections')
rule('مرجع كشف الحساب أو مستند الفحص|مرجع خطاب التأمين أو التحويل البنكي','اكتب مرجع الكشف أو خطاب الجهة أو التحويل الذي يؤيد المبلغ والمعالجة، بعد مطابقته بالمريض أو المطالبة أو الحركة المقصودة.','insurance')
rule('مرجع الرسالة أو ملاحظة الإرسال','سجل مرجع الرسالة أو ملاحظة ما حدث فعليًا بالقناة. تجهيز رسالة أو فتحها لا يثبت الإرسال أو التسليم.','communications-guide')
rule('مرجع مستند شركة التحصيل|مرجع الكشف','اكتب رقم أو اسم المستند أو فترة كشف البنك/شركة التحصيل التي ستطابقها، بحيث يمكن الرجوع لنفس المصدر لاحقًا.','bank')
rule('إجمالي العملية قبل العمولة','اكتب إجمالي التسوية قبل خصم عمولة الجهة. راجع أن الصافي المحول للبنك والعمولة يساويان الإجمالي، ولا تدخل الصافي في خانة الإجمالي.','bank')
rule('العمولة حسب المستند','اكتب مبلغ العمولة الفعلي من مستند التسوية، وليس نسبة تخمينية أو إجمالي التحصيل.','bank')
rule('الحركة الدفترية غير المطابقة','اختر القيد أو الحركة الموجودة التي تقابل سطر كشف البنك وتحتاج مطابقة. لا تسجل تحصيلًا جديدًا لمجرد أن الحركة ظهرت في الكشف.','bank')
rule('سطور الكشف: التاريخ، المرجع، المبلغ. سطر لكل حركة؛ الداخل موجب والخارج سالب.','أدخل كل حركة في سطر مستقل بصيغة التاريخ ثم المرجع ثم المبلغ كما يطلب النموذج. الداخل موجب والخارج سالب. راجع الأرصدة والفترة قبل المطابقة.','bank')
rule('تاريخ الاستحقاق حسب العقد|استحقاق المطالبة إن لزم','حدد موعد استحقاق المبلغ وفق الاتفاق أو المطالبة، وليس تاريخ التحصيل المتوقع بالتخمين أو تاريخ اليوم تلقائيًا.','insurance')
rule('مجموعة المطالبات / الشهر','اكتب مرجع الدفعة أو شهر المطالبات الذي يجمع المستندات المقصودة للتقديم والمتابعة مع الجهة.','insurance')
rule('نتيجة الاتصال أو التصحيح والمستند المرجعي|نتيجة الإجراء وأدلته','سجل ما حدث فعليًا في التواصل أو التصحيح، وما المستند الذي يؤيده، والمرحلة التالية. لا تسجل وعدًا بالسداد كأنه تحصيل.','insurance')
rule('شركة التأمين|شركة التأمين للافتتاح إن لزم','اختر الجهة صاحبة المطالبة أو الرصيد، مع مطابقة العقد والمريض والمستند. لا تجمع جهات مختلفة في افتتاح تفصيلي واحد.','insurance')
rule('سبب المعالجة وأدلتها','اكتب سبب الرفض أو التخفيض والدليل الذي يحدد نوع المعالجة. تصحيح المطالبة يختلف عن التخفيض التعاقدي وخسارة الائتمان.','insurance')
rule('الموظف المسؤول عند ثبوت مسؤوليته','اختر الموظف فقط بعد أن تثبت المراجعة مسؤوليته بالقرار والأدلة. وجود فرق نقدي وحده لا يبرر تحميله على الموظف.','cash-shifts-guide')
rule('اسم الموظف|الموظف','اختر الموظف الذي يخصه التكليف أو العقد أو الاستحقاق أو الفلترة. في مستحقات الرواتب طابق الاسم بالعقد والفترة ولا تستخدم اسم مسجل الطلب بدل المستفيد.','payroll')
rule('عقد الموظف المعتمد','اختر عقد العامل المعتمد والساري الذي يخص شهر الراتب أو الاستحقاق. وجود مسودة عقد لا يكفي لاحتساب مستحق معتمد.','payroll')
rule('الضريبة المستقطعة حسب المستند','اكتب قيمة الاستقطاع من مستند التسوية المعتمد. صافي السداد يساوي الإجمالي ناقص الاستقطاع، فلا تخصمه مرتين.','payroll')
rule('العمر الإنتاجي بالأشهر','اكتب مدة استخدام الأصل المحاسبية المعتمدة بالأشهر، مثل 60 إذا كان العمر خمس سنوات. لا تستخدم عدد أقساط شراء الأصل بدل عمره الإنتاجي.','assets-tax')
rule('تاريخ بدء التشغيل والإهلاك','حدد تاريخ بدء استخدام الأصل الذي تعتمد عليه خطة الإهلاك، وليس بالضرورة تاريخ سداد ثمنه. راجع المستند والسياسة المعتمدة.','assets-tax')
rule('عدد أشهر الإهلاك السابقة','للأصل القديم اكتب عدد الأشهر التي أُهلكت قبل إدخاله مع مراجعة تكلفة الأصل ومجمعه، حتى لا يبدأ الإهلاك من الصفر مرة أخرى.','assets-tax')
rule('الأصل المعتمد','اختر الأصل الذي اعتمدت بياناته وتخصه دورة الإهلاك أو العملية. راجع كوده وتاريخ بدء استخدامه قبل التنفيذ.','assets-tax')
rule('شهر الإهلاك التالي','حدد شهر الفترة التي سيتم حساب إهلاكها حسب تسلسل الأصل، وتأكد من عدم احتساب شهر سبق ترحيله.','assets-tax')
rule('المعالجة حسب المستند|الالتزام الضريبي المعتمد|الالتزام','اختر الالتزام الضريبي أو اتجاه المعالجة وفق المستند المعتمد، وراجع هل العملية إثبات أم سداد أم تسوية. السداد لا ينشئ نفس المصروف مرة أخرى.','assets-tax')
rule('قناة الصرف|وسيلة الصرف أو التحصيل','اختر الوسيلة المستخدمة فعليًا للمال وفق الإجراء، ثم أكمل الوردية أو مرجع التحويل المطلوب. لا تختار نقدي لعملية تمت من البنك.','collections')
rule('نوع العملية|الإجراء','حدد الإجراء أو نوع الحركة من خيارات النموذج، واقرأ أثره والمستند الذي يتطلبه قبل الحفظ أو الاعتماد. الاختيار لا ينفذ العملية وحده.','ledger-guide')
# owner 2026-11-25 (help 276): plain labels in the finance «طلب جديد» modal
rule('عايز تعمل إيه؟','اختار نوع الطلب: سلفة لموظف، مرتب شهر، عقد موظف جديد… والعنوان والشرح بيتغيروا على حسب اختيارك.','finance-request-plain')
rule('رقم الورقة أو الإيصال','رقم بيتكتب لوحده ومايتكررش. لو معاك رقم إيصال أو فاتورة حقيقي اكتبه بداله.','finance-request-plain')
rule('مرتب شهر','الشهر اللي المرتب ده بتاعه.','finance-request-plain')
rule('هيشتغل كام شهر','عدد الشهور اللي الجهاز أو الأصل هيفضل شغال فيها، علشان تكلفته تتوزع عليها.','finance-request-plain')
rule('بدأ يشتغل من','اليوم اللي الجهاز بدأ يتستخدم فيه.','finance-request-plain')
rule('عدد الشهور اللي اتحسبت قبل كده','للجهاز القديم: كام شهر إهلاك اتحسب قبل ما يدخل السيستم.','finance-request-plain')
rule('الأصل','اختار الجهاز أو الأصل المتسجّل اللي هيتحسب له الإهلاك.','finance-request-plain')
rule('نوعها','ضريبة علينا ندفعها، ولا ضريبة هترجعلنا — زي ما مكتوب في الورقة.','finance-request-plain')
rule('الضريبة اللي هتتدفع','اختار الضريبة المتسجلة والمعتمدة اللي بتسددها دلوقتي.','finance-request-plain')
rule('بتدفع إيه؟','اختار اللي بتدفعه للجهة: ضرايب اتخصمت من الدكاترة، ضريبة الأجور، أو تأمينات الموظفين.','finance-request-plain')
rule('هيتصرف إزاي؟','تحويل بنكي، أو نقدي من ورديتك — النقدي بيظهر بس لو عندك وردية مفتوحة باسمك.','finance-request-plain')
rule('من وردية','الوردية المفتوحة باسمك اللي الفلوس هتطلع منها.','finance-request-plain')
# help 277: voucher modal plain labels
rule('الفلوس دي لإيه؟ (الحساب)','اختار الحساب اللي الفلوس رايحة له أو جاية منه، زي مصروف الكهربا أو جاري صاحب المركز. حسابات الدكاترة والموردين والبنك والمرتبات مش هتظهر هنا — ليها شاشاتها.','finance-today-plain')
rule('اسم اللي استلم أو سلّم الفلوس','اسم الشخص أو الجهة اللي أخدت الفلوس من الخزينة أو جابتها.','finance-today-plain')
rule('المبلغ (قبل خصم الضريبة)','المبلغ كله زي ما هو في الورقة، قبل ما تخصم أي ضريبة. الضريبة بتتكتب في خانتها.','finance-today-plain')
rule('ابحث باسم الدكتور','اكتب جزء من اسم الدكتور علشان القايمة تتصفّى عليه.','doctor-accounts-plain')
rule('سبب الرفض (٣ حروف على الأقل)','اكتب ليه رفضت المصروف (٣ حروف على الأقل). الرفض علامة للمتابعة بس ومش بيرجّع الفلوس ولا بيغيّر القيد.','shift-expenses-review')
rule('هامش مصروفات الوردية (ج.م)','أقصى إجمالي مصروفات الكاشير في الوردية الواحدة على الخزينة دي. صفر = كارت المصروفات مقفول.','shift-expenses-review')
rule('حد المصروف الواحد (ج.م)','أقصى مبلغ للمصروف الواحد. صفر = كارت المصروفات مقفول للخزينة دي.','shift-expenses-review')
rule('اكتب اسم المريض أو التليفون أو رقم الملف','دوّر على المريض باسمه أو تليفونه أو رقم ملفه علشان تفتح زيارته وتصلّح اللي فيها.','fix-visit')
rule('الحساب','اختر الحساب المقصود من قائمة هذه الشاشة. في القيد يكون حسابًا من الشجرة، وفي الإعلانات حسابًا إعلانيًا. راجع اسم القسم وكود الحساب قبل الاختيار.','ledger-guide')
rule('صاحب الرصيد إن لزم','حدد الطرف الذي يخصه الرصيد الافتتاحي أو التفصيلي، مثل المريض أو المورد حسب الحساب. القيد التجميعي وحده لا ينشئ أرصدة تفصيلية صحيحة للأطراف.','ledger-guide')
rule('مرجع العكس الفريد|سبب العكس والمستند','اكتب مرجعًا وسببًا واضحين لعكس القيد مع مستند التصحيح. العكس يحفظ الأصل، ولا يصحح مستند تشغيل من مسار آخر تلقائيًا.','ledger-guide')
rule('سطور القيد','أدخل حساب ومبلغ كل طرف في سطره، وراجع تساوي مجموع المدين والدائن والمستند والفترة. الحفظ مسودة، والترحيل يحتاج المراجعة المطلوبة.','ledger-guide')
rule('أمر الشراء','اختر أمر الشراء المعتمد الذي ستربط به الاستلام أو الفاتورة، وطابق المورد والأصناف والكميات بدل تسجيل شراء ثانٍ لنفس الطلب.','purchases')
rule('رقم فاتورة المورد|رقم فاتورة / إيصال المورد','انقل رقم فاتورة أو إيصال المورد كما هو على المستند. هذا الرقم يربط تكلفة التوريد وحساب المورد ويختلف عن كود التشغيلة.','purchases')
rule('تاريخ فاتورة المورد','اكتب التاريخ الموجود على فاتورة المورد، وميّزه عن تاريخ إنشاء الطلب أو دفع الحساب.','purchases')
rule('رابط الفاتورة إن وجد|رابط صورة أو ملف الفاتورة إن وجد','أرفق رابط المستند المسموح الوصول إليه للمراجعين، وتأكد أنه يفتح الفاتورة المقصودة ولا يكشف ملفات أخرى.','purchases')
rule('الصرف الأصلي للمريض','اختر حركة الصرف الأصلية التي تخص المريض والصنف المراد رده، حتى يرتبط المرتجع بالمخزون والفاتورة الصحيحين.','internal-issue')
rule('الاسترداد المالي المعتمد','اختر طلب الاسترداد الذي اعتمد بالفعل ويرتبط بالعملية المراد ردها. لا تستخدم طلبًا معلقًا كدليل سداد.','requests')
rule('سبب الطلب ونتيجة الفحص','اكتب سبب المرتجع أو الطلب وما أثبته فحص الصنف والمستند، مع الكمية وحالتها عند الحاجة، ثم أرسله للمراجعة.','purchases')
rule('بند المصروف','اختر التصنيف الحقيقي للمصروف، مثل كهرباء أو مياه أو غاز أو نفايات. التصنيف يحدد عرض التكلفة في التقارير، ولا يغني عن المستند والاعتماد.','requests')
rule('عقد الطبيب لهذه الفاتورة','اختر عقد الطبيب الساري والمعتمد الذي تنطبق شروطه على الخدمة بهذه الفاتورة. إذا لم ينطبق عقد فلا تربط عقدًا آخر لمجرد إكمال النموذج.','doctor-missing')
rule('النسبة المئوية|النسبة %','اكتب النسبة فقط مثل 25 وليس مبلغ الأتعاب. تراجع النسبة مع وعاء الحساب وشروط العقد قبل الاعتماد.','doctor-missing')
rule('وعاء النسبة بعد خصم المردودات','حدد المبلغ الذي تطبق عليه نسبة الطبيب حسب العقد بعد معالجة المردودات. الخدمة دون المستلزمات تختلف عن إجمالي الفاتورة بما فيها المستلزمات.','doctor-missing')
rule('مرجع العقد أو الملحق|رقم العقد','اكتب رقم العقد أو الملحق المعتمد الذي يثبت الشروط والفترة، حتى يمكن للمراجع الرجوع لنفس الاتفاق.','doctor-missing')
rule('بداية فترة الكشف|نهاية فترة الكشف|فترة المستحقات من','حدد الفترة التي تريد استخراج مستحقاتها، وليس موعد السداد. راجع الخدمات المنفذة والعقد والفترات التي سبق تسويتها.','payroll')

rule('الصنف|الصنف من المخزن|المستلزم','اختر الصنف أو تعريف المستلزم المقصود من القائمة، وطابق الاسم والكود ووحدة الصرف. وجود اسم مشابه لا يعني أنه نفس الصنف أو أن ربط التسعير اكتمل.','supply-map')
rule('كود الصنف|كود المستلزم|الكود','اكتب كودًا يميز الصنف أو السجل داخل النظام حسب عنوان النموذج. لا تستخدم رقم فاتورة المورد أو كود تشغيلة بدل الكود الثابت للصنف.','supply-map')
rule('اسم الصنف|الاسم','اكتب اسمًا يميز السجل المقصود في عنوان النموذج. للصنف اذكر وصفًا يفرقه عن الأحجام أو المقاسات الأخرى، وتجنب إنشاء نسخة ثانية من صنف موجود.','supply-map')
rule('نوع الوحدة (علبة/زجاجة/عبوة...)','اكتب اسم وحدة التسعير مثل قطعة أو علبة أو زجاجة. الاسم ليس عدد الوحدات، ويجب أن يتوافق مع عدد محتويات العبوة ومعامل ربط المخزن.','supply-map')
rule('الكمية بوحدة الصرف|العدد','اكتب الكمية بوحدة الصرف المكتوبة للصنف، لا عدد العبوات إذا كان المخزن بالقطعة. راجع معامل التحويل قبل التأكيد.','supply-map')
rule('كمية وحدة المخزن مقابل وحدة التسعير','عدد وحدات المخزن التي تخصم لكل وحدة تسعير. قطعة مقابل قطعة = 1. علبة 100 والتخزين بالقطعة = 100. قطعة والتخزين بالعلبة100 = 0.01.','supply-map')
rule('كمية الاستهلاك الافتراضية للمريض الواحد','عدد وحدات التسعير التي تستخدم افتراضيًا لمريض واحد، مثل قطعتين. يختلف عن عدد محتويات العبوة وعن كمية وحدات المخزن لكل وحدة تسعير.','supply-map')
rule('معامل التحويل','معامل يحول كمية المصدر أو الملف المستورد إلى وحدة المخزن. راجع اتجاه التحويل المكتوب في شاشة الاستيراد قبل الاعتماد، فعبوة100 قطعة ليست قطعة واحدة.','supply-map')
rule('الحد الأدنى للمخزون','اكتب مستوى التنبيه لإعادة التوريد بوحدة المخزن. هذا حد للتنبيه وليس كمية افتتاحية أو شراء ينفذ تلقائيًا.','inventory-count')
rule('سعر بيع الوحدة للجمهور بعد هامش الربح','هذا سعر البيع للمريض للوحدة بعد إضافة الربح، وليس سعر شراء المورد. راجع أساس أعلى سعر شراء وسياسة النسبة قبل تعديله.','profit')
rule('نسبة الزيادة على تكلفة الشراء %|نسبة الإضافة على سعر الشراء %','اكتب نسبة الزيادة على تكلفة الشراء، مثل 20 لتصبح تكلفة10 بسعر بيع12. راجع هل الصنف يتبع النسبة القياسية أم له نسبة مخصصة.','profit')
rule('سعر شراء وحدة الصرف قبل الربح|تكلفة وحدة الصرف|تكلفة الوحدة الحالية','اكتب تكلفة شراء وحدة الصرف قبل الربح من مستند الشراء أو افتتاح المخزون. لو فاتورة المورد بالعلبة حوّلها إلى وحدة الصرف الصحيحة. لا تدخل سعر البيع هنا.','purchases')
rule('سعر الوحدة','راجع عنوان هذا الجزء ووحدة الصرف قبل الإدخال. في التوريد يكون سعر شراء الوحدة قبل الربح، وفي الصرف قد يعرض تكلفة تقديرية؛ لا تستبدله بسعر البيع دون أن يطلب النموذج ذلك.','purchases')
rule('الرصيد الموجود عند بدء الاستخدام','كمية المخزون الفعلية عند بداية استخدام النظام، بوحدة الصرف. سجّلها من مسار الافتتاح أو الجرد المعتمد حتى لا تتكرر مع توريد سابق.','inventory-count')
rule('اسم المورد|المورد المسجل','اختر المورد المسجل أو اكتب اسمه عند إنشاء مورد، مع مطابقة فاتورته وبيانات التواصل. لا تضف اسمًا مكررًا بدل استخدام حسابه الحالي.','purchases')
rule('رقم تشغيلة المصنع LOT / Batch|رقم التشغيلة LOT / Batch إن وجد','انقل رقم الدفعة من عبوة المصنع إذا توفر. إذا لم يتوفر استخدم اختيار غياب كود المصنع أو التتبع الداخلي المتاح، ولا تخترع رقم مصنع.','batch')
rule('تشغيلة موجودة للجرد|التشغيلة|التشغيلة (اختياري)|التشغيلة والصلاحية','اختر الدفعة الفعلية التي تخص العد أو الصرف، وراجع تاريخ انتهائها والكمية المتاحة في المكان. الاختيار التلقائي قد يستخدم الأقرب انتهاء حسب المسار.','batch')
rule('الصلاحية|له صلاحية','حدد هل الصنف يحتاج تتبع صلاحية، أو أدخل تاريخ انتهاء الدفعة إذا كان الحقل تاريخًا. إعداد الصنف لا يغني عن بيانات انتهاء كل دفعة استلام.','batch')
rule('تاريخ الإنتاج إن وجد','اكتب تاريخ الإنتاج المطبوع على الدفعة إن توفر، وليس تاريخ شراء الفاتورة. راجعه مع مدة الصلاحية أو الانتهاء المطبوع.','batch')
rule('مدة الصلاحية بالشهور إن وجدت','عدد الأشهر من تاريخ الإنتاج حتى الانتهاء وفق العبوة، مثل 24. إن لم تتوفر المدة أدخل تاريخ الانتهاء المطبوع في حقله بدل التخمين.','batch')
rule('المخزن المطلوب منه|مخزن الصرف|المخزن المصدر','اختر المكان الذي ستخرج منه الكمية فعليًا وراجع الرصيد والدفعة فيه. مخزن الصرف يختلف عن اسم القسم أو المريض المستفيد.','internal-issue')
rule('المخزن المستقبل|مخزن الاستلام','اختر المخزن الذي سيستلم التوريد أو التحويل، وراجع الفرع والمسؤول. في التحويل يجب أن يختلف عن مخزن المصدر.','transfer')
rule('المكان|المخزن|اسم المخزن','اختر مكان حفظ الكمية المقصودة، أو اكتب اسمًا يميز المخزن عند إنشائه. الأرصدة والجرد والحركات تُراجع على المكان المحدد.','inventory-count')
rule('الغرض من الطلب|الغرض من الاستخدام','اكتب استخدام الكمية ومن المستفيد ولماذا تحتاجها. صرف مستلزم لمريض يربط بالمريض/الزيارة، أما الاستهلاك الإداري فلا يحمله على مريض بلا سبب.','internal-issue')
rule('نوع الإدخال','حدد هل العملية افتتاح مخزون أو جرد فعلي حسب الاختيارات. الافتتاح يثبت بداية الرصيد، والجرد يقارن الموجود بالحركات؛ لا تخلطهما بفاتورة شراء.','inventory-count')
rule('التاريخ والوقت الفعلي للجرد','حدد وقت العد الفعلي للكميات، وليس وقت رفع ملف الجرد إذا اختلف. الوقت يساعد مطابقة الحركات التي تمت قبل العد وبعده.','inventory-count')
rule('المطابقة','اربط سطر الملف المستورد بالصنف الموجود فعلًا أو اختر إنشاء صنف جديد عند عدم وجوده. راجع الاسم والوحدة قبل قبول المطابقة.','inventory-count')
rule('المستلم','اختر الموظف الذي سيستلم الكمية أو العهدة فعليًا في وجهة التحويل حسب الإجراء. لا يعتبر الاختيار وحده إثبات استلام.','transfer')
rule('المستخدم|الموظف المسؤول','اختر حساب الموظف الذي تخصه المسؤولية أو الوردية أو الجرد. راجع تكليفه وصلاحيته بدل اختيار منشئ الطلب تلقائيًا.','inventory-count')
rule('اسم الجرد|اسم خطة الجرد','اكتب اسمًا يميز عملية العد أو خطة تكرار الجرد، مع المكان أو الفترة عند الحاجة لسهولة الرجوع إليها.','inventory-count')
rule('مهلة التسليم بالأيام','عدد الأيام المسموحة لتسليم مهمة الجرد حسب خطة التكليف. هذه مهلة عمل وليست مدة صلاحية صنف.','inventory-count')
rule('آخر موعد للتسليم|موعد التسليم|أول موعد','حدد الموعد الذي يخص المهمة أو خطة الجرد. أول موعد يبدأ منه الجدول، وموعد التسليم آخر وقت مطلوب لإنجاز التكليف.','tasks-guide')
rule('تكرار كل (يوم)','اكتب عدد الأيام بين مرات تكرار الخطة، مثل7 للجرد الأسبوعي. راجع أول موعد والمهلة قبل تشغيل التكرار.','inventory-count')
rule('اسم الفرع|الفرع','حدد الفرع الذي يخص السجل أو المخزن أو الطبيب. راجع أن المكان والتكليف تابعان لنفس الفرع عند تنفيذ حركة.','inventory-count')
rule('نسخ تقسيمات فرع','اختر الفرع الذي تريد أخذ تقسيماته كنموذج عند إعداد فرع، ثم راجع الأسماء والمسؤوليات الجديدة. نسخ التقسيمات لا يعني نقل رصيد المخزون.','inventory-count')
rule('المسؤولية','حدد حدود مسؤولية المستخدم عن المكان أو الجرد وفق التكليف. هذا إعداد صلاحية وعهدة، وليس قرار تحميل مالي لفرق غير مراجع.','inventory-count')
rule('سبب الصرف الإضافي','اكتب سبب إضافة المستلزم للمريض خارج المشمول، وراجع موافقته والزيارة والفاتورة. لا تصرف نفس المستلزم مرة من التنفيذ ومرة من هذا النموذج.','internal-issue')
rule('نوع الهالك','حدد سبب خروج الكمية كهالك مثل تلف أو انتهاء صلاحية حسب القائمة، واربطه بالدفعة والمستند والمراجعة المطلوبة.','inventory-count')
rule('مخزن الهالك|كمية الهالك إن وجدت','اختر المكان والكمية التالفة الفعلية بوحدتها. الهالك يؤثر على المخزون والتكلفة ولا يسجل بيعًا أو تحصيلًا من مريض.','inventory-count')
rule('العدد الفعلي الآن','اكتب الكمية التي عُدت فعلًا في المكان والدفعة المحددين، لا الكمية الدفترية إذا اختلفتا. سيظهر الفرق للمراجعة.','inventory-count')
rule('سبب الجرد وملاحظات العد','اكتب مناسبة الجرد وكيف تم العد وأي ظروف تفسر الفرق، حتى يراجع المسؤول التسوية قبل اعتمادها.','inventory-count')
rule('سبب التحويل','اكتب لماذا تنقل الكمية بين المكانين وما الجهة المستفيدة، حتى يمكن تتبعها مع الإرسال والاستلام.','transfer')
rule('الكمية المستلمة فعليًا في هذه المرة','اكتب ما استلمته فعليًا في هذه الدفعة فقط، خصوصًا عند الاستلام الجزئي. لا تدخل إجمالي الطلب إذا وصل جزء منه.','transfer')
rule('سبب فرق الاستلام إن وجد','اشرح لماذا اختلف المستلم عن المصروف أو المطلوب، مع المستند أو حالة الأصناف إن توفرت، قبل إغلاق التحويل.','transfer')
rule('بحث بالكود أو الصنف أو المورد|بحث بالاسم أو الكود','اكتب جزءًا من الكود أو الاسم المحدد في عنوان البحث لفلترة السجلات. البحث لا يغير بيانات الصنف أو ينشئ كودًا جديدًا.','batch')
rule('بحث باسم المريض أو الهاتف أو رقم الملف|بحث بالاسم أو الهاتف أو رقم الملف','اكتب اسم المريض أو الهاتف أو رقم الملف للعثور على السجل الموجود، ثم طابق الهوية قبل اختياره. النتيجة المتشابهة في الاسم لا تعني نفس المريض.','patient')

rule('الخدمة|اسم الخدمة|الخدمة الأصلية','اختار أو اكتب الخدمة التي يخصها هذا السجل، مع مطابقة كودها وقسمها. في الحجز استخدم الخدمة الجاهزة، وفي الربط اختار تعريفها الأصلي من التسعير.','booking-flow')
rule('كود الخدمة|كود الخدمة في عقد الطبيب|كود النسخة في الاستقبال','استخدم الكود المعتمد للخدمة واربطه بالكود المقابل في العقد والتسعير. اسم الخدمة وحده لا يكفي للمطابقة بين هذه السجلات.','doctor-missing')
rule('سعر الخدمة|سعر الخدمة المتعاقد','اكتب سعر الخدمة الذي يخص التعريف أو العقد في هذه الشاشة، وراجع المشمول والتحمل والخصم. السعر المرجعي أو المتعاقد لا يعني تحصيلًا من المريض.','invoice')
rule('مدة الخدمة بالدقائق|الدقائق','اكتب عدد دقائق الخدمة أو الحجز مثل20. المدة تحدد طول الموعد، ويجب أن تكفيها فترة تواجد الطبيب.','no-slots')
rule('تاريخ الحجز بتوقيت القاهرة|الوقت المتاح بتوقيت القاهرة|بداية التواجد بتوقيت القاهرة|نهاية التواجد بتوقيت القاهرة','اختر تاريخ ووقت القاهرة للحجز أو التواجد حسب الحقل. راجع بداية الفترة ونهايتها ومدة الخدمة؛ ظهور عقد طبيب لا ينشئ مواعيد بلا تواجد.','no-slots')
rule('الطبيب والقسم من عقد الأتعاب المعتمد','اختار الطبيب والقسم من عقد أتعاب ساري ومعتمد ومتوافق مع الخدمة. إذا كانت القائمة خالية راجع نطاق كود الخدمة وشروط الاستحقاق والمراجع المستقل.','doctor-missing')
rule('اسم المريض التجريبي','اسم يستخدم داخل مساحة التدريب فقط. لا تنقل ملفًا حقيقيًا لمساحة التدريب ولا تعتبر هذا الملف بديلًا لملف الأرشيف المتكامل.','booking-flow')
rule('تاريخ الميلاد إن وجد','انقل تاريخ ميلاد المريض الصحيح عند توفره، ولا تستخدم تاريخ الزيارة أو تاريخ اليوم بدلًا منه.','patient')
rule('مساحة العمل','اختار مساحة التشغيل المتاحة لحسابك. التدريب له بيانات منفصلة، والتشغيل المتصل يستخدم سجلات المركز الفعلية ضمن صلاحياته. راجع اسم المساحة قبل الحفظ.','booking-flow')
rule('تصنيف جهة التعاقد','اختار التصنيف الذي ستظهر الجهة داخله. الجهات السابقة موجودة في تعاقدات كاش، والإضافة تبدأ بتصنيف الصفحة المفتوحة. التصنيف منفصل عن نوع الجهة وحالة عقدها.','entities')
rule('شامل الحسابات التابعة — أستاذ عام','فعّل الاختيار لتجميع حركة الحساب وأبنائه مرة واحدة. ألغِه لعرض الحركة المسجلة مباشرة على الحساب المختار.','ledger-guide')
rule('نسبة الاستقطاع حسب المستند %','أدخل النسبة المدونة بالمستند. يحسب النظام مبلغ الاستقطاع وصافي النقد، ويمكنك إدخال مبلغ الاستقطاع مباشرة. لا توجد نسبة ضريبية ثابتة مفروضة هنا.','ledger-guide')
rule('الحساب المقابل','اختَر حساب حركة مفعّلًا من الشجرة. الحسابات التشغيلية مثل الأطباء والموردين والرواتب والبنك تسدد من أقسامها حتى يبقى ربط الرصيد محفوظًا.','ledger-guide')
rule('وردية الخزينة الرئيسية','اختَر ورديتك المفتوحة في الخزينة الرئيسية. السند يُحفظ للمراجعة ولا يؤثر في النقد قبل اعتماد مستخدم آخر.','ledger-guide')
rule('اسم مستلم النقد أو مسلّمه','اكتب اسم الطرف الذي يستلم النقد عند الصرف أو يسلّمه عند القبض، كما هو موضح بالمستند.','ledger-guide')
rule('الفرع أو مركز التكلفة','اكتب الفرع أو مركز التكلفة المدون بالمستند إن وجد. هذه معلومة وصفية للسند ولا تعيد تصنيف الحسابات أو القيود السابقة.','ledger-guide')
rule('إجمالي السند قبل الاستقطاع','أدخل إجمالي قيمة العملية قبل الاستقطاع. النقد المصروف يساوي الإجمالي ناقص الاستقطاع ويظهر قبل الحفظ.','ledger-guide')
rule('مرجع السند','أدخل رقم المستند المؤيد للعملية. المرجع لا يتكرر بين سندات الحسابات.','ledger-guide')
rule('بيان السند','اكتب سبب القبض أو الصرف ووصف العملية طبقًا للمستند، ليظهر في كشف الحساب والمراجعة.','ledger-guide')
rule('اسم الجهة|الجهة','اختار الجهة صاحبة الاتفاق أو اكتب اسمها عند تعريفها، مع مطابقة المستند وبيانات التواصل. لا تخلط موردًا بجهة تأمين أو جهة تعاقد أخرى.','entities')
rule('نوع العلاقة|نوع الجهة','حدد صفة الجهة مثل تأمين أو شركة أو شريك وفق القائمة؛ الصفة تحدد البيانات وطريقة التعامل والمتابعة المناسبة.','entities')
rule('تحمل الجهة %','نسبة قيمة الخدمة التي تتحملها الجهة حسب العقد، وليس ما يدفعه المريض. مثال جهة تتحمل80% يترك20% على المريض قبل أي شروط أو بنود أخرى.','insurance')
rule('الشروط والمستند|شروط التعاقد والمشمولات|شروط المشمول والإلغاء|ملاحظات العقد','اكتب شروط العقد المعتمد بوضوح، بما يشمل الخدمات والمستلزمات والزيارات والصلاحية والإلغاء عند انطباقها. لا تستخدم ملاحظة غير معتمدة لتغيير حق مالي.','package')
rule('مرحلة الاعتماد|حالة التعاقد','اختر أو راجع المرحلة التي وصل إليها العقد بالفعل. المسودة أو المعلق لا يساوي عقدًا معتمدًا ساريًا، والاعتماد يتطلب مراجعًا حسب الصلاحية.','entities')
rule('العقد المعتمد','اختر العقد الذي اكتمل اعتماده وتنطبق فترته وشروطه على هذه العملية. لا تستخدم عقدًا آخر لإكمال حقل فارغ.','entities')
rule('إثبات الأهلية أو رقم الموافقة','اكتب رقم موافقة الجهة أو مستند أهلية المريض لهذه الخدمة وفق العقد. وجود ملف للمريض وحده لا يثبت أن الجهة ستتحمل المبلغ.','insurance')
rule('الفاتورة / الباكج / الإيصال / الطرف','اختر المستند أو الطرف الذي يخص نوع الطلب الحالي. راجع نوعه ورقمه والمبلغ المتبقي قبل إرسال الطلب للمراجعة.','requests')
rule('المبلغ؛ الهالك وطلبات التصحيح صفر','اكتب مبلغ طلب السداد أو الاسترداد حسب العملية. في الهالك أو طلب التصحيح أدخل0 كما يطلب هذا المسار؛ الكمية والتصحيح يُحددان في حقولهما، ولا يعني الصفر عدم وجود أثر محاسبي.','requests')
rule('عند الإشعار الدائن: البند المخفض','حدد أي بند يتم تخفيضه في الإشعار الدائن، مثل الخدمة أو المستلزم بحسب الخيارات، حتى لا ينخفض بند غير المقصود أو يُخفض مرتين.','invoice')
rule('اسم الباكج|الباكج|الباكج إن وجد','اختر تعريف الباكج أو باكج المريض المناسب لهذه العملية، أو اكتب اسمًا يميزه عند إنشائه. راجع الخدمات والزيارات والصلاحية قبل الحجز أو البيع.','package')
rule('إجمالي سعر الباكج','اكتب المقابل المتفق عليه للباكج كاملًا. يختلف عن قيمة دفعة واحدة أو سعر زيارة واحدة، ولا يثبت إيراد كل الخدمات قبل تنفيذها.','package')
rule('نسبة الربح % (على إجمالي الباكج)','نسبة الزيادة التي يطبقها نموذج التسعير على مجموع خدمات الباكج لحساب سعره النهائي. راجع الناتج بدل إضافة نفس الزيادة مرة أخرى عند التحصيل.','package')
rule('الصلاحية بالأيام','عدد الأيام التي يظل فيها حق استخدام الباكج ساريًا وفق شروطه. هذه مدة استخدام الباكج وليست صلاحية دواء أو عدد زيارات.','package')
rule('مرجع النص التعاقدي المؤيد لحق التحصيل','اذكر بند العقد أو المستند الذي يثبت حق التحصيل غير المشروط في هذا المسار. لا تعتبر موعد القسط وحده دليل استحقاق دون شروط العقد.','package')
rule('راجع طبيعة الحق','اختر طبيعة الحق وفق النص التعاقدي الذي يراجعه المسؤول المالي. القرار يحدد معالجة الاستحقاق ولا يستخدم لتجاوز تنفيذ الخدمة أو إثبات تحصيل لم يحدث.','package')
rule('سبب إنهاء الزيارة دون خدمة منفذة إن وجد','اشرح لماذا ستغلق الزيارة بلا تنفيذ، مثل إلغاء المريض أو عدم إتمام الإجراء، وراجع حالة الطلبات والتحصيلات قبل الإغلاق.','booking-flow')
rule('نسبة الخصم %','اكتب نسبة الخصم المعتمدة فقط، مثل10، وراجع أساس تطبيقها وصلاحية منحها. النسبة تختلف عن قيمة المبلغ بعد الخصم.','invoice')
rule('أساس الأتعاب','حدد هل وعاء أتعاب الطبيب يخص الخدمة أو يخصم منه تكلفة المستلزمات وفق الخيارات والاتفاق. طابقه مع العقد قبل التنفيذ.','doctor-missing')
rule('يتطلب جهازًا|الجهاز إن استخدم|الجهاز المحجوز إن لزم','حدد الجهاز المطلوب أو المستخدم فعلًا للخدمة عند انطباق الشرط. راجع توافره وحجزه، ولا تربط جهازًا لم يستخدم فقط لإكمال النموذج.','devices-guide')
rule('كود الجهاز','معرّف ثابت يميز الجهاز داخل النظام. استخدمه لربط الحجز والتشغيل والصيانة بالجهاز الصحيح، وليس برقم فاتورة شرائه.','devices-guide')
rule('نوع العداد','اختار طريقة قياس استخدام الجهاز مثل دقائق أو عداد حسب الإعداد. الاختيار يحدد كيف تفهم قراءات التشغيل وتكاليفه.','devices-guide')
rule('مرجع الأصل إن وجد','اربط الجهاز بالأصل المحاسبي المقصود عند توفره، حتى يمكن مراجعة بياناته وتكلفته دون إنشاء أصل ثانٍ لنفس الجهاز.','devices-guide')
rule('دقائق تشغيل الجهاز إن استخدم','اكتب عدد دقائق التشغيل الفعلية لهذه الخدمة، وليس مدة تواجد الطبيب أو عدد خدمات اليوم.','devices-guide')
rule('قراءة قبل|قراءة بعد','سجل قراءة عداد الجهاز قبل الاستخدام وبعده كما حدثت. راجع أن الفرق يمثل الاستهلاك المقصود وبوحدة العداد المحددة.','devices-guide')
rule('سبب اختلاف الاستهلاك عن المكونات إن وجد','اشرح لماذا اختلفت الكمية الفعلية من المستلزمات عن الوصفة الافتراضية للخدمة، مع مراجعة المشمول والإضافات قبل التنفيذ.','internal-issue')
rule('الموافقة على الإضافات','سجل موافقة المريض الفعلية على الإضافات المدفوعة بعد توضيح سعرها. هذا الاختيار لا يعني موافقة تلقائية لكل مريض أو صرفًا سبق تنفيذه.','internal-issue')
rule('الليد المرتبط بنفس ملف المريض|الليد المرتبط بنفس ملف المريض إن وجد','اختار الليد المرتبط بملف هذا المريض لربط التواصل بالحجز ومصدره. لا تربط ليدًا لشخص آخر بسبب تشابه الاسم أو الهاتف المشترك.','leads-guide')
rule('الموافقة|مرجع الموافقة أو طلب إيقاف التواصل','سجل موافقة المريض على التواصل أو طلبه إيقافه ومرجع ذلك حسب النموذج. الموافقة على الحجز لا تفترض موافقة على كل رسالة تسويقية.','communications-guide')
rule('نوع التواصل|نص المسودة','حدد غرض الرسالة واكتب نصها للمراجعة وفق حالة الحجز والموافقة. حفظ المسودة أو فتح واتساب لا يثبت إرسالًا أو تسليمًا.','communications-guide')
rule('دليل الإسناد','اختر الدليل الذي يثبت مصدر الحجز بحسب المسار، وأرفق مرجعه. إفادة المريض تختلف عن تتبع إعلان مؤكد، ولا يثبت التتبع بمجرد اختيار القناة.','booking-source')
rule('معرف الإعلان من تقرير Meta','انقل معرّف الإعلان من تقرير ميتا الذي يخص العملية، وليس اسم الحملة أو رقم الحجز. راجع دليل الإسناد قبل اعتماد الربط.','ads-guide')
rule('مرجع تقرير الإنفاق أو المستند|نتيجة المطابقة ومرجع القرار|نتيجة مراجعة الأرقام والتغطية','اذكر مصدر الأرقام ونتيجة مطابقتها بالفترة والحملة أو السجلات، مع تفسير أي فرق قبل اعتماد التقرير.','indicators')
rule('نوع الأصل|السجل في الاستقبال|الأصل في النظام','في شاشة الربط حدد نوع السجل ومرجعه في الاستقبال ومرجعه الأصلي بالنظام. طابق الطرفين من سجلاتهما، ولا تخترع معرّفًا أو تعيد إنشاء السجل لإتمام الربط.','integration-guide')
rule('الكود المحاسبي للطبيب إن كان الربط لطبيب','كود الطبيب الثابت المعتمد في الحسابات لربط سجله، وليس كود الخدمة أو اسم الطبيب. طابقه بعقد الطبيب قبل الحفظ.','doctor-missing')
rule('نتائج التجربة والنواقص بالتفصيل','سجل ما اختبرته والنتيجة والفروق المتبقية بالمستندات. لا تعتمد التجربة نيابة عن موظف لم يختبرها أو تصف بيانات محاكاة بأنها تشغيل فريق فعلي.','integration-guide')
rule('كلمة السر|كلمة السر الجديدة','اكتب كلمة المرور الخاصة بك وفق شروط النموذج. عند التغيير استخدم كلمة جديدة، والمساعدة تشرح الحقل دون قراءة القيمة التي كتبتها.','access')
rule('تأكيد كلمة السر','أعد كتابة نفس كلمة المرور الجديدة للتأكد من تطابق الإدخال. هذا ليس مكان كلمة المرور السابقة.','access')
rule('بحث في الأقسام المتاحة لك|بحث|بحث عن مادة','اكتب اسم القسم أو جزءًا من اسم السجل المطلوب. النتائج تعتمد على صلاحية حسابك والبيانات المتاحة، والبحث لا يغير السجلات.','personal')
rule('رسالة الشكر','اكتب سبب شكرك للزميل أو العمل الذي تقدره، واختر المستلم الصحيح قبل الإرسال.','personal')
rule('مواد المحتوى (ساعة)','عدد الساعات المستخدم كحد متابعة لتأخر مواد المحتوى بحسب إعداد التنبيه. لا يمثل موعد نشر تلقائي أو ساعات عمل الموظف.','access')
rule('ليدز جديدة من غير رد (ساعة)','عدد الساعات الذي يحدد متى يُعد الليد الجديد متأخرًا بلا رد في تنبيهات المتابعة. عدل الحد حسب سياسة الفريق.','access')
rule('من|من تاريخ|من تاريخ البدء|إلى|إلى تاريخ|لـ|يبدأ|ينتهي|اليوم|التاريخ','حدد بداية أو نهاية الفترة أو اليوم وفق عنوان الحقل ونوع الإدخال. في الفلاتر يغير العرض فقط، وفي العقد أو التواجد يحدد السريان. راجع ترتيب البداية والنهاية والمنطقة الزمنية المكتوبة.','personal')
rule('المتابعة القادمة|موعد المتابعة القادمة','حدد تاريخ المتابعة المقبلة بعد تسجيل نتيجة المحاولة الحالية، ثم راجع المسؤول عن متابعتها. لا تستخدمه بدل موعد حجز المريض.','leads-guide')
rule('ملاحظة|ملاحظة (اختياري)|ملاحظات|التفاصيل','اكتب تفاصيل هذا السجل التي يحتاجها المراجع أو المنفذ ولا تغطيها الحقول الأخرى. تجنب نسخ بيانات حساسة لا تخص الغرض، ولا تستخدم الملاحظة بدل المستند أو القرار.','personal')
rule('وصف الخدمة|وصف الخدمة أو الصرف','صف الخدمة المقدمة أو غرض الصرف كما هو في المستند، حتى يستطيع المراجع تمييزها عن الحركات الأخرى. لا تضع مبلغًا أو اسم مريض بدل الوصف.','invoice')
rule('المطلوب|عنوان المهمة|وصف المطلوب|المطلوب من الموظف|التوجيه والخطوات المطلوبة','اكتب العمل الذي يجب تنفيذه ومن أين يبدأ وما الذي يجب تسليمه. استخدم طلبًا يمكن للمسؤول فهمه ومراجعته بدل عنوان عام.','tasks-guide')
rule('المشروع|اسم المشروع|مشروع الفريق|المهمة','اختر المشروع أو المهمة التي تخص هذا التكليف، أو اكتب اسمًا يميز المشروع عند إنشائه. اربط المهمة بوالدها الصحيح حتى تظهر داخل تسلسلها.','tasks-guide')
rule('وصف الخطة','اشرح نتيجة المشروع وخطواته ونطاقه وما يعتمد عليه من أقسام أخرى، ثم وزع المهام بدل وضع كل التفاصيل في عنوان المشروع.','tasks-guide')
rule('مدير المشروع','اختر الحساب المسؤول عن متابعة المشروع وتوزيع مهامه ومراجعة تقدمه حسب صلاحياته. هذا لا يمنحه صلاحيات مالية أو إدارية إضافية.','tasks-guide')
rule('شكل التسليم|النتيجة المتوقعة|النتيجة المتوقعة ومعيار القبول','حدد ما الذي سيُراجع عند اكتمال المهمة، مثل ملف جرد أو رابط تقرير أو عدد مستندات مطابق. وضّح معيار القبول قبل بدء التنفيذ.','tasks-guide')
rule('الأولوية','حدد ترتيب أهمية العمل من القائمة. الأولوية تساعد تنظيم البداية، لكنها لا تستبدل موعد التسليم أو الاعتماد المطلوب.','tasks-guide')
rule('الفترة|إيقاف التكرار في (اختياري)','حدد وحدة تكرار المهمة أو تاريخ إيقاف التكرار حسب الحقل. راجع العدد وموعد أول تنفيذ حتى لا ينشئ الجدول تكليفات في فترة غير مطلوبة.','tasks-guide')
rule('اكتب شغلك هنا أو أرفق ملفًا|رابط الشغل (اختياري)|إضافة ملفات|📎 إرفاق ملفات','أدخل نتيجة العمل أو رابطًا يمكن للمراجع فتحه وأرفق الملفات التي تثبت التنفيذ. راجع صلاحيات الرابط والمرفق قبل إرسال المهمة للمراجعة.','tasks-guide')
rule('الحالة|حالة السوشيال','اختار الحالة الفعلية أو فلتر العرض حسب هذه الشاشة. تغيير الفلتر لا ينقل المستند لمرحلة جديدة، والحالة التنفيذية لها إجراء وصلاحية مستقلان.','personal')
rule('تقرير المتابعة','اختر التقرير الذي ستسجل نتيجة متابعة إجراءاته، وطابق الفترة والمؤشر قبل تقييم التنفيذ.','indicators')
rule('النتيجة|النتيجة الموثقة','سجل ما تحقق بعد التنفيذ مع ما يثبته. ميّز النتيجة الفعلية عن النتيجة المتوقعة أو اقتراح لم يبدأ.','indicators')
rule('القيمة المقاسة','اكتب القياس الفعلي للمؤشر في الفترة المحددة وبوحدته، مثل عدد الحجوزات أو نسبة التحويل. راجع مصدر القياس قبل الحكم على الأثر.','indicators')
rule('دليل الحكم وتفسيره','اذكر المستند أو القياس الذي بنيت عليه تقييم النتيجة، واشرح علاقته بمعيار القبول والفترة بدل تسجيل حكم بلا دليل.','indicators')
rule('المرحلة','اختر المرحلة التي وصل إليها العمل فعلًا، مع استكمال المطلوب منها. تخطي مرحلة لا يعوض اعتمادًا أو إجراءً لم يحدث.','tasks-guide')
rule('المخرج الذي يثبت التنفيذ','حدد ملفًا أو رابطًا أو مستندًا يثبت إنجاز المرحلة، مع إمكانية وصول المراجع إليه. كتابة «تم» وحدها لا توضح ما نُفذ.','tasks-guide')
rule('موعد المرحلة بتوقيت جهازك|موعد تسليم المهمة بتوقيت جهازك','اكتب تاريخ ووقت التسليم وفق توقيت الجهاز كما ينص الحقل. راجع المنطقة الزمنية إذا كنت خارج مصر، ولا تفترض أنه حقل بتوقيت القاهرة.','tasks-guide')
rule('موعد التسليم بتوقيت القاهرة','حدد موعد التكليف بتوقيت القاهرة، وميّزه عن حقول أخرى مكتوب عليها توقيت الجهاز. راجع التاريخ والساعة قبل الحفظ.','tasks-guide')
rule('أقرب تاريخ لقياس الأثر','اختر أول تاريخ يمكن فيه قياس نتيجة الإجراء بعد تنفيذه. لا تقارن أثر حملة أو تغيير قبل أن تتوفر له مدة وبيانات مناسبة.','indicators')
rule('لينك اللوكيشن (جوجل ماب)','ضع رابط موقع الفرع الصحيح على خرائط جوجل بعد فتحه والتحقق من العنوان، حتى لا يُوجّه المريض لفرع آخر.','chatbot')
rule('الموقع','رابط الموقع الإلكتروني الرسمي للمركز في هذا الحقل، وليس العنوان البريدي أو رابط خرائط المكان.','chatbot')
rule('طرق الدفع المتاحة','حدد طرق السداد التي يقبلها المركز فعليًا في المعلومات العامة. هذا الوصف لا يفتح خزينة أو يثبت تحصيلًا ماليًا.','chatbot')
rule('اسم العرض|السعر / الخصم','اكتب اسم العرض أو سعره/خصمه المعتمد وفق الحقل، وراجع الفترة والشروط والخدمات المشمولة قبل إتاحته للمستخدمين.','chatbot')
rule('السؤال|الإجابة المعتمدة','اكتب السؤال الشائع أو الرد الذي راجعته الإدارة في الحقل المقابل. الرد يجب أن يتفق مع المواعيد والأسعار والشروط الحالية دون إدخال بيانات مرضى.','chatbot')
rule('الخدمات المتفق عليها','اكتب أو اختر الخدمات التي ينص عليها عقد الجهة، مع الأسعار أو الشروط في حقولها. لا تعتبر باقي خدمات المركز مشمولة تلقائيًا.','entities')
rule('اسم مسؤول التعاقد','اكتب أو اختر المسؤول الذي يتابع الاتفاق والتواصل مع الجهة وفق التكليف، حتى يعرف الفريق لمن يرجع عند نقص مستند أو سؤال.','entities')
rule('تسجيل متابعة|تسجيل محاولة تواصل','سجل وقت المحاولة وما حدث ونتيجتها الفعلية ثم حدد الموعد التالي. لا تعتبر عدم الرد موافقة أو حجزًا مؤكدًا.','leads-guide')
rule('نوع المعاملة','اختر تصنيف المعاملة المقصودة حسب قائمة الجهة أو الحساب، مع ربطها بالمستند؛ التحصيل يختلف عن استحقاق قيمة الخدمة.','entities')
rule('ملف العقد|الملف (صورة / PDF / إكسيل)','ارفع المستند المطلوب بالسجل الصحيح وراجع امتداده ومحتواه وصلاحية وصول المراجعين إليه. الرفع وحده لا يعتمد عقدًا أو يرحل معاملة.','entities')
rule('اسم العميل','اكتب اسم صاحب الاستفسار كما ورد بعد البحث بالهاتف لتجنب التكرار. الاسم وحده لا يثبت أنه نفس ملف مريض موجود.','leads-guide')
rule('نص الرسالة (اختياري)','انقل مضمون الاستفسار أو الرسالة التي تخص الليد دون تغيير معناه أو إضافة بيانات حساسة لا يحتاجها التواصل.','leads-guide')
rule('الخدمة المهتم بيها (اختياري)|مصدر الاهتمام (اختياري)','سجل الخدمة أو المنشور أو سبب الاهتمام الذي ورد في الاستفسار، وميّز ما قاله العميل عن استنتاج الموظف أو تتبع مؤكد للحملة.','leads-guide')
rule('رقم/مرجع الحجز','انقل مرجع الموعد الذي تم حجزه لهذا الليد إذا كان موجودًا فعلًا، حتى يربط التواصل بالموعد. لا تضع رقمًا افتراضيًا لتغيير الحالة إلى محجوز.','leads-guide')
rule('الميزانية اليومية|الميزانية الإجمالية','اكتب حد الإنفاق الإعلاني اليومي أو الإجمالي حسب الحقل والعملة. راجع مدة الحملة والموافقة، فهذا ليس إيراد المركز أو تكلفة إنتاج التصميم.','ads-guide')
rule('ملخص الاستهداف','اكتب الجمهور والموقع والقيود التي تستهدفها الحملة وفق الخطة المعتمدة، دون إضافة قوائم مرضى أو استهداف حساس غير مصرح به.','ads-guide')
rule('ملخص الاستراتيجية','اشرح هدف الحملة والجمهور والميزانية والإبداع ومعيار القياس الذي ستراجعه، مع تمييز المقترح عن إجراء جرى تنفيذه.','ads-guide')
rule('الحملة','اختر الحملة الإعلانية المعنية من الحساب الصحيح والفترة المقصودة. لا تخلط اسم الحملة بمعرف الإعلان أو بموضوع منشور غير ممول.','ads-guide')
rule('هتتنشر على (تقدر تختار أكتر من منصة)','حدد المنصات التي ستنشر عليها المادة المعتمدة، وراجع الصفحة والهوية ومتطلبات كل منصة. اختيار المنصة لا يعني أن النشر تم.','publishing-guide')
rule('فترة السماح قبل الجدولة (دقيقة)','عدد الدقائق التي تظل فيها المادة الجاهزة متاحة للجدولة اليدوية قبل أن تجدولها المهمة التلقائية. الحد الأدنى 5 دقائق، ويطبق فقط عند تفعيل الجدولة التلقائية.','publishing-guide')
rule('معاد النشر المجدول|تعديل ميعاد النشر','اختر موعد نشر المادة وفق المنطقة الزمنية الموضحة في شاشة الجدولة، وراجع محتواها والمنصات. الجدولة تظل مختلفة عن تأكيد النشر الفعلي.','publishing-guide')
rule('رابط المنشور للمنصات اليدوية فقط (تيكتوك/يوتيوب)|رابط المنشور للمنصات اليدوية فقط','ضع الرابط الفعلي للمادة بعد نشرها يدويًا على المنصة المطلوبة. رابط المعاينة أو ملف التصميم ليس رابط منشور منشور للجمهور.','publishing-guide')
rule('اختر جهة تنفيذ التصميم|جهة تنفيذ التصميم','اختر الموظف أو مسار التنفيذ المخول بإنتاج التصميم حسب الخيارات، ثم راجع الاستلام والرفع والاعتماد. التكليف لا يساوي اعتماد التصميم.','design-guide')
rule('المستهدف','اكتب قيمة الهدف للفترة والمؤشر المعنيين وبنفس وحدته، لا النتيجة الحالية. الهدف يستخدم للمقارنة بعد تسجيل الأداء الفعلي.','indicators')
rule('فلترة بالشهر|بداية الأسبوع','اختر الشهر أو تاريخ بداية الأسبوع الذي تريد عرض أو إدخال بياناته. راجع الفترة قبل مقارنة الأرقام أو استيراد تقرير.','indicators')
rule('أو ارفع تقرير CSV (Meta Business Suite / Meta Ads / Google Ads)','ارفع ملفCSV المصدر للفترة المطلوبة، وراجع مطابقة الأعمدة والأرقام والمعاينة قبل اعتماد الاستيراد. تحقق هل المسار يستبدل بيانات سابقة قبل الحفظ.','indicators')
rule('الوصول (Reach)','عدد الحسابات التي وصل إليها المحتوى حسب التقرير الأصلي والفترة. لا تدخل عدد المشاهدات أو مرات الظهور بدل الوصول إذا اختلف تعريفهما.','indicators')
rule('نسبة التفاعل %','اكتب النسبة المئوية كما يحسبها التقرير المعتمد مع مراجعة أساسها. نسبة5% تدخل5، وليس عدد التفاعلات أو0.05 إذا كان الحقل يطلب بالمئة.','indicators')
rule('متابعين جدد','عدد المتابعين الذين أضيفوا خلال الفترة حسب المصدر، وليس إجمالي متابعي الصفحة. راجع هل التقرير يعرض إضافة فقط أم صافي التغير.','indicators')

rule('البحث في الداشبورد|بحث في القائمة','اكتب اسم القسم أو الإجراء المطلوب لعرض الروابط المتاحة لحسابك. الفلترة لا تمنح صلاحية لقسم محجوب.','personal')
rule('سبب القيد والمستند|سبب القرار والمستند','اكتب سبب إنشاء أو مراجعة القيد والمستند الذي يؤيده، مع توضيح ما تصححه إذا كان بديلًا لقيد سابق. راجع الفترة والتوازن والمراجع المستقل.','ledger-guide')
rule('سعر شراء الوحدة','اكتب تكلفة شراء الوحدة المحددة في هذا السطر قبل نسبة ربح المركز، مع مطابقتها بفاتورة المورد ووحدة الصرف.','purchases')
rule('البند','اختر سطر المستند الأصلي الذي ستستلم أو تعالج كميته، مع مراجعة الصنف والمطلوب والمتبقي من نفس الطلب.','purchases')
rule('الكمية المستلمة','اكتب العدد الذي وصل فعلًا في هذه الدفعة، بوحدة السطر. لا تؤكد استلام إجمالي الطلب إن وصل جزء منه.','purchases')
rule('العدد في الزيارة|رقم زيارة الباكج','عدد الخدمة في زيارة الباكج أو ترتيب الزيارة حسب عنوان الحقل. راجع خطة الباكج وخدمات كل زيارة قبل الحفظ حتى لا تخصم زيارة أو خدمة مرتين.','package')
rule('تاريخ القسط','موعد الدفعة المجدولة حسب اتفاق الباكج. موعد القسط تذكير بالتحصيل ولا يثبت قبض المال أو استحقاق إيراد كل الخدمات.','package')
rule('كمية لكل وحدة خدمة','كمية المستلزم التي تدخل افتراضيًا في تنفيذ وحدة واحدة من الخدمة، بوحدة المستلزم المرتبط. راجع معامل التحويل إلى وحدة المخزن.','supply-map')
rule('المستلزم — سعر بيع الوحدة','اختار المستلزم الإضافي وفق سعر البيع المعروض للمريض، وراجع هل هو مشمول أصلًا في الخدمة قبل إضافة مبلغ عليه.','internal-issue')
rule('الكمية الفعلية','سجل الكمية التي استُخدمت فعلًا في التنفيذ بوحدتها، وفسر أي فرق عن المكونات الافتراضية قبل تأكيد الصرف.','internal-issue')
rule('الدور','اختر دور الموظف الذي ستعرض أو تعدل مستهدفاته وأوزان مؤشراته، وليس حساب شخص منفرد أو منح صلاحية جديدة.','indicators')
rule('إيه اللي اتعمل أو هتشتغل عليه؟|ملخص الإنجاز','اكتب ما أنجزته فعلًا وما ستبدأه أو ما تسلمه للمراجع، مع ملف أو رابط يثبت النتيجة عند الحاجة. لا تسجل المهمة منتهية قبل تحقق معيار التسليم.','tasks-guide')
rule('إيه اللي موقفك؟','اشرح العائق المحدد وما الإجراء أو الشخص الذي تنتظره، مثل انتظار سعر من المورد، حتى يقدر المسؤول يوجه المساعدة.','tasks-guide')
rule('ملاحظة الاعتماد (اختياري)|المطلوب تعديله','سجل نتيجة مراجعة العمل أو التعديل المطلوب بعبارة محددة، وما الذي سيقبله المراجع عند إعادة التسليم.','tasks-guide')
rule('الترتيب','اكتب ترتيب تنفيذ المهمة ضمن مهام الموظف كما يسمح النموذج. الترتيب يوضح البداية والتتابع ويختلف عن درجة الأولوية وموعد التسليم.','tasks-guide')

rule('اكتب حرفين على الأقل…|ابحث عن قسم…|اكتب 3 حروف على الأقل|بحث بالاسم / الهاتف / المرجع / الطبيب…|بحث بالاسم / الهاتف|بحث عن مريض…|بحث بالاسم / الهاتف / كود المريض|كود التتبع أو اسم الصنف|ابحث باسم المهمة أو المسؤول أو المشروع…|دوّر بالاسم / اسم الحملة / رقم الإعلان / مجموعة الكرييتف / التخصص','اكتب جزءًا من البيان المطلوب في عنوان البحث، مع الالتزام بالحد الأدنى للحروف إن وُجد، ثم اختر النتيجة الصحيحة. البحث لا ينشئ سجلًا ولا يغيره.','personal')
rule('مثال: شكراً على المجهود الرائع في حملة الأسبوع ده!','اكتب سبب الشكر والعمل الذي تقدره للموظف المحدد، ثم راجع المستلم قبل الإرسال.','personal')
rule('اكتب كومنت...|اكتب الرد…|اكتب تعليق، أو الصق رابط ملف (Drive مثلاً)…|السبب في جملة (اختياري)','اكتب تعليقًا يخص المادة أو نتيجة المراجعة، مع تحديد المطلوب أو سبب تقييمك. لو أضفت رابط ملف تأكد من إتاحته للمراجع، ثم سجل حالة التعديل حسب الإجراء.','content')
rule('اسم الجهاز الجديد','اكتب اسم الجهاز أو أسلوب العلاج الذي تريد إضافته لقائمة الاختيار، وراجعه قبل الحفظ حتى لا يكرر عنصرًا موجودًا. الإضافة للقائمة لا تنشئ أصلًا محاسبيًا.','devices-guide')
rule('رصيد مقدم قديم موثق، دون تحصيل جديد، قبل اعتماد الافتتاح.','حدد هذا الإقرار فقط عند إدخال رصيد مقدم قديم موثق قبل اعتماد الافتتاح. لا تستخدمه كتحصيل جديد أو لإضافة كاش لم يدخل الخزينة.','collections')
rule('راجعت القناة وتأكدت من النتيجة قبل القرار.','أكد الإقرار بعد فحص وسيلة الدفع ودليل وصول المبلغ أو عدم وصوله. لا تعتمده بناءً على طلب دفع أو رسالة فقط.','collections')
rule('أؤكد أن الرسالة أُرسلت بالفعل للحجز الحالي.','ضع علامة فقط إذا تحققت من إرسال الرسالة بالفعل لهذا الحجز. تجهيز النص أو فتح القناة ليس إثبات إرسال.','communications-guide')
rule('أؤكد تنفيذ الخدمة وعدم تسجيلها سابقًا في الدورة المالية.|أؤكد تنفيذ الخدمة أو تسليم المستلزمات وعدم تسجيل الفاتورة سابقًا.','أكد التنفيذ أو التسليم الفعلي بعد مراجعة السجل للتأكد من عدم تسجيل نفس الحدث سابقًا. الإقرار يترتب عليه أثر مالي ولا يصلح لإثبات حجز لم ينفذ.','invoice')
rule('راجعت الحركات والورديات حتى هذا التاريخ.','حدد الإقرار بعد مطابقة حركات الفترة ووردياتها وتسوياتها قبل الإقفال. لا تستخدمه لمجرد إخفاء فرق غير محلول.','cash-shifts-guide')
rule('أعتمد معالجة المردودات والتخفيضات بتخفيض الوعاء بنسبة انخفاض الإيراد مع إبقاء تكلفة المستلزمات المصروفة.','راجع بند العقد قبل الإقرار بهذه السياسة: تخفض المردودات وعاء أتعاب الطبيب وفق انخفاض الإيراد، وتبقى تكلفة المستلزمات التي صُرفت. الموافقة تحتاج توافق الاتفاق ومراجعه.','doctor-missing')
rule('موافق إن المرتجعات والخصومات بتقلّل نسبة الدكتور بنفس نسبة نقص الإيراد، وتمن المستلزمات اللي اتصرفت بيفضل محسوب.','راجع بند العقد قبل الإقرار بهذه السياسة: تخفض المردودات وعاء أتعاب الطبيب وفق انخفاض الإيراد، وتبقى تكلفة المستلزمات التي صُرفت. الموافقة تحتاج توافق الاتفاق ومراجعه.','doctor-missing')
rule('الصنف غير مفتوح وصالح للإعادة بعد الفحص.','حدد الإقرار بعد فحص الصنف المرتجع والتأكد من أنه غير مفتوح وصالح للإعادة وفق المسار، لا لمجرد أن المريض طلب الاسترداد.','purchases')
rule('راجعت الصرف السابق، وهذه كمية إضافية جديدة فعلًا وليست إعادة تسجيله','راجع سجل الصرف والفاتورة ثم أكد أن الكمية إضافية جديدة بالفعل. لا تكرر صرف مكون سُجل من تنفيذ الخدمة.','internal-issue')
rule('المريض وافق على قيمة المستلزم الإضافي الظاهرة','حدد الإقرار بعد توضيح سعر البيع الإضافي للمريض والحصول على موافقته، وقبل تسجيل الصرف والفاتورة المرتبطين.','internal-issue')
rule('إرسال للمراجعة بعد استكمال كل الأصناف','اختار الإرسال بعد مراجعة كميات جميع الأصناف ووحداتها. السطور غير المعدودة لا تعتبر رصيدها صفرًا، والمراجعة لا تتم بمجرد رفع الملف.','inventory-count')
rule('تطبيق النسبة على جميع الأصناف الحالية أيضًا بدل نسبها الخاصة','حدد هذا الخيار فقط إذا أردت استبدال نسب الأصناف الحالية بالنسبة القياسية أيضًا. تركه غير محدد يحافظ على سياسة الأصناف الخاصة حسب إعداد النموذج.','profit')
rule('أعتمد التكليف والمسؤول والمراحل ومواعيدها','راجع العمل والمسؤول والمراحل ومواعيد التسليم قبل تأكيد التكليف، ثم تابع الإنجاز والمخرج الذي يثبت كل مرحلة.','tasks-guide')
rule('تطبيق التعديلات على التكرارات القادمة','حدد الخيار إذا أردت أن تتبع النسخ القادمة من المهمة المتكررة هذه التعديلات أيضًا. راجع أثره على التكليفات القادمة قبل الحفظ.','tasks-guide')
rule('2026-10-17, BANK-001, 250.00','مثال لصيغة سطر كشف البنك: تاريخ ثم مرجع ثم مبلغ تفصل بينها فواصل. ضع كل حركة في سطر مستقل، والداخل موجب والخارج سالب.','bank')
rule('1112, 1000, 0, 3210, 0, 1000,','مثال لطرفي قيد: كود حساب ثم مدين ثم دائن لكل سطر حسب تنسيق النموذج. استبدل المثال بحساباتك ومبالغ مستندك، وراجع التوازن قبل الإرسال.','ledger-guide')
rule('نتيجة الاتصال أو الاجتماع','اكتب ما تم الاتفاق عليه أو ما تعطل وموعد الخطوة التالية بعد الاتصال أو الاجتماع، مع مرجع مستند عند وجوده.','entities')
rule('ملاحظة مختصرة (نقطة قوة / نقطة تطوير)','اكتب ملاحظة أداء مرتبطة بعمل أو مؤشر ودليل خلال الفترة، مع خطوة يمكن للموظف تنفيذها للتحسين.','indicators')
rule('رابط الشغل (اختياري)|https://…|https://...','ضع الرابط الفعلي المطلوب في عنوان النموذج، مثل رابط منشور منشور أو ملف تسليم. تأكد أنه يفتح للمراجع ولا تستخدم رابط معاينة بدل المستند المطلوب.','personal')
rule('عنوان المادة','اكتب عنوان المادة أو جزءًا منه للعثور عليها في قائمة النشر حسب المرشح الحالي. البحث لا يضيف مادة جديدة.','publishing-guide')
rule('مثال: حددي فئات الجمهور واحتياجات كل فئة للخدمات المسندة إليك','اكتب المطلوب من الموظف في صورة خطوات ونتيجة محددة، مع الخدمات أو نطاق العمل الذي سيعمل عليه.','tasks-guide')
rule('مثال: جدول Word أو Excel، لكل فئة الخدمة والاحتياج ومخاوف الجمهور','حدد تنسيق التسليم ومحتواه مثل جدول بالأعمدة المطلوبة، حتى يعرف الموظف ما الذي سيراجعه المسؤول.','tasks-guide')
rule('أضف بند جديد واضغط إضافة','اكتب بندًا واحدًا واضحًا في قائمة المهمة ثم اضغط إضافة. راجع القائمة قبل إرسال العمل حتى لا تتكرر البنود.','tasks-guide')
rule('الصق النص أو اكتب اللي خلصته…','اكتب العمل الذي أنجزته وأرفق المستندات أو الروابط التي تثبته، ثم اختر الإجراء المناسب مثل حفظ تقدم أو إرسال للمراجعة.','tasks-guide')
rule('لم يُعدّ','هذه علامة لسطر لم يتم عدّه بعد. أدخل العدد الفعلي عند اكتمال العد، ولا تحوله إلى صفر من غير جرد حقيقي.','inventory-count')
rule('اسم العملية','اسم العملية الجراحية السابقة كما ورد في ملف المريض أو إفادته مع التاريخ المتاح. لا تضع إجراءً مقترحًا ضمن العمليات التي تمت بالفعل.','patient-records')
rule('المرض|ضغط/سكر/غدة درقية/كلى/أورام/تنفسية/أخرى...','سجل المرض المذكور في التاريخ المرضي وفق الإفادة أو المستند، مع توضيح مصدر المعلومة. لا تضف تشخيصًا غير موثق.','patient-records')
rule('اكتب السبب الآخر|اذكرها','اكتب التفصيل الذي يقصده خيار «أخرى» في هذا الجزء من النموذج، مع الرجوع لسؤال الحقل بدل إدخال وصف لا يخصه.','patient-records')
rule('اسم الطبيب المحوّل له','اكتب اسم الطبيب أو التخصص الذي تم تحويل المريض إليه وفق قرار الطبيب، مع توثيق سبب التحويل في حقله.','patient-records')
rule('اسم الدواء','انقل اسم الدواء من وصفة الطبيب كما هو، مع التركيز والجرعة في حقليهما. لا تضع اسم المادة أو دواء بديلًا بالتخمين.','patient-records')
rule('التركيز','انقل تركيز الدواء ووحدته من العبوة أو الوصفة، مثل القيمة المكتوبة بالملليجرام. يختلف التركيز عن كمية الجرعة التي يتناولها المريض.','patient-records')
rule('الجرعة','اكتب كمية الجرعة التي وصفها الطبيب بوحدتها، مع التكرار والمدة في الحقول المقابلة. لا تستنتج جرعة من العمر أو الوزن داخل هذا النموذج.','patient-records')
rule('وحدة ساعة يوم','اختر وحدة فاصل الجرعات حسب الوصفة مثل ساعة أو يوم، مع العدد المكتوب في «كل». راجع الفرق بين كل8 ساعات وكل8 أيام.','patient-records')
rule('تعليمات إضافية للمريض','انقل تعليمات الطبيب الخاصة بالاستخدام أو المتابعة، مع تمييزها عن ملاحظة داخلية للفريق.','patient-records')
rule('تحاليل تانية غير موجودة في القائمة|أشعة تانية غير موجودة في القائمة','اكتب الفحوص التي طلبها الطبيب ولم تجدها ضمن الخيارات، مع اسمها وموضعها والجهة إن لزم، دون تكرار ما اختير بالفعل.','patient-records')
rule('أي ملاحظات من العميل','دوّن ملاحظات المريض كما وردت وميّزها عن رأي الطبيب أو نتيجة الفحص.','patient-records')
rule('سطر عادي = عنوان بولد (➢)، وسطر يبدأ بـ - = تفصيل تحته (•)','اكتب نص التقرير بحسب تنسيق هذا المحرر: السطر العادي عنوان، والسطر الذي يبدأ بشرطة تفصيل تحته. راجع معاينة الطباعة للتأكد من الترتيب.','patient-records')
rule('رقم السن','اكتب رقم السن وفق ترقيم نموذج الأسنان الذي يستخدمه الطبيب، مع مراجعة الجهة والمخطط. لا تستخدم ترتيب الجلسة بدل رقم السن.','patient-records')
rule('الخدمة اللي اتعملت','سجل الإجراء الذي نُفذ بالفعل في الجلسة وفق ملاحظة الطبيب. كتابة الإجراء في التقرير لا تعوض تسجيل تنفيذه في المسار المالي عند الحاجة.','patient-records')
rule('المدة (Time)|المدة','اكتب مدة الجلسة أو الاستخدام المقصود بوحدة الحقل، مع التمييز بينها وبين فترة العلاج الكاملة أو فاصل تكرار الجرعة.','patient-records')
rule('تشخيص الحالة العام — منفصل عن تحديد نقط الـ area على الرسم','اكتب التشخيص العام الذي وثقه المختص. أما مواضع الألم فتحدد على الرسم، ولا تستبدل أحد الجزأين بالآخر.','patient-records')
rule('اسم الوجبة (مثال: الإفطار)','اسم الوجبة في خطة التغذية مثل الإفطار، مع مكوناتها وكمياتها في الحقول المقابلة.','patient-records')
rule('المكونات (افصل بفاصلة)','اكتب مكونات الوجبة حسب خطة الأخصائي وافصل بينها بفواصل كما يطلب المحرر، مع عدم تغيير كمياتها دون مراجعة المختص.','patient-records')
rule('السعرات','سجل عدد السعرات الذي حدده أخصائي التغذية لهذه الوجبة أو الخطة وفق عنوان الحقل. لا تستخدم وزن الطعام أو سعره مكان القيمة.','patient-records')
rule('سبب الرفض (اختياري)','اشرح ما الذي منع اعتماد السجل أو الطلب بعد المراجعة، مع الخطوة المطلوبة لتصحيحه. لا ترفض سجلًا من غير مراجعة المستند وصلاحية القرار.','patient-records')
rule('الأهداف المطلوب العمل عليها','اكتب أهداف التقييم أو الخطة التي حددها المختص، بما يسمح بتوثيق العمل والاستجابة خلال الجلسات.','patient-records')
rule('التمارين والمهارات التي تم التدريب عليها','سجل التدريب الذي تم بالفعل في الجلسة وفق توثيق المختص، وليس جميع تدريبات الخطة المستقبلية.','patient-records')
rule('ما يطبقه الطفل في المنزل','انقل الواجب المنزلي الذي اعتمده المختص مع طريقة التطبيق والتكرار والمدة إن حددها، دون إضافة تمارين من عندك.','patient-records')
rule('حضر|غاب|اعتذر','حدد حالة حضور الجلسة الفعلية حسب الخيار. الاعتذار يختلف عن الغياب، ولا يعتبر الموعد المحجوز جلسة منفذة.','patient-records')
rule('ملاحظات الجلسة','سجل ما لاحظه المختص أو ما حدث في هذه الجلسة، مع ربطه بتاريخها وأهدافها والاستجابة، وميّزه عن الخطة القادمة.','patient-records')
rule('نعم|لا','اختر الإجابة التي تنطبق على السؤال الطبي أو التاريخ المرضي المقابل حسب الإفادة الموثقة. عدم معرفة المعلومة لا يساوي «لا».','patient-records')
rule('سبب الاستخدام|سبب التوقف','اكتب السبب الذي ورد في التاريخ الدوائي لاستخدام الدواء أو إيقافه مع مصدره وتاريخه إن توفر. لا توقف أو تغير علاجًا من هذا السجل دون قرار مختص.','patient-records')

# Newly introduced specialist forms retain their restricted workflow.
rule('اسم المريض من كلمتين على الأقل|الاسم من كلمتين','اكتب اسم المريض من كلمتين على الأقل. راجع الاسم ورقم الهاتف قبل إنشاء ملف جديد لتجنب تكراره.','patient-records')
rule('رقم التليفون','اكتب رقم الهاتف الذي يمكن التواصل معه وفق الحقل. في ملف المريض راجع مطابقته للملف الحالي ولا تنشئ ملفًا مكررًا.','patient-records')
rule('السن بالسنوات','اكتب سن المريض بالسنوات من0 إلى130 حسب البيانات الموثقة. استكمل الأساسيات قبل حفظ ملف أو جلسة جديدة.','patient-records')
rule('سبب طلب الاستعراض','اشرح سبب حاجتك لاستعراض سجلات التخصصات لهذا المريض. لا يتيح الطلب الاستعراض حتى يوافق المدير أو السوبر أدمن.','patient-records')
rule('ابحث بالاسم أو التليفون أو الدكتور…','اكتب جزء من اسم المريض أو تليفونه أو اسم الدكتور علشان تضيّق قايمة الحجوزات. النتايج بتتغير وانت بتكتب.','automatic-bookings')
rule('رقم التليفون أو الاسم','اكتب رقم التليفون (6 أرقام على الأقل) أو كلمة أو اتنين من اسم المريض (3 حروف على الأقل) للبحث في سجلات ماسا القديمة والجديدة. البحث للقراءة بس.','masa-archive')
rule('رقم التليفون أو الملف','اكتب رقم الهاتف الكامل أو رقم الملف للبحث عن المريض الموجود قبل إنشاء ملف جديد.','patient-records')
rule('مدة الاستعراض بالأيام','حدد مدة السماح باستعراض سجلات التخصصات من1 إلى90 يومًا حسب الحاجة. الافتراضي7 أيام، ويمكن للإدارة إلغاء السماح.','patient-records')

rule('الطبيب وعقد الخدمة المعتمد','اختار الطبيب وعقد الخدمة المعتمد والساري لعرض اسمه وكوده ونسبته ووعاء الاستحقاق وخصم المستلزمات وفترة العقد تلقائيًا. كود الطبيب مستقل عن كود الخدمة. إذا كانت الخدمة موجودة افتح سجلها الأصلي. السعر والقسم والمدة تأتي من تعريف الخدمة؛ النسبة المعتمدة للطبيب لا تساوي هامش ربح المركز.','doctor-missing')
rule('اكتب اللي عايزه… مثلاً: مصروف','اكتب كلمة من اللي عايز تعمله (مثلاً: مصروف، تحصيل، ورديتي) والقايمة هتوريك الجمل اللي فيها الكلمة دي بس.','reception-drawer')

reviewed_aliases={
'وصف اللقطة (اختياري). لو سبته فاضي النظام بيكتب وصف مناسب للمادة لوحده.':'وصف اللقطة المطلوبة',
'الشريحة ١: … الشريحة ٢: …':'نص كل شريحة (اختياري — سطر لكل شريحة، أو سيبه فاضي والوكيل يكتبه)',
'مثال: الصداع النصفي، أو اتركه ليستخدم بيانات المادة':'الموضوع أو توجيه إضافي',
'تلقائي حسب موضع النص':'وضع العنوان',
'الاسم كما سيظهر في التصميم':'اسم الدكتور',
'مثال استشاري أمراض الأطفال':'التايتل والتخصص',
'مثال الأحد - الاثنين':'أيام العمل',
'بداية الـFade بكسل':'بداية الـFade','نهاية الـFade بكسل':'نهاية الـFade',
'الأربعاء':'اليوم','مثال: 170 سم':'الطول',
'مثال: د. دينا حسني':'اسم الطبيب','مثال: مخ وأعصاب':'التخصص',
'مثلاً: المركز / المعمل / الأشعة':'القسم','مثلاً: 300 جنيه بدل 500':'السعر / الخصم',
'01xxxxxxxxx':'رقم الهاتف','name@example.com':'البريد الإلكتروني',
'اكتب أي تفاصيل تخص الملف':'ملاحظات / تفاصيل الملف (اختياري)',
'مثال: عظام':'التخصص',
'اكتب نص التقرير كامل زي ما هيتطبع بالظبط...':'نص التقرير',
'اكتب تفاصيل الروشتة كاملة زي ما هتتطبع بالظبط...':'الروشتة',
'الجملة الافتتاحية':'Hook','مثال: Medical authority + patient safety':'Angle',
'النص اللي هيتقال في الفيديو':'سكريبت / Voice-over','Caption':'كابشن النشر',
'مثال: save_share / whatsapp / book':'نوع CTA','الجملة النهائية':'نص CTA',
'مثال: medical_educational':'Video Template','ليه الفكرة تستحق الاختبار':'سبب الفرضية / Evidence note',
'احتفظ بالرد الكامل للرجوع إليه لاحقًا':'الناتج الخام من الوكيل (اختياري)',
'الصق هنا رد الوكيل الكامل...':'الناتج الخام من الوكيل (اختياري)',
'عنوان المحتوى':'العنوان','اكتب الفكرة والنص...':'نص المحتوى',
'صور حقيقية':'نوع الصور','رسوم':'نوع الصور',
'صف المكان والأشخاص والحركة والإضاءة المطلوبة':'وصف المشهد',
'مثال: الصداع النصفي، رسم المخ، تنميل الأطراف...':'الموضوع / الخدمة'
}
for alias,target in reviewed_aliases.items():
 for names,text,art in rules:
  if target in names:names.add(alias);break
 else:raise RuntimeError('No authored alias target '+target)

# MORE_RULES
# --- Training & evaluation center (training-evaluation.js) ---
TE='training-evaluation.js'
frule(TE,'المسار','اختر المنصب الذي يُعَدّ له المتدرب: مدير فرع أو مدير فريق. المسار يحدد عنوان التكليف، والاختبار واحد للمسارين في هذه المرحلة.','training-center')
frule(TE,'المتدرب','اختر الموظف صاحب حساب الدخول الذي سيقرأ الدورة ويؤدي الاختبار. يظهر التكليف له وحده في «تكليفاتي».','training-center')
frule(TE,'المراجع (يُجري المقابلة)','اختر من سيجري المقابلة ويقيّم المتدرب لاحقًا. لا يجوز أن يكون المراجع هو المتدرب نفسه، ويرى المراجع التكليفات المسندة إليه فقط.','training-center')
frule(TE,'الموعد النهائي (اختياري)','تاريخ متوقع لإنهاء الدورة والاختبار، للمتابعة فقط. لا يغلق التكليف تلقائيًا، ومدة الاختبار نفسها يحددها بنك الأسئلة.','training-center')
frule(TE,'ملاحظة للمراجع (لا تظهر للمتدرب)','ملاحظة داخلية تراها الإدارة والمراجع المسند فقط، مثل سبب الترشيح. لا تكتب فيها بيانات مرضى.','training-center')
frule(TE,'ملاحظة قصيرة (اقتباس من إجابة المرشح)','جملة قصيرة من إجابة المرشح أو سلوكه تبرر الدرجة. يراها المراجع المسند والإدارة فقط، ولا يراها المتدرب. لا تكتب فيها بيانات مرضى.','training-center')
frule(TE,'القرار النهائي','يظهر مختارًا عليه التقدير المقترح المحسوب (40% اختبار، 40% مقابلة، 20% تمثيل). يمكن للإدارة اختيار تقدير آخر بشرط كتابة السبب. بعد الاعتماد تُقفل الدرجات.','training-center')
frule(TE,'سبب التعديل (إلزامي إذا خالف القرار المقترح)','يُكتب فقط عند اختيار قرار يخالف التقدير المحسوب، ويُحفظ في سجل التدقيق مع القرار. بدونه يرفض الخادم الاعتماد.','training-center')
frule(TE,'رسالة للمتدرب (تظهر له مع النتيجة المعتمدة)','رسالة توجيهية من الإدارة تظهر للمتدرب مع تقديره بعد الاعتماد. اكتبها بصياغة تعليمية، دون درجات تفصيلية أو ملاحظات المراجع الداخلية.','training-center')
frule(TE,'سبب الإلغاء','سبب مكتوب إلزامي لإلغاء تكليف مفتوح. يُحفظ في سجل التدقيق، وبعد الإلغاء لا يستطيع المتدرب متابعة الدورة أو الاختبار.','training-center')
# --- Human resources and price lists (workforce-prices.js, price-list-governance.js) ---
W='workforce-prices.js';G='price-list-governance.js'
frule(W,'شهر المتابعة','اختار الشهر اللي عايز تشوف حضوره وطلباته ووردياته. تصدير متابعة الشهر وتحضير استحقاق المرتب بيستخدموا نفس الشهر. تغيير الشهر لا يعدل أي بيانات.','hr-my-file')
frule(W,'ابحث عن موظف أو طبيب','اكتب جزء من الاسم أو الكود أو الموبايل لتصفية القائمة. البحث بيعرض بس الملفات المسموح لك تشوفها ولا يغير حاجة.','hr-manage')
frule(W,'التكرار','اختار يومي أو أسبوعي أو شهري لتكرار المهمة على الموظف. المهمة بتظهر عند المسؤول المختار هو اللي يسجلها ويتابعها.','tasks-guide')
frule(W,'الاسم الثنائي على الأقل','اكتب اسم الموظف أو الطبيب ثنائي على الأقل زي ما هو في المستندات. قبل الحفظ النظام بيدور على ملف بنفس الاسم أو الموبايل علشان مايتكررش.','hr-manage')
frule(W,'العلاقة بالمركز','اختار موظف أو طبيب متعاون أو طبيب وموظف. ده بيحدد يظهر في المرتبات ولا في عقود الأطباء ولا الاتنين. «يحتاج استكمال» معناها لسه ماتحددش.','hr-manage')
frule(W,'حساب الدخول','اختار «ملف فقط» لو الشخص مش هيدخل الداشبورد، أو «ربط مستخدم موجود» لو عنده حساب، أو «إنشاء مستخدم» علشان تتبعت له دعوة دخول على بريده بعد الحفظ.','hr-manage')
frule(W,'اختر المستخدم الحالي','اختار حساب الدخول الموجود اللي يخص الشخص ده. الربط مايغيرش صلاحيات الحساب، والحساب الواحد مايتربطش بملفين.','hr-manage')
frule(W,'دور المستخدم الجديد','اختار الدور الوظيفي للحساب الجديد. الحساب بياخد صلاحيات الدور ده بس. الأدوار العليا زي المدير العام والمدير المالي يحددها السوبر أدمن فقط.','access')
frule(W,'المسمى الوظيفي','اكتب الوظيفة زي ما في العقد أو قرار التعيين، مثل موظف استقبال أو أخصائي. المسمى للعرض والتقارير وما بيديش صلاحيات.','hr-manage')
frule(W,'المدير المباشر','اختار الشخص اللي بيتابع الموظف ده. ده بيستخدم في متابعة الطلبات والمهام، ومايديش المدير صلاحيات إضافية لوحده.','hr-manage')
frule(W,'بداية العمل','تاريخ أول يوم شغل فعلي حسب العقد أو قرار التعيين. بيستخدم في حساب المدة ورصيد الإجازات.','hr-manage')
frule(W,'نهاية العمل','سيبه فاضي طول ما الشخص شغال. اكتب آخر يوم شغل لما العلاقة تنتهي، وغير الحالة لـ«انتهت العلاقة». إنهاء الخدمة الكامل له مسار مستقل.','hr-manage')
frule(W,'كود الطبيب من عقود الحسابات','اربط الملف بكود الطبيب المسجل في عقود الأطباء بالحسابات علشان مستحقاته تظهر مع ملفه. الكود لازم يكون موجود في العقود الأول.','hr-manage')
frule(W,'معرف الموظف من عقود المرتبات','اربط الملف بالمعرف المسجل في عقد المرتب بالحسابات. من غير الربط ده مش هتقدر تحضر استحقاق مرتب للموظف.','payroll')
frule(W,'اسم جهة اتصال الطوارئ','اسم الشخص اللي نكلمه لو حصل طارئ للموظف، مع صلة القرابة لو تحب. بيانات خاصة تظهر للمسؤولين المصرح لهم بس.','hr-manage')
frule(W,'تاريخ الميلاد','تاريخ ميلاد الموظف أو الطبيب زي ما في البطاقة. بيانات خاصة تظهر للمسؤولين المصرح لهم بس.','hr-manage')
frule(W,'هاتف الطوارئ','رقم موبايل جهة اتصال الطوارئ. راجعه مع الموظف لأنه بيستخدم في الطوارئ بس.','hr-manage')
frule(W,'مرجع مستند الاستحقاق','بيتملى تلقائي بكود زي PAY-الشهر-كود الموظف. عدله لو عندك رقم مستند أو كشف حضور معتمد. المرجع بيمنع تكرار نفس الاستحقاق.','payroll')
frule(W,'البدلات المعتمدة حسب المستند','اكتب إجمالي البدلات المعتمدة للشهر من المستند بالجنيه، أو صفر. النظام مابيحسبش إضافي أو بدلات لوحده.','payroll')
frule(W,'ضريبة الأجور حسب المستند','اكتب ضريبة كسب العمل المستقطعة الشهر ده كما في المستند المعتمد، أو صفر.','payroll')
frule(W,'التأمينات حسب المستند','اكتب حصة الموظف في التأمينات المستقطعة الشهر ده كما في المستند، أو صفر.','payroll')
frule(W,'استرداد سلفة بموافقة موثقة','اكتب المبلغ اللي هيتخصم الشهر ده من سلفة معتمدة، بس لو فيه موافقة مكتوبة. فرق الخزينة مايتخصمش من المرتب تلقائي.','payroll')
frule(W,'اسم المستند','اكتب نوع المستند بوضوح زي صورة البطاقة أو العقد أو شهادة المؤهل.','hr-manage')
frule(W,'رابط المستند على HTTPS','الصق رابط الملف على درايف المركز، ولازم يبدأ بـ https. الملف نفسه مابيترفعش من هنا، وتأكد إن مشاركته محدودة.','hr-manage')
frule(W,'تاريخ انتهاء الصلاحية','اكتب تاريخ انتهاء المستند لو له صلاحية زي ترخيص المزاولة، أو سيبه فاضي. بيساعد تعرف المستندات اللي محتاجة تجديد.','hr-manage')
frule(W,'نوع الإجازة','اختار سنوية أو عارضة أو مرضية أو ولادة طفل. كل نوع له قواعد إخطار مكتوبة تحت النموذج، والمرضية محتاجة شهادة طبية خلال 48 ساعة.','hr-my-file')
frule(W,'الكمية — أيام للإجازة، ساعات للإضافي والإذن، مبلغ للسلفة','اكتب عدد الأيام للإجازة، أو الساعات للإضافي والإذن، أو المبلغ بالجنيه للسلفة. راجع إنها متوافقة مع تاريخ «من» و«إلى».','hr-my-file')
frule(W,'سبب الاستثناء — لو الطلب خارج القواعد','لو الطلب مخالف لقواعد الإخطار أو الحد، اكتب السبب هنا. الطلب بيتقبل للمراجعة، والمراجع هو اللي يقرر.','hr-my-file')
frule(W,'رابط الشهادة الطبية (صورة أو PDF على درايف)','ارفع صورة الشهادة على درايف المركز والصق الرابط هنا خلال 48 ساعة من الإجازة المرضية، وإلا اليوم ممكن يتحسب غياب.','hr-my-file')
frule(W,'يوم الوردية','تاريخ اليوم اللي الوردية تخصه.','hr-manage')
frule(W,'بداية الوردية|نهاية الوردية','الميعاد المخطط للوردية بتوقيت جهازك. العرض بعد الحفظ بتوقيت القاهرة.','hr-manage')
frule(W,'الحضور الفعلي|الانصراف الفعلي','الوقت الفعلي للحضور أو الانصراف لو معروف. الفرق عن ميعاد الوردية بيظهر كتأخير في ملخص الشهر. السجل محتاج اعتماد شخص تاني.','hr-manage')
frule(W,'اسم اللائحة','اسم واضح يميز اللائحة، زي «أسعار المركز» أو اسم الجهة المتعاقدة. الاسم بيظهر في سبب السعر عند الحجز.','price-lists')
frule(W,'رقم الإصدار','رقم نسخة اللائحة. «إنشاء إصدار جديد» بيزود الرقم تلقائي وبيحافظ على النسخة القديمة كما هي.','price-lists')
frule(W,'النطاق','اختار «لائحة المركز» للأسعار العامة، أو عقد جهة معينة لو اللائحة خاصة بيها.','price-lists')
frule(W,'طريقة التسعير','أسعار ثابتة: كل بند له سعره. خصم: الخصم بيتطبق على سعر المركز. أسعار وخصومات: الاتنين مع بعض حسب كل بند.','price-lists')
frule(W,'الخدمات غير المدرجة','بيحدد إيه اللي يحصل لخدمة مش موجودة في البنود: «غير مشمولة» توقف التسعير وتحتاج مراجعة، أو سعر المركز من غير خصم، أو سعر المركز مع خصم اللائحة.','price-lists')
frule(W,'الجمع مع خصم إضافي داخل الاستقبال','اختار «يسمح» لو مسموح للاستقبال يطلب خصم زيادة على سعر اللائحة، وده بيمشي بإجراءات اعتماد الخصم العادية.','price-lists')
frule(W,'خصم اللائحة %','نسبة خصم عامة من 0 لـ100 على كل بنود اللائحة. لو للبند خصم نسبة كمان، النسبتين بيتطبقوا ورا بعض مش بيتجمعوا.','price-lists')
frule(W,'خصم اللائحة مبلغ لكل وحدة خدمة','مبلغ بالجنيه بيتخصم من كل وحدة خدمة بعد الخصم بالنسبة. لو السعر النهائي طلع صفر أو أقل النظام بيرفض.','price-lists')
frule(W,'سارية من|سارية حتى','فترة تطبيق اللائحة على تاريخ الخدمة. برا الفترة دي اللائحة مابتتطبقش حتى لو معتمدة.','price-lists')
frule(W,'استيراد Excel أو CSV أو PDF نصي','اختار ملف الأسعار وهو بيتقري على جهازك ويحول السطور لبنود. راجع مطابقة كل سطر بالخدمة الصح قبل الحفظ. PDF المصور مش بيتقري.','price-lists')
frule(W,'السعر الثابت — اختياري','سعر الخدمة في اللائحة دي بالجنيه. لو سبته فاضي بيتحسب من سعر المركز مع الخصومات.','price-lists')
frule(W,'خصم البند %','نسبة خصم للخدمة دي بس من 0 لـ100، بتتطبق قبل خصم اللائحة العام.','price-lists')
frule(W,'خصم البند مبلغ','مبلغ بالجنيه بيتخصم من سعر الخدمة دي بس، بعد خصومات النسبة.','price-lists')
frule(W,'ملاحظات / اسم السطر المستورد','اسم الخدمة كما ورد في ملف الجهة أو أي ملاحظة على البند، علشان المراجع يتأكد من المطابقة.','price-lists')
frule(W,'تاريخ التسعير','تاريخ الخدمة اللي عايز تحسب سعرها. النظام بيختار اللائحة المعتمدة السارية في التاريخ ده. الحساب للعرض بس ومابيعملش حجز.','price-lists')
frule(G,'صلاحية تعديل هذه القائمة','اسمح أو امنع المستخدم المختار من تعديل بنود القائمة. المنع الصريح بيتقدم حتى على منشئ القائمة.','price-lists')
frule(G,'إنشاء إصدار جديد من هذه القائمة','اسمح للمستخدم ينسخ القائمة لإصدار جديد يعدل فيه. النسخة القديمة بتفضل كما هي.','price-lists')
frule(G,'سبب الحذف','اكتب سبب إخفاء القائمة، 3 حروف على الأقل. القائمة المعتمدة أو المرتبطة بعقد مابتتحذفش، والبنود والسجل بيتحفظوا.','price-lists')
frule(G,'العقد','اختار عقد الجهة اللي هتربط بيه مرجع الأسعار. حالة الربط وحالة العقد بيظهروا تحت.','price-lists')
frule(G,'مرجع الأسعار المتفق عليه','اختار القائمة المتفق عليها مع الجهة. ممكن نفس القائمة تترتبط بأكتر من عقد. الربط محتاج اعتماد من شخص تاني غير اللي ربط.','price-lists')
frule(G,'نسبة تحمل الجهة لهذه الخدمة — اتركها فارغة لاستخدام العقد','النسبة اللي الجهة بتدفعها من سعر الخدمة دي بس، من 0 لـ100. فاضية يعني نسبة العقد العامة.','price-lists')
TASKS_ALL='في تكرار المهمة «كل» هو عدد الوحدات بين كل تكرار والتاني، مثل1 مع أسبوع يعني كل أسبوع، وراجع بداية الجدول ونهايته. وفي التعليق «الكل» معناها التعليق يوصل لكل المشاركين في المهمة بدل شخص واحد.'
frule('render-tasks.js','الكل',TASKS_ALL,'tasks-guide')
frule(G,'شروط الخدمة','اكتب شرط الجهة على الخدمة دي، زي عدد مرات أو مستند مطلوب. الشرط بيخص العقد المختار بس.','price-lists')
# --- Contracts, shared tariffs, service mapping and insurance plans ---
C='contract-price-workspace.js'
ENTITY_CODE='كود الخدمة زي ما مكتوب في تعريفة أو ملف الجهة. بيساعد في مطابقتها بخدمة المركز الصح وفي المطالبات.'
frule(C,'اسم اللائحة','اسم واضح للائحة أو التعريفة، زي «أسعار المركز ٢٠٢٧» أو اسم التعريفة المشتركة. الاسم بيظهر في سبب السعر عند الحجز.','price-lists')
frule(C,'رقم النسخة','رقم نسخة اللائحة. الإصدار الجديد بياخد الرقم اللي بعده، والنسخة القديمة بتفضل محفوظة كما هي.','price-lists')
frule(C,'سنة إصدار اللائحة|سنة إصدار التعريفة','السنة اللي الجهة أو المركز أصدروا فيها التعريفة، زي ما مكتوبة على ملف الأسعار. ممكن تختلف عن سنة التطبيق.','price-lists')
frule(C,'سنة التطبيق','السنة اللي الأسعار دي هتتطبق فيها فعلاً على الخدمات. فترة السريان بالتاريخ هي اللي بتحدد التطبيق بالظبط.','price-lists')
frule(C,'خصم عام بالنسبة|خصم القائمة بالنسبة','نسبة خصم من 0 لـ100 على كل بنود القائمة. لو للبند خصم نسبة كمان، النسبتين بيتطبقوا ورا بعض مش بيتجمعوا.','price-lists')
frule(C,'خصم عام لكل وحدة|خصم القائمة بالمبلغ','مبلغ بالجنيه بيتخصم من كل وحدة خدمة بعد خصم النسبة. لو السعر النهائي بقى صفر أو أقل النظام بيرفض.','price-lists')
frule(C,'سارية من|سارية حتى|بداية سريان القائمة|نهاية سريان القائمة','فترة تطبيق القائمة على تاريخ الخدمة. برا الفترة دي القائمة مابتتطبقش حتى لو معتمدة. النهاية لازم تكون بعد البداية.','price-lists')
frule(C,'شروط اللائحة|ملاحظات وشروط الإصدار','اكتب شروط الجهة العامة على الأسعار، زي مستندات مطلوبة أو حدود. للتوضيح للمراجع والاستقبال، ومابتغيرش السعر.','price-lists')
frule(C,'تاريخ الخدمة','تاريخ الخدمة اللي عايز تجرب سعرها. التجربة بتقرا الأسعار المعتمدة في التاريخ ده بس، ومابتعملش حجز ولا فاتورة.','price-lists')
frule(C,'بحث في القوائم','اكتب جزء من اسم القائمة أو الجهة لتصفية القوائم. البحث مابيغيرش حاجة.','price-lists')
frule(C,'توزيع الخدمات حسب أقسام الملف وإنشاء الأقسام غير الموجودة','علّم عليها لو ملف الجهة مقسم أقسام (زي أشعة ومعمل)، علشان كل خدمة تتحط في قسمها ويتعمل القسم الناقص في القائمة دي بس.','price-lists')
frule(C,'اسم الإصدار الجديد','اسم الإصدار اللي هيتعمل كنسخة جديدة من القائمة. الإصدار الجديد بيبدأ مسودة، وربط العقود بالقائمة الأصلية بيفضل زي ما هو.','price-lists')
frule(C,'نسخ الأقسام','علّم عليها علشان الإصدار الجديد ياخد نفس أقسام القائمة الحالية. شيلها لو عايز مسودة فاضية. صلاحيات المستخدمين مابتتنسخش.','price-lists')
frule(C,'اسم الخدمة أو الكود أو القسم|دوّر باسم الخدمة أو الكود أو القسم|بحث داخل سطور الدفعة','اكتب اسم خدمة أو كود أو قسم علشان تلاقي سطر معين في دفعة الاستيراد. البحث مابيغيرش السطور.','price-lists')
frule(C,'كود الجهة',ENTITY_CODE,'price-lists')
frule(C,'السعر','سعر الخدمة بالجنيه زي ما في ملف الجهة. راجعه مع الأصل قبل تأكيد المطابقة.','price-lists')
frule(C,'القسم في الملف','القسم اللي الخدمة كانت تحته في ملف الجهة، زي أشعة أو معمل. بيستخدم لتوزيع الخدمات على أقسام القائمة.','price-lists')
frule(C,'نسبة الزيادة أو التخفيض','نسبة تغيير كل أسعار المسودة أو قسم منها، موجب للزيادة وسالب للتخفيض. راجع المعاينة قبل الحفظ، والتغيير على المسودة بس.','price-lists')
frule(C,'السعر الثابت','سعر الخدمة في القائمة دي بالجنيه. إجباري في القوائم ذات الأسعار الثابتة. لو فاضي بيتحسب من سعر المركز مع الخصم.','price-lists')
frule(C,'خصم النسبة','نسبة خصم للخدمة دي بس من 0 لـ100، بتتطبق قبل خصم القائمة العام.','price-lists')
frule(C,'خصم المبلغ','مبلغ بالجنيه بيتخصم من سعر الخدمة دي بس، بعد خصومات النسبة.','price-lists')
frule(C,'اسم الخدمة عند الجهة','اسم الخدمة زي ما بتكتبه الجهة في تعريفتها أو مطالباتها. بيفضل مربوط بخدمة المركز المعتمدة.','price-lists')
frule(C,'اسم القسم','اسم القسم جوه القائمة دي، زي أشعة أو معمل. القسم بيخص القائمة دي بس ومابيعملش قسم في خدمات المركز.','price-lists')
frule(C,'اسم الخدمة المعتمد','اسم الخدمة الجديدة زي ما هيظهر في خدمات المركز. اتأكد إنها مش موجودة باسم تاني قبل ما تطلب إضافتها، والطلب بيراجعه شخص تاني.','price-lists')
frule(C,'وحدة تقديم الخدمة','الوحدة اللي الخدمة بتتقدم بيها، زي جلسة أو منطقة أو عينة. بتفرق بين خدمتين بنفس الاسم.','price-lists')
frule(C,'سبب الإضافة وتفاصيل تميزها','اشرح ليه الخدمة دي محتاجة تتضاف وإيه اللي يميزها عن الخدمات الموجودة، علشان المراجع يقرر.','price-lists')
frule(C,'سبب الإنهاء','اكتب سبب إنهاء القائمة المعتمدة، زي صدور تعريفة جديدة. بعد الإنهاء القائمة مابتتطبقش على حجوزات جديدة.','price-lists')
N='contract-navigation.js'
frule(N,'بحث عن جهة','اكتب جزء من اسم الجهة أو الكود لتصفية الجهات المتعاقدة. البحث مابيغيرش حاجة.','entities')
frule(N,'التصنيف','اعرض جهات تصنيف معين بس، زي تأمين أو شركات أو نقابات.','entities')
frule(N,'حالة العقد','اعرض الجهات حسب حالة عقدها، زي ساري أو منتهي، أو الجهات اللي مالهاش عقد.','entities')
frule(N,'التجميع','جمّع الجهات في القائمة حسب التصنيف أو حالة العقد علشان تقراها أسهل. التجميع للعرض بس.','entities')
frule(N,'عروضي المحفوظة','اختار عرض حفظته قبل كده بالفلاتر والترتيب بتوعه. العروض بتخصك انت بس.','entities')
frule(N,'اجعله عرض البداية','علّم عليها علشان العرض ده يفتح تلقائي أول ما تدخل الجهات.','entities')
frule(N,'الترتيب','رتب الجهات حسب الاسم أو أقرب موعد متابعة أو أقرب نهاية عقد. الترتيب للعرض بس.','entities')
frule(N,'اسم العرض','اسم قصير للفلاتر والترتيب الحاليين علشان ترجعلهم بسرعة من «عروضي المحفوظة».','entities')
frule(C,'الملف','اختار ملف أسعار الجهة (Excel أو CSV أو Word أو PDF نصي). الملف بيتقري على جهازك ويتحول لدفعة سطور تراجعها قبل ما تتضم للقائمة.','price-lists')
frule(C,'الوحدة','وحدة تقديم الخدمة زي جلسة أو منطقة أو عينة، زي ما في ملف الجهة. راجعها قبل تأكيد المطابقة لأنها بتفرق بين خدمتين بنفس الاسم.','price-lists')
M='contract-service-mapping.js'
frule(M,'اختيار من قائمة سونو','اختار خدمة من خدمات المركز علشان تشوف مربوطة بأنهي اسم عند الجهة.','price-lists')
frule(M,'اختيار من قائمة الجهة','اختار خدمة من أسماء الجهة علشان تشوف مربوطة بأنهي خدمة في المركز.','price-lists')
frule(M,'المسمى المعتمد في سونو','خدمة المركز الأصلية اللي اسم الجهة هيتربط بيها. اختارها بدقة لأن السعر والمطالبة بيمشوا عليها.','price-lists')
frule(M,'اسم الخدمة في جهة التعاقد','اسم الخدمة زي ما الجهة بتكتبه. المطابقة بتخلي النظام يفهم إن الاسمين نفس الخدمة.','price-lists')
frule(M,'كود الجهة',ENTITY_CODE,'price-lists')
R='service-mapping-review.js'
frule(R,'قائمة الجهة','اختار تعريفة الجهة اللي عايز تراجع مطابقة أسماء خدماتها.','price-lists')
frule(R,'راجعت العينة والوحدة وعدد الجلسات والمنطقة وشمول المستلزمات','علّم عليها بس بعد ما تتأكد إن سطر الجهة وخدمة المركز متطابقين في نوع العينة والوحدة وعدد الجلسات والمنطقة والمستلزمات. اقتراحات المساعد مش اعتماد.','price-lists')
frule(R,'قسم الخدمة المقترحة','القسم اللي الخدمة الجديدة المقترحة هتتحط فيه في خدمات المركز لو الطلب اتعتمد.','price-lists')
P='service-search-picker.js'
frule(P,'خدمة المركز|ابحث في خدمات سونو|اكتب اسمًا أو كلمة أو كودًا','اكتب جزء من اسم الخدمة أو كودها واختار الخدمة الصح من النتايج. لو مش لاقيها جرب كلمة تانية أو الكود.','price-lists')
frule('center-master-review.js','راجعت فترة التطبيق والأسعار والخدمات','علّم عليها بعد ما تراجع فترة السريان والأسعار والخدمات الجديدة. المراجعة لازم تكون من حساب تاني غير اللي جهز المطابقات.','price-lists')
frule('center-master-review.js','أؤكد أن السطور المتطابقة الموضحة تمثل خدمة واحدة','أكّد بس لو السطور المتجمعة فعلاً نفس الخدمة. لو فيه اختلاف في الوحدة أو النوع، ماتأكدش.','price-lists')
frule('finance-contract-signature.js','المقدمة','نص بداية العقد قبل البنود. ممكن تستخدم المتغيرات المكتوبة تحت زي اسم الطبيب ورقم المرجع، وجدول الشروط المالية بيتضاف تلقائي بعد البنود.','payroll')
I='insurance-contracts.js'
frule(I,'شركة/عقد التأمين','اختار عقد شركة التأمين اللي عايز تدير فئاته وتحمله ومطالباته.','insurance')
frule(I,'اسم الفئة/الكارنيه','اسم فئة الكارنيه زي ما في عقد الشركة، زي فضي أو ذهبي. كل فئة ممكن يبقى لها تحمل ولائحة أسعار مختلفة.','insurance')
frule(I,'كود الفئة','كود الفئة عند شركة التأمين لو موجود، بيساعد في المطالبات.','insurance')
frule(I,'لائحة الأسعار','اختار لائحة الأسعار اللي تتطبق على الفئة دي، أو سيبها على لائحة العقد الافتراضية.','insurance')
frule(I,'نوع تحمل المريض|نوع التحمل','اختار اللي المريض بيدفعه: بدون تحمل، أو نسبة من السعر، أو مبلغ ثابت. في استثناءات الخدمات «حسب الفئة» معناها نفس تحمل الفئة.','insurance')
frule(I,'قيمة التحمل|القيمة','النسبة أو المبلغ اللي المريض بيدفعه حسب نوع التحمل. الباقي بيبقى مطالبة على شركة التأمين.','insurance')
frule(I,'سارية من|سارية حتى','فترة سريان الفئة أو الاستثناء. لو النهاية فاضية تبقى مفتوحة.','insurance')
frule(I,'فئة الكارنيه','اختار فئة الكارنيه بتاعة المريض زي ما مكتوبة على الكارت. الفئة بتحدد التحمل ولائحة الأسعار.','insurance')
frule(I,'رقم الكارنيه / العضوية|اختياري','رقم كارت التأمين أو العضوية زي ما مكتوب على الكارت. اختياري، بس بيسهل المطالبة.','insurance')
frule(I,'الخزينة/الوردية','اختار الخزينة أو الوردية اللي استلمت الفلوس لو التحصيل كاش. التحويل البنكي مش محتاج خزينة.','insurance')
frule(I,'رقم التحويل/الإيصال|مرجع التحصيل','اكتب رقم التحويل أو الإيصال من مستند الشركة. المرجع بيمنع تسجيل نفس التحصيل مرتين.','insurance')
# --- Human resources workspaces (hr-*.js) ---
frule('hr-closures.js','اسم الأجازة (مثلًا عيد الأضحى)','اكتب اسم الأجازة الرسمية زي ما هتظهر للموظفين والاستقبال، مثل عيد الأضحى.','hr-manage')
frule('hr-closures.js','من يوم|إلى يوم (سيبه فاضي لو يوم واحد)','أيام الأجازة الرسمية. سيب «إلى» فاضي لو يوم واحد. بعد اعتمادها من سوبر أدمن أو مدير عام تاني، الحجز بيتقفل في الأيام دي والحضور مابيتحسبش غياب.','hr-manage')
frule('hr-closures.js','سبب الإلغاء','اكتب ليه بتلغي الأجازة. بعد الإلغاء الحجز بيرجع مفتوح في الأيام دي والحضور بيتحسب عادي.','hr-manage')
frule('hr-custody.js','بحث بالبند أو الكود أو الشخص','اكتب اسم البند أو كوده أو اسم الموظف اللي معاه العهدة لتصفية السجل. البحث مابيغيرش حاجة.','hr-offboarding')
frule('hr-custody.js','اسم البند','اسم العهدة بوضوح، زي لابتوب أو مفتاح المخزن أو موبايل الشغل.','hr-offboarding')
frule('hr-custody.js','الوصف','تفاصيل تميز البند، زي اللون أو الحالة أو الملحقات اللي معاه.','hr-offboarding')
frule('hr-custody.js','الرقم التسلسلي أو المرجع','الرقم التسلسلي للجهاز أو رقم الأصل، علشان مايتلخبطش مع بند شبهه.','hr-offboarding')
frule('hr-custody.js','القيمة بالجنيه','قيمة البند بالجنيه. لو الموظف ساب الشغل من غير ما يرجعه، القيمة دي بتظهر في مخالصته.','hr-offboarding')
frule('hr-custody.js','يُسلَّم الآن إلى (اختياري)','اختار الموظف اللي استلم البند دلوقتي، أو سيبه فاضي لو البند لسه في المخزن.','hr-offboarding')
frule('hr-custody.js','تاريخ التسليم','اليوم اللي الموظف استلم فيه العهدة فعلاً.','hr-offboarding')
frule('hr-custody.js','مصدر البند (اختياري)','منين جه البند، زي شراء أو تحويل من فرع، لو حابب تسجله.','hr-offboarding')
frule('hr-custody.js','تاريخ الإرجاع','اليوم اللي الموظف رجّع فيه العهدة. بعد الإرجاع مابتظهرش في مخالصته.','hr-offboarding')
frule('hr-custody.js','سبب تغيير القيمة (إن تغيّرت)','لو غيرت قيمة البند اكتب السبب، زي تلف أو إهلاك. التغيير بيتسجل في سجل البند.','hr-offboarding')
frule('hr-insurance.js','بحث بالاسم أو الكود أو رقم التأمين','اكتب اسم الموظف أو كوده أو رقمه التأميني لتصفية الاشتراكات.','hr-offboarding')
frule('hr-insurance.js','رقم التأمين','الرقم التأميني للموظف زي ما في مستندات التأمينات.','hr-offboarding')
frule('hr-insurance.js','استقطاع الموظف شهريًا من الراتب','المبلغ اللي بيتخصم من مرتب الموظف كل شهر للتأمينات. بيتقري تلقائي في شاشة حساب المرتب.','hr-offboarding')
frule('hr-insurance.js','حصة المركز شهريًا (إن وجدت)','المبلغ اللي المركز بيدفعه عن الموظف شهريًا، لو موجود. مابيتخصمش من المرتب.','hr-offboarding')
frule('hr-insurance.js','تاريخ بدء الاشتراك','اليوم اللي اشتراك الموظف في التأمينات بدأ فيه فعلاً.','hr-offboarding')
frule('hr-insurance.js','سبب تغيير المبلغ (إن تغيّر)','لو غيرت مبلغ الاستقطاع أو حصة المركز اكتب السبب، زي زيادة الأجر التأميني.','hr-offboarding')
frule('hr-insurance.js|hr-offboarding.js','تاريخ الإيقاف','آخر يوم في اشتراك التأمينات، غالبًا آخر يوم شغل.','hr-offboarding')
frule('hr-insurance.js|hr-offboarding.js','رقم أو مرجع إخطار الإيقاف|رقم أو مرجع الإخطار','رقم إخطار إيقاف الاشتراك اللي اتقدم للتأمينات، علشان يبقى فيه دليل إنه اتعمل.','hr-offboarding')
frule('hr-insurance.js|hr-offboarding.js','آخر موعد للإخطار (يكتبه المسؤول يدويًا)|آخر موعد للإخطار (يكتبه المسؤول يدويًا — لا يحسبه النظام)','اكتب آخر يوم مسموح فيه بتقديم الإخطار حسب قواعد التأمينات. النظام مابيحسبهوش، بس بيفكرك بيه.','hr-offboarding')
frule('hr-offboarding.js','آخر يوم عمل','آخر يوم الموظف هيشتغل فيه فعلاً. منه بيتحسب المستحق له والمستحق عليه في المخالصة.','hr-offboarding')
frule('hr-offboarding.js','سبب الإلغاء','اكتب ليه بتلغي إجراء إنهاء الخدمة، زي إن الموظف رجع في استقالته.','hr-offboarding')
frule('hr-offboarding.js','الوصف','وصف البند في كشف المخالصة، زي مرتب آخر شهر أو سلفة أو لابتوب.','hr-offboarding')
frule('hr-offboarding.js','القيمة (للمستند 0)','قيمة البند بالجنيه. لو البند مستند أو عقد مع الموظف اكتب صفر.','hr-offboarding')
frule('hr-offboarding.js','المعالجة','اختار إيه اللي حصل للبند: اتسلّم، أو يتخصم من مستحقاته، أو تنازل.','hr-offboarding')
frule('hr-offboarding.js','ملاحظة (إجبارية عند التنازل أو الخصم)','اكتب سبب التنازل أو الخصم ومين وافق عليه. إجبارية في الحالتين دول.','hr-offboarding')
frule('hr-offboarding.js','رابط الملف الموقع','ارفع المخالصة الموقعة على مجلد مستندات المركز والصق الرابط (يبدأ بـ https). بعد كده بس شهادة الخبرة بتتفتح.','hr-offboarding')
frule('hr-offboarding.js','مرجع الصرف','رقم إذن الصرف أو التحويل اللي اتصرف بيه صافي المخالصة.','hr-offboarding')
frule('hr-offboarding.js','تاريخ الصرف','اليوم اللي الموظف استلم فيه صافي المخالصة فعلاً.','hr-offboarding')
frule('hr-offboarding.js','سبب الاستثناء','اكتب ليه شهادة الخبرة لازم تطلع قبل المخالصة الموقعة. اسمك والسبب بيتسجلوا. ده للمالك بس.','hr-offboarding')
frule('hr-offboarding.js','النص','نص المخالصة أو شهادة الخبرة اللي هيتطبع. التعديل بيعمل نسخة جديدة، والقديمة بتفضل محفوظة.','hr-offboarding')
frule('hr-offboarding.js','ملاحظة على النسخة (مثلًا: مراجعة المحامي)','اكتب إيه اللي اتغير في النص ومين راجعه.','hr-offboarding')
P='hr-payroll-workspace.js'
frule(P,'توقيت الأوقات غير المزودة بمنطقة زمنية','اختار توقيت القاهرة الصح للملف: UTC+2 أو UTC+3 في التوقيت الصيفي. بيتطبق على الأوقات المكتوبة من غير منطقة زمنية.','hr-payroll')
frule(P,'Excel أو CSV','اختار ملف Excel أو CSV بالأعمدة المكتوبة تحت بالترتيب. الملف بيتقري على جهازك ويظهر معاينة تراجعها قبل الحفظ، والحفظ بيبعته للمراجعة.','hr-payroll')
frule(P,'تحل محل قاعدة معتمدة (لتعديل قاعدة سابقة)','لو بتعدل قاعدة معتمدة اختارها هنا، والجديدة هتحل محلها بعد الاعتماد. «قاعدة جديدة» لو أول مرة.','hr-payroll')
frule(P,'حتى','آخر يوم تسري فيه قاعدة الأجر. «من» و«حتى» بيحددوا الشهور اللي القاعدة بتتطبق عليها.','hr-payroll')
frule(P,'سماح التأخير بالدقائق','عدد دقايق التأخير المسموح بيها قبل ما الخصم يبدأ، حسب العقد أو اللائحة.','hr-payroll')
frule(P,'خصم كل دقيقة تأخير بعد السماح','المبلغ بالجنيه اللي بيتخصم عن كل دقيقة تأخير بعد السماح. صفر لو مفيش خصم تأخير.','hr-payroll')
frule(P,'خصم الوردية المسجلة غيابًا','المبلغ اللي بيتخصم عن كل وردية اتسجلت غياب، حسب العقد أو اللائحة.','hr-payroll')
frule(P,'مقابل ساعة الإضافي','المبلغ بالجنيه لكل ساعة إضافي معتمدة. صفر لو مفيش إضافي مدفوع.','hr-payroll')
frule(P,'حد أدنى مضمون','«نعم» معناها الموظف ياخد الأكبر: المرتب أو النسبة. «لا» معناها ياخد المرتب زائد النسبة.','hr-payroll')
frule(P,'مرجع الاتفاق وقواعد الحساب','اكتب رقم العقد أو اللائحة اللي القاعدة دي جاية منها، علشان المراجع يتأكد.','hr-payroll')
frule(P,'شهر الاستحقاق','الشهر اللي البند ده هيتحسب في مرتبه.','hr-payroll')
frule(P,'المبلغ للمكافأة أو الخصم','قيمة المكافأة أو الخصم بالجنيه. في نسبة الخدمة سيبه صفر واملا الخدمة والقيمة والنسبة.','hr-payroll')
frule(P,'الخدمة عند اختيار نسبة','الخدمة اللي الموظف بياخد عليها نسبة، لما يكون النوع «نسبة خدمة».','hr-payroll')
frule(P,'قيمة الخدمات المثبتة بالمستند','إجمالي قيمة الخدمات اللي النسبة بتتحسب عليها، زي ما في المستند.','hr-payroll')
frule(P,'نسبة استحقاق الموظف','النسبة من 0 لـ100 اللي الموظف بياخدها من قيمة الخدمات.','hr-payroll')
frule(P,'مرجع مستند لا يتكرر','رقم المستند اللي البند جاي منه. مايتكررش علشان نفس البند مايتحسبش مرتين.','hr-payroll')
frule(P,'تفاصيل المستند والخدمات والفترة','اشرح البند: المستند والخدمات والفترة، علشان المراجع يعتمده.','hr-payroll')
frule(P,'سبب القرار بعد مراجعة تفاصيل الحضور','اكتب نتيجة مراجعتك لملف الحضور وليه اعتمدته أو رفضته. المراجع لازم يكون غير اللي رفع الملف.','hr-payroll')
frule(P,'ضريبة الأجور حسب المستند','ضريبة كسب العمل المستقطعة الشهر ده من مستند الضريبة، أو صفر.','hr-payroll')
frule(P,'التأمينات حسب المستند','حصة الموظف في التأمينات المستقطعة الشهر ده، أو صفر.','hr-payroll')
frule(P,'استرداد السلفة المعتمد','المبلغ اللي هيتخصم الشهر ده من سلفة معتمدة بموافقة مكتوبة، أو صفر.','hr-payroll')
frule(P,'مرجع استحقاق الشهر','رقم يميز استحقاق مرتب الموظف ده للشهر ده. بيمنع تكرار نفس الاستحقاق.','hr-payroll')
frule(P,'تأكيد مراجعة اكتمال ورديات الشهر والمستندات','اكتب إنك راجعت إن كل ورديات الشهر والمستندات متسجلة ومعتمدة قبل ما تبعت الحساب.','hr-payroll')
frule(P,'نوع الجهاز','نوع الجهاز اللي عايز تربطه، زي بصمة الحضور والانصراف.','hr-payroll')
frule(P,'اسم الجهاز','اسم يميز الجهاز، زي بصمة الاستقبال.','hr-payroll')
frule(P,'الموديل','موديل الجهاز زي ما مكتوب عليه. الربط بيعتمد على إن الموديل مدعوم.','hr-payroll')
frule(P,'البرنامج المستخدم أو تفاصيل الشركة','البرنامج اللي شغال مع الجهاز أو الشركة اللي ركبته. الحفظ بيسجل طلب تجهيز بس، مش ربط فعلي.','hr-payroll')
frule('hr-presence.js','اختر الموظف','اختار الموظف صاحب رقم البصمة ده علشان يظهر باسمه في «الحضور الآن». ممكن تغير الربط أو تشيله في أي وقت.','hr-manage')
S='hr-shift-swaps.js'
frule(S,'صاحب الطلب','الموظف اللي طالب التبديل.','hr-manage')
frule(S,'الزميل (من نفس القسم)','الزميل اللي هيبدل معاه، ولازم يكون من نفس القسم. الزميل بيوافق الأول، وبعده الموارد البشرية.','hr-manage')
frule(S,'اليوم (يوم صاحب الطلب)','يوم وردية صاحب الطلب اللي عايز يبدله.','hr-manage')
frule(S,'يوم الزميل (للتبديل بين يومين فقط)','املاه بس لو كل واحد هيشتغل يوم التاني. سيبه فاضي لو التبديل في نفس اليوم (كل واحد ياخد مواعيد التاني).','hr-manage')
frule(S,'طلب طارئ (أقل من 24 ساعة)','علّم عليها لو الطلب قبل الوردية بأقل من 24 ساعة. الطلب الطارئ بيتراجع كاستثناء.','hr-manage')
H='hr-shifts.js'
frule(H,'اسم الوردية','اسم يميز الوردية، زي صباحي أو مسائي.','hr-manage')
frule(H,'تبدأ|تنتهي','ميعاد بداية ونهاية الوردية. لو النهاية قبل البداية (زي 21:00 لـ 05:00) بتتحسب وردية ليلية بتخلص تاني يوم.','hr-manage')
frule(H,'دقائق السماح قبل احتساب التأخير','عدد الدقايق المسموحة بعد بداية الوردية قبل ما الحضور يتحسب تأخير.','hr-manage')
frule(H,'اللون','لون الوردية في الجدول علشان تفرقها بسرعة. للعرض بس.','hr-manage')
frule(H,'تعبئة سريعة (كل الأيام ما عدا الجمعة)','اختار وردية وهي تتحط على كل أيام الأسبوع ما عدا الجمعة مرة واحدة. تقدر تعدل أي يوم بعدها.','hr-manage')
frule(H,'يسري من','اليوم اللي الجدول الجديد يبدأ منه. مابيغيرش حضور الأيام اللي قبله.','hr-manage')
T='hr-tax.js'
frule(T,'الشهر','الشهر اللي الضريبة دي مستقطعة فيه.','hr-payroll')
frule(T,'الضريبة المستقطعة بالجنيه','الضريبة المستقطعة من مرتب الموظف الشهر ده من مستند الضريبة. الرقم ده بيظهر تلقائي في حساب المرتب.','hr-payroll')
frule(T,'الوعاء الخاضع للضريبة (اختياري)','المبلغ اللي الضريبة اتحسبت عليه، لو موجود في المستند.','hr-payroll')
frule(T,'مرجع مستند الضريبة','رقم مستند أو كشف الضريبة اللي الرقم جاي منه.','hr-payroll')
frule(T,'سبب تغيير المبلغ (إن تغيّر)','لو عدلت مبلغ الضريبة اكتب السبب، زي تصحيح في المستند.','hr-payroll')
# --- Finance: entity claims, booking channels, doctor fees and payouts, staff tax/insurance payments ---
E='entity-claims.js'
PAY_METHOD='إزاي المريض دفع نصيبه (التحمل): كاش أو فيزا أو تحويل أو InstaPay أو محفظة.'
PAY_REF='رقم الإيصال أو العملية لتحصيل نصيب المريض، لو الدفع مش كاش.'
frule(E,'بحث في الفواتير','اكتب رقم فاتورة أو اسم مريض أو خدمة لتصفية فواتير الجهة في الفترة المختارة. البحث مابيغيرش حاجة.','insurance')
frule(E,'مرجع المطالبة','رقم يميز المطالبة دي، بيتملى تلقائي بكود CLM. عدله لو الجهة بتطلب ترقيم معين. مايتكررش.','insurance')
frule(E,'الأدوية','مين بيدفع تمن الأدوية في العقد ده: المريض أو الجهة. لازم يتحدد قبل الفوترة.','insurance')
frule(E,'رقم الفاتورة','رقم فاتورة الخدمة للجهة، بيتملى تلقائي بكود INV. مايتكررش، ولو عدته بنفس الرقم مش هتتعمل فاتورة تانية.','insurance')
frule(E,'المستلزمات','مين بيدفع تمن المستلزمات في العقد ده: المريض أو الجهة. لازم يتحدد قبل الفوترة، وعدم تطبيق الخصم مابيحددش مين بيدفع.','insurance')
frule(E,'مهلة السداد بعد تقديم المطالبة بالأيام','عدد الأيام اللي الجهة المفروض تسدد فيها بعد تقديم المطالبة، حسب العقد. بيستخدم في متابعة المتأخرات.','insurance')
frule(E,'المستندات المطلوبة للمطالبة','اكتب المستندات اللي الجهة بتطلبها مع كل مطالبة، زي صورة الكارنيه أو الموافقة أو التقرير، علشان تتجهز قبل التقديم.','insurance')
frule(E,'نص يطبع على الفاتورة','نص ثابت بيتطبع على فواتير الجهة دي، زي اسم العقد أو رقم الاتفاق.','insurance')
frule(E,'اسم المريض أو الرقم الطبي أو رقم الزيارة','دوّر على زيارة المريض المربوطة بجهة تعاقد علشان تعمل فاتورة الخدمة. لو مش ظاهرة، سجل الزيارة واربط العقد الأول.','insurance')
frule(E,'بحث عن الخدمة','اكتب اسم الخدمة أو كودها علشان تختار الخدمة اللي اتعملت للمريض.','insurance')
frule(E,'رقم البطاقة / العضوية','رقم كارنيه المريض أو عضويته عند الجهة، زي ما مكتوب على الكارت. بيتطبع على الفاتورة والمطالبة.','insurance')
frule(E,'اسم الصنف أو المخزن|بحث في الأصناف المتاحة','دوّر على الدوا أو المستلزم اللي اتصرف للخدمة دي. سجل بس اللي اتصرف فعلاً ومااتسجلش من شاشة تانية.','insurance')
frule(E,'طريقة تحصيل المريض',PAY_METHOD,'insurance')
frule(E,'الوردية المفتوحة','اختار الوردية اللي استلمت فلوس المريض لو التحصيل كاش.','insurance')
frule(E,'مرجع تحصيل المريض',PAY_REF,'insurance')
frule(E,'أؤكد تنفيذ الخدمة وصرف البنود المسجلة لها، وعدم إدخال صرف سبق تسجيله.','علّم عليها بعد ما تتأكد إن الخدمة اتعملت فعلاً، والأدوية والمستلزمات المكتوبة اتصرفت ومش متسجلة قبل كده.','insurance')
frule(E,'سبب تكرار تنفيذ الخدمة','الخدمة دي اتفوترت قبل كده لنفس المريض. لو ده تنفيذ تاني فعلاً اكتب السبب، زي جلسة تانية.','insurance')
frule(E,'راجعت بيان الفواتير ومتطلبات المستندات وأثر هذا الإجراء.','علّم عليها بعد ما تراجع فواتير المطالبة ومستنداتها وتفهم أثر الإجراء. الفواتير وحركات التحصيل بتفضل محفوظة.','insurance')
frule(E,'اسم المستند','اسم واضح للمستند المرفق بالمطالبة، زي خطاب التقديم أو إيصال الاستلام.','insurance')
frule(E,'رابط Google Drive','رابط المستند على درايف المركز. اتأكد إن المشاركة محدودة.','insurance')
frule(E,'أو رفع مستند للأرشيف','بدل الرابط، ارفع ملف المستند نفسه علشان يتحفظ في أرشيف المطالبة.','insurance')
frule(E,'مبلغ التحصيل','المبلغ اللي الجهة دفعته فعلاً بالجنيه. مايزيدش عن المتبقي على المطالبة.','insurance')
frule(E,'رقم التحويل أو الإيصال','رقم التحويل البنكي أو الإيصال من الجهة. بيمنع تسجيل نفس التحصيل مرتين.','insurance')
frule(E,'مرجع خطاب الجهة','رقم خطاب الجهة اللي فيه الرفض أو الخصم أو التسوية. المعالجة مابتغيرش المديونية غير بعد اعتماد المراجع.','insurance')
F='finance-channels.js'
frule(F,'قناة الحجز / المنصة','اختار القناة اللي المريض حجز منها، زي منصة حجز أو نقابة أو تليفون. النظام بيحفظ نسخة من قاعدتها على الفاتورة.','invoice')
frule(F,'قيمة الكشف قبل الخصم|قيمة الخدمات الأخرى قبل الخصم','قيمة الكشف والخدمات قبل خصم القناة، علشان النظام يحسب خصم المريض وحصة القناة. الحساب بيظهر تحت.','invoice')
frule(F,'الكود (حروف إنجليزية صغيرة وأرقام و _)','كود ثابت للقناة بحروف إنجليزية صغيرة وأرقام، زي vezeeta. مابيتغيرش في الإصدارات الجديدة.','invoice')
frule(F,'اسم القناة كما يظهر للمحاسب','اسم القناة زي ما هيظهر للكاشير والمحاسب عند الفوترة.','invoice')
frule(F,'نوع القناة','منصة خارجية أو قناة داخلية للمركز (زي التليفون والواتساب) أو جهة تعاقد.','invoice')
frule(F,'تسري على','القاعدة بتتطبق على الكشف بس، ولا على الكشف وكل الخدمات.','invoice')
frule(F,'خصم المريض %','نسبة الخصم اللي المريض بياخدها لما يحجز من القناة دي.','invoice')
frule(F,'حصة المنصة أو القناة % (تُخصم من وعاء الطبيب)','نسبة القناة من القيمة. بتتخصم من وعاء الطبيب قبل حساب نسبته، وبتقل تلقائي مع المرتجعات.','invoice')
frule(F,'تُدفع لمن؟','الحصة بتروح فين: تفضل في المركز، أو عمولة للمنصة، أو كاش باك للجهة.','invoice')
frule(F,'متى تُدفع (مثال: آخر الشهر)','ميعاد دفع الحصة حسب الاتفاق، زي آخر الشهر.','invoice')
frule(F,'مصادر الحجز المرتبطة (مفصولة بفاصلة)','أكواد مصادر الحجز في الاستقبال اللي تخص القناة دي، بينهم فاصلة، علشان القناة تتختار لوحدها.','invoice')
frule(F,'أؤكد أن النسب مطابقة لاتفاق المركز مع هذه الجهة، وأن القاعدة لن تعمل قبل اعتماد شخص آخر.','علّم عليها بعد ما تراجع النسب مع الاتفاق. القاعدة مش هتشتغل غير بعد اعتماد شخص تاني.','invoice')
frule(F,'سبب الإنهاء','اكتب ليه القاعدة بتنتهي. الفواتير القديمة بتحتفظ بنسخة القاعدة، والجديدة مش هتستخدمها.','invoice')
frule('finance-doctor-accounts.js|finance-doctors.js','بحث باسم الدكتور أو كوده','اكتب اسم الطبيب أو كوده لتصفية القائمة. البحث مابيغيرش حاجة.','payroll')
frule('finance-doctor-accounts.js','اختر الطبيب من الموارد البشرية','اختار الطبيب المسجل في الموارد البشرية. الكود والاسم بيتملوا تلقائي من ملفه.','payroll')
frule('finance-doctor-accounts.js','عرض باقي الموظفين (ممرضين وغيرهم وغير المصنفين)','علّم عليها علشان تختار كمان من الممرضين أو الموظفين اللي نوعهم مش متحدد.','payroll')
frule('finance-doctor-dues.js|finance-doctor-payout.js','نسبة الضريبة %','نسبة الضريبة اللي بتتخصم من الأتعاب المختارة عند الصرف، حسب وضع الطبيب الضريبي.','payroll')
frule('finance-doctor-dues.js|finance-doctor-payout.js','نسبة الاستقطاع %','نسبة أي استقطاع تاني متفق عليه من الأتعاب عند الصرف، أو صفر.','payroll')
D='finance-doctors.js'
frule(D,'خدمة خارجية (مبلغ إضافي يُضاف على فاتورة المريض)','علّم عليها لو الخدمة ليها مبلغ إضافي المريض بيدفعه فوق سعرها. المبلغ ده مابيدخلش في وعاء أتعاب الطبيب.','payroll')
frule(D,'المبلغ الإضافي (جنيه)','المبلغ اللي بيتضاف على فاتورة المريض فوق سعر الخدمة، مثلاً خدمة 500 وإضافي 250 يبقى 750.','payroll')
frule(D,'منفّذ الخدمة','مين بينفذ الخدمة: الطبيب، أو ممرض لوحده، أو ممرض مع طبيب. ده بيحدد مين ياخد الأتعاب.','payroll')
frule(D,'الممرض','اختار الممرض اللي بينفذ الخدمة لو المنفذ ممرض.','payroll')
frule(D,'المبلغ الثابت (جنيه) لكل خدمة تُنفَّذ','مبلغ ثابت للطبيب عن كل خدمة بيعملها، من غير نسبة. لو الفاتورة اتخفضت أو اتمرتجعت بيقل بنفس النسبة.','payroll')
frule(D,'كود الخدمة أو اسمها','الخدمة اللي العقد أو السطر ده يخصها. اكتب الكود أو الاسم زي ما في الحجز.','payroll')
frule(D,'القيمة','قيمة السطر ده من الفاتورة. مجموع السطور لازم يساوي قيمة الخدمة من غير المستلزمات.','payroll')
frule(D,'كشف','علّم عليها لو السطر ده كشف، علشان تتطبق عليه نسبة عقد الكشف.','payroll')
frule(D,'نطاق العقد','العقد على خدمة محددة، أو كذا خدمة، أو قسم كامل. عقد الخدمة المحددة بيتقدم على عقد القسم.','payroll')
frule(D,'اسم الخدمة أو كودها أو القسم|بحث في الخدمات','دوّر على الخدمات اللي العقد هيغطيها وعلّم عليها.','payroll')
frule(D,'نوع الأتعاب','نسبة من وعاء الخدمة، أو مبلغ ثابت لكل خدمة.','payroll')
frule(D,'آخر يوم يسري فيه العقد','آخر يوم العقد بيتطبق فيه. الخدمات بعده مش هتحسب أتعاب بالعقد ده.','payroll')
frule(D,'سبب الإنهاء','اكتب ليه العقد بينتهي، زي اتفاق جديد أو سيب الطبيب للمركز.','payroll')
frule(D,'يسري من (بعد النهارده)','اليوم اللي التعديل يبدأ منه، ولازم يكون بعد النهارده. الفواتير اللي قبله بتفضل بالعقد القديم.','payroll')
frule(D,'مرجع التعديل','رقم ملحق العقد أو المستند اللي فيه التعديل.','payroll')
frule(D,'سبب التعديل','اشرح التعديل وسببه علشان المراجع يعتمده.','payroll')
frule(D,'القرار على كل العقود المعلّقة لهذا الطبيب|القرار على كل عقود المجموعة','اعتماد أو رفض كل العقود المعلقة مرة واحدة. المراجع لازم يكون غير اللي عمل العقود، واكتب سبب القرار.','payroll')
for f in ['finance-staff-insurance.js','finance-staff-tax.js']:
 frule(f,'الشهر','الشهر اللي بتسدد عنه. الأرقام بتتجمع من سجلات الموارد البشرية والمرتبات المعتمدة للشهر ده.','payroll')
 frule(f,'المبلغ المسدد للجهة','المبلغ اللي اتدفع فعلاً للجهة بالجنيه. السداد اللي يزيد عن الرصيد المثبت في الدفاتر مابيتعتمدش.','payroll')
 frule(f,'شرح السداد','اكتب تفاصيل السداد، زي الفترة وطريقة الدفع.','payroll')
frule('finance-staff-insurance.js','رقم إيصال أو مرجع السداد للجهة','رقم إيصال سداد التأمينات من الجهة.','payroll')
frule('finance-staff-tax.js','رقم إيصال أو مرجع السداد للمصلحة','رقم إيصال سداد ضريبة المرتبات من مصلحة الضرايب.','payroll')
B='insurance-billing.js'
frule(B,'اسم المريض / رقم الملف / رقم الزيارة|بحث عن المريض أو الزيارة','دوّر على زيارة المريض المؤمن عليه علشان تعمل فاتورتها.','insurance')
frule(B,'طريقة تحصيل المريض',PAY_METHOD,'insurance')
frule(B,'رقم الإيصال/العملية|مرجع تحصيل المريض',PAY_REF,'insurance')
frule('render-staffkpi.js','متوسط الفريق','متوسط نقاط الموظفين اللي ليهم تقييم في الفترة (من 100)، وتحته مقارنة بالفترة اللي قبلها بنفس الطول.','team-performance')
frule('render-staffkpi.js','أداء جيد (80 فأكتر)','عدد الموظفين اللي نقاطهم 80 أو أكتر من اللي ليهم تقييم في الفترة.','team-performance')
frule('render-staffkpi.js','محتاجين متابعة','عدد الموظفين اللي عندهم مؤشر واحد على الأقل تحت 60٪ من المستهدف بعينة كفاية.','team-performance')
frule('render-staffkpi.js','نشاط قليل','موظفين مفيش لهم بيانات كفاية في الفترة، فمش بيتقيّموا لحد ما يبقى فيه نشاط مسجّل.','team-performance')
frule('render-summary.js','الوصول','عدد الحسابات اللي وصلها المحتوى في الأسبوع حسب التقرير الأصلي. ماتدخلش مرات الظهور بدل الوصول.','indicators')
frule('summary-v2.js','اتنشر','عدد المواد اللي اتنشرت في الفترة المختارة (اليوم أو الأسبوع أو الشهر)، وتحته المقارنة بالفترة اللي قبلها بنفس الطول.','summary-overview')
frule('accounting-shell.js','ابحث في أقسام الحسابات|ابحث في الحسابات…','اكتب جزء من اسم القسم، زي «الأطباء» أو «التحصيل»، والقايمة الجانبية هتعرض الأقسام اللي فيها الكلمة دي بس. البحث بيصفي القايمة ومش بيغير أي بيانات.','accounting-shell')
frule('render-accounting.js','قسم الخدمة في سونو','القسم اللي الخدمة بتظهر تحته في الحجز والتقارير، زي أشعة أو معمل.','add-doctor-service-booking')
frule('render-accounting.js','يتباع من (اختياري)','أول يوم الباكج ده يظهر في «تعاقد على باكج». فاضي = من دلوقتي.','package-offers')
frule('render-accounting.js','يتباع لحد (اختياري)','آخر يوم العرض. بعده الباكج مش بيتباع، واللي اتباع بيفضل ساري مدته.','package-offers')
frule('render-accounting.js','أقل دفعة أولى % من قيمة الباكج','المريض لازم يدفع النسبة دي قبل أول جلسة، وكل دفعة بعدها متقلش عنها أو عن الباقي على الزيارات اللي فاضلة. فاضي = مفيش حد.','package-offers')
frule('render-accounting.js','سعر الباكج الثابت (ج.م)','السعر اللي هيظهر في «تعاقد على باكج» في الاستقبال بالظبط، ومش بيتغير لما سعر أي خدمة جوه الباكج يتغير. لازم أكبر من صفر.','package-fixed-price')
# --- Reception, today operations, lab links, patient 360, test records ---
L='lab-link-review.js'
frule(L,'العينة','نوع عينة التحليل زي ما في قائمة المعمل، زي دم أو بول. في الفلتر بتعرض تحاليل عينة معينة بس، وفي الخدمة الجديدة بتتسجل معاها.','price-lists')
frule(L,'الثقة','درجة تطابق اقتراح الربط الآلي: عالية أو متوسطة أو ضعيفة أو مفيش اقتراح. للتصفية بس، ومفيش ربط بيتأكد من غير ما شخص يضغط.','price-lists')
frule(L,'الإصدار','اختار إصدار قائمة المعمل الشريك اللي عايز تراجعه، لو فيه أكتر من إصدار.','price-lists')
frule(L,'اسم الخدمة في المركز','اسم التحليل زي ما هيظهر في خدمات المركز والحجز.','price-lists')
frule(L,'سعر البيع في المركز (جنيه)','السعر اللي المريض هيدفعه في المركز. قارنه بتكلفة المعمل علشان ماتبيعش بأقل من التكلفة.','price-lists')
frule(L,'إتاحة الخدمة في الحجز بعد الاعتماد','علّم عليها علشان الخدمة تظهر في الحجز أول ما مراجع تاني يعتمد الطلب.','price-lists')
frule(L,'سبب الإضافة','اشرح ليه التحليل محتاج خدمة جديدة ومش موجود له مقابل في المركز. الطلب بيروح لمراجع تاني.','price-lists')
frule(L,'ابحث باسم الخدمة','اكتب جزء من اسم الخدمة علشان تختار خدمة المركز المطابقة للتحليل.','price-lists')
frule(L,'سبب هذا الاختيار','اكتب ليه الخدمة دي هي نفس التحليل، زي نفس العينة ونفس الاسم العلمي. القرار بيتسجل باسمك.','price-lists')
frule(L,'التكلفة (جنيه)','سعر التحليل اللي المعمل الشريك بياخده من المركز.','price-lists')
frule(L,'مصدر الرقم','منين جبت التكلفة، زي قائمة أسعار المعمل أو خطاب منه.','price-lists')
frule(L,'راجعت الصفحة وأتحمل مسؤولية التأكيد باسمي','علّم عليها بس بعد ما تراجع كل الربطات الظاهرة في الصفحة. كل ربط هيتسجل باسمك.','price-lists')
X='patient360.js'
frule(X,'اكتب المعلومة، ولا تفترض سببًا غير مؤكد.','اكتب المعلومة اللي عرفتها عن المريض أو العميل زي ما قالها، من غير ما تستنتج سبب مش مؤكد.','leads-guide')
frule(X,'اكتب الشكوى والمطلوب مراجعته دون استنتاج مسؤولية أو تشخيص.','اكتب الشكوى زي ما وصلت والمطلوب مراجعته، من غير ما تحدد مين الغلطان أو تكتب تشخيص.','leads-guide')
frule(X,'سبب المتابعة','اكتب ليه محتاجين نتابع مع المريض، زي سؤال عن نتيجة أو موعد ماتحجزش.','leads-guide')
frule(X,'مسودة رسالة بدون ضغط على العميل','اكتب نص رسالة المتابعة بأسلوب لطيف من غير ضغط. دي مسودة بس ومش بتتبعت تلقائي.','leads-guide')
frule(X,'موعد مقترح','ميعاد مقترح للمتابعة. الحفظ بيسجل مسودة بس.','leads-guide')
frule('reception-patient-documents.js','نوع المستند','اختار نوع المستند اللي بترفعه للمريض، زي بطاقة أو كارنيه أو نتيجة.','reception-patient-documents')
O='reception-service-orders.js'
frule(O,'الطلب','اختار طلب الخدمة اللي بتسجل تنفيذه أو مكانه.','today-board')
frule(O,'جهة التأمين / التعاقد','اسم شركة التأمين أو الجهة المتعاقدة زي ما هيتطبع على فاتورة المطالبة.','insurance')
frule(O,'رقم الموافقة','رقم موافقة الجهة على الخدمة (لو فيه) — بيتطبع على فاتورة المطالبة، وارفق صورة الموافقة معاها.','insurance')
frule(O,'رقم العضوية','رقم كارنيه المريض عند جهة التأمين.','insurance')
frule(O,'نسبة تحمّل المريض %','النسبة اللي المريض بيدفعها من قيمة الخدمات حسب شروط الجهة.','insurance')
frule(O,'أو تخصص','اختار تخصص بدل طبيب معين لو أي طبيب في التخصص ده ينفع ينفذ الخدمة. لازم تختار واحد بس: طبيب أو تخصص.','today-board')
frule(O,'تسري من','اليوم اللي النسبة الجديدة تبدأ منه.','today-board')
frule(O,'نسبة المزوّد % (أشعة خارجية يحاسبها المركز)','النسبة اللي المزود بياخدها لما المركز هو اللي بيحاسب المريض على أشعة بتتعمل عند المزود.','today-board')
frule(O,'نسبة المركز % (أشعة يحاسبها المزوّد)','النسبة اللي المركز بياخدها لما المزود هو اللي بيحاسب المريض مباشرة.','today-board')
frule(O,'السنة','السنة اللي سعر تكلفة المعمل ده بيتطبق فيها.','today-board')
TAB='today-auto-bookings.js'
frule(TAB,'مثلاً: هيكلمنا الأسبوع الجاي','ملاحظة اختيارية مع سبب الإلغاء، تظهر في سجل الحجز. الإلغاء بيتسجل في الداشبورد بس — الغي الحجز على مسا كمان.','today-board')
frule(TAB,'الموبايل','رقم موبايل المريض الصحيح (11 رقم يبدأ بـ 01). التعديل بيظهر في «حجوزات آلية» وبيتستخدم في البحث عن ملف المريض وقت تسجيل الوصول، ومش بيغيّر الحجز على مسا.','today-board')
frule(O,'سعر التكلفة','المبلغ اللي المركز بيدفعه للمعمل الخارجي عن الخدمة. المريض بيدفع حسب أسعار المركز.','today-board')
V='reception-services.js'
frule(V,'سبب تغيير المواعيد','اكتب ليه تواريخ أقساط الباكج بتتغير، زي طلب المريضة أو تأجيل زيارة.','package')
frule(V,'المدة بالأيام (اختياري)|المدة بالأيام','عدد الأيام اللي الباكج بيخلص فيها، لو متفق عليها.','package')
frule(V,'احتساب مقدم ٢٥٪ والأقساط على عدد زيارات الباكج','علّم عليها علشان النظام يحسب مقدم 25٪ ويوزع الباقي أقساط على الزيارات.','package')
frule(V,'تاريخ المقدم المتفق عليه','اليوم اللي المريض هيدفع فيه المقدم.','package')
frule(V,'السعر المتفق عليه','السعر النهائي اللي اتفقت عليه مع المريض للباكج.','package')
frule(V,'الاستحقاق','القسط بيستحق عند الزيارة، ولا في تواريخ ثابتة. الأقساط تذكير لحد ما استحقاقها يتعتمد.','package')
frule(V,'الخدمة الجديدة','خدمة الليزر اللي الزيارة دي هتتحسب عليها بدل القديمة.','package')
frule(V,'الكمية المتفق عليها','عدد الوحدات المتفق عليها للزيارة دي، زي عدد المناطق.','package')
frule(V,'سبب التعديل','اكتب ليه اتفاق الباكج أو الزيارة اتغير. التعديل بيتسجل ويتراجع.','package')
R='reception-workspace.js'
frule(R+'|today-operations.js','اسم المريض أو رقم الملف أو التليفون أو الدكتور','اكتب جزء من اسم المريض أو رقم ملفه أو تليفونه أو اسم الدكتور علشان تلاقي الحجز.','booking-flow')
frule(R+'|today-operations.js','الأطباء','اعرض حجوزات طبيب معين بس، أو كل الأطباء.','booking-flow')
frule(R,'القسم / التخصص','اعرض قسم أو تخصص معين بس.','booking-flow')
frule(R,'اكتب حرفين من اسم الخدمة أو كود سونو','اكتب حرفين على الأقل من اسم الخدمة أو كود سونو واختارها من النتايج. في «تأمين / تعاقد» اختار الجهة الأول، وبعدها دوّر باسم سونو أو اسم الجهة أو كودها.','reception-entity-service-names')
frule(R,'خدمة خارجية (مبلغ إضافي يُضاف على فاتورة المريض)','علّم عليها لو الخدمة ليها مبلغ إضافي المريض بيدفعه فوق سعرها. المبلغ ده مش من أتعاب الطبيب.','booking-flow')
frule(R,'المبلغ الإضافي (جنيه)','المبلغ اللي بيتضاف على فاتورة المريض فوق سعر الخدمة.','booking-flow')
frule(R,'فترة تانية من','لو الطبيب عنده فترتين في نفس اليوم، اكتب بداية ونهاية الفترة التانية.','weekly-schedule')
frule(R,'من يوم|لحد يوم (شامل)','أول وآخر يوم للتغيير المؤقت في مواعيد الطبيب، والاتنين داخلين. الحجوزات القديمة مش بتتلغي لوحدها، وهيظهرلك اللي محتاج تكلمه.','schedule-exception')
frule(R,'نوع التغيير','الطبيب مش موجود (إجازة أو سفر)، ولا موجود بساعات مختلفة.','schedule-exception')
T='test-records.js'
frule(T,'نوع السجل','اختار نوع السجل التجريبي اللي بتدور عليه: فاتورة، عقد دكتور، دكتور كامل، صنف مخزون، مستلزم تسعير، مقدم حجز، أو خزينة.','test-records')
frule(T,'بحث (اسم / رقم / مرجع)','اكتب اسم أو رقم أو مرجع السجل علشان تلاقيه.','test-records')
frule(T,'مثال: فاتورة تجربة عملها المحاسب|سبب اعتباره تجريبيًا','اكتب ليه السجل ده تجريبي، زي فاتورة تجربة عملها المحاسب.','test-records')
frule(T,'اكتب كلمة «تجريبي» للتأكيد','اكتب كلمة «تجريبي» بالظبط علشان تأكد إنك عايز تعلّم السجل.','test-records')
frule(T,'سبب الحذف','اكتب ليه السجل التجريبي هيتحذف.','test-records')
frule(T,'اكتب كلمة «حذف» للتأكيد (مفيش رجوع من الشاشة؛ النسخة محفوظة في الأرشيف)','اكتب كلمة «حذف» بالظبط للتأكيد. مفيش رجوع من الشاشة، بس نسخة بتتحفظ في الأرشيف.','test-records')
S='today-operations-sandbox.js'
frule(S,'مريض التجربة|الخدمة التجريبية|طبيب التجربة','بيانات تجريبية للتدريب على الحجز. محفوظة جوه مساحة التجربة بس ومابتأثرش على المرضى أو الحسابات الحقيقية.','today-board')
frule(S,'التقييم من 1 إلى 5','تقييم تجربة الزيارة من 1 لـ5 في مساحة التجربة.','today-board')
frule(S,'تعليق اختياري','تعليق على تجربة الزيارة لو حابب.','today-board')
frule('today-operations-v2.js|today-operations-service-request-v3.js','الخدمة المطلوبة','اختار الخدمة اللي المريض محتاجها. النظام بيصنفها لوحده تحاليل أو أشعة أو علاج طبيعي، والمنفذ بيتحدد وقت التنفيذ.','today-board')
Q='today-operations-v2.js'
frule(Q,'مستوى الأولوية','اختار سبب تقديم المريض. الحالات العاجلة والحرجة بتتقدم بقرار التمريض.','today-board')
frule(Q,'سبب الأولوية','اكتب السبب التشغيلي للأولوية. إجباري لأي مستوى غير العادي.','today-board')
frule(Q,'اليوم الجديد|الساعة المتاحة','اختار اليوم الجديد، وبعدها هتظهر الساعات الفاضية للطبيب في اليوم ده.','today-board')
frule(Q,'ملاحظة اختيارية','ملاحظة عن إنهاء الزيارة لو حابب.','today-board')
Y='today-operations.js'
frule(Y,'يوم التشغيل','اليوم اللي عايز تشوف حجوزاته ورحلة مرضاه.','today-board')
frule(Y,'ابحث بالاسم أو التليفون أو رقم الملف','اكتب اسم المريض أو تليفونه أو رقم ملفه علشان تلاقيه في قائمة اليوم.','today-board')
frule(Y,'خط العرض|خط الطول','إحداثيات المركز على الخريطة. بتستخدم للتأكد إن المريض جوه المركز وقت تسجيل الوصول. ممكن تضغط «استخدم موقعي» وانت في المركز.','today-board')
frule(Y,'نطاق السماح بالمتر','المسافة المسموحة من المركز بالمتر علشان تسجيل الوصول يتقبل.','today-board')
frule(Y,'التحقق من الموقع','«مطلوب» معناها المريض لازم يكون جوه النطاق علشان يسجل وصوله.','today-board')
frule(Y,'QR تسجيل الوصول','تشغيل أو إيقاف تسجيل وصول المريض بكود QR.','today-board')
frule(Y,'طلب التقييم بعد الزيارة','تشغيل أو إيقاف طلب تقييم من المريض بعد ما الزيارة تخلص.','today-board')
frule(Y,'حد تنبيه الانتظار بالدقائق','لو المريض استنى أكتر من الدقايق دي، بيظهر تنبيه في لوحة اليوم.','today-board')
frule(Y,'حد تأخير الطبيب بالدقائق','لو الطبيب اتأخر أكتر من الدقايق دي عن أول ميعاد، بيظهر تنبيه.','today-board')
frule(Y,'التأخير المتوقع بالدقائق','الوقت المتوقع لتأخير الطبيب. بيظهر للاستقبال علشان يبلغوا المرضى.','today-board')
frule(Y,'درجة الأولوية','من عادية لأولوية 5. اكتب السبب لأي أولوية.','today-board')
# --- Digital team, assistants, content, leads, publishing and misc ---
MSG_KIND='اختار نوع رسالتك للوكيل: رسالة عادية أو سؤال أو تعليمات أو تكليف بمهمة. النوع بيحدد الوكيل هيتعامل معاها إزاي، والرد استشاري ومابينفذش حاجة في الحجز أو الحسابات لوحده.'
CHAT_SEARCH='اكتب اسم أو رقم أو كلمة علشان تلاقي محادثة أو ملاحظة. البحث مابيبعتش حاجة.'
DT='digital-team.js|digital-team-chat.js|digital-team-communications.js|digital-team-server-chat.js'
frule(DT,'نوع الرسالة',MSG_KIND,'digital-team')
frule('administrative-assistant.js','مثال: موافق · موافق على صلاحية الحسابات لمحمود','اكتب قرارك على الطلب بكلام بسيط، زي «موافق» أو «موافق على صلاحية الحسابات». ده للمالك بس.','digital-team')
frule('administrative-assistant.js','مثال: لو كشف المرتبات طبيعي ومطابق للحضور اعتمده، ولو فيه فرق استناني.','علّم المساعد قاعدة يمشي عليها بعد كده، زي امتى يعتمد وامتى يستناك. القاعدة بتتحفظ ويتقدر تمسحها.','digital-team')
frule('design-inputs.js','Claude يصمم المادة دي على طول (بوست أو كاروسيل)','علّم عليها علشان المادة تروح لـ Claude يصممها أول ما تبعتها، والتصميم يظهر في الاعتماد النهائي.','design-guide')
frule('design-inputs.js|render-review.js','نوع التصميم','عادي بالقوالب المعتمدة، أو عرض وحملة، أو تصميم حر بمثال. النوع بيحدد القالب اللي هيتصمم بيه.','design-guide')
frule('render-review.js','نوع المادة','اعرض نوع مواد معين بس: فيديو وريل، أو بوست، أو كاروسيل، أو بوست رابط. الفلتر للعرض بس.','content')
frule('digital-team-chat.js','احفظها في تعليمات الوكلاء','علّم عليها لو الرسالة تعليمات دايمة الوكلاء يفتكروها في كل مرة.','digital-team')
frule('digital-team-chat.js','متابعة دورية','علّم عليها علشان الوكيل يتابع الموضوع ده بشكل دوري (يومي أو أسبوعي). المتابعة تحليلية بس.','digital-team')
frule('digital-team-chat.js','موعد المتابعة بتوقيت الإمارات','الساعة اللي المتابعة الدورية بتشتغل فيها، بتوقيت الإمارات.','digital-team')
frule('digital-team-chat.js|digital-team-server-chat.js','اكتب رسالتك هنا...|اكتب رسالتك… (@ لاختيار وكيل)','اكتب رسالتك للوكيل. اكتب @ علشان تختار وكيل معين. ماتكتبش بيانات مرضى أو كلمات سر.','digital-team')
frule('digital-team-communications.js','المرسل إليه','الوكيل اللي هتبعتله، أو الفريق كله.','digital-team')
frule('digital-team-communications.js','مثال: يا حور راجع تأخر بداية الكشف وحلل الأسباب واقترح الحلول، واطلب رأي حتب في أثر الانتظار على المرضى.|الرسالة أو وصف المهمة','اكتب المطلوب بوضوح: إيه اللي يتراجع، وإيه النتيجة اللي عايزها، ومين يتشارك. الرد استشاري ومابينفذش حاجة لوحده.','digital-team')
frule('digital-team-communications.js','فلترة حسب الوكيل|فلترة حسب نوع الرسالة','اعرض رسايل وكيل معين أو نوع معين بس. الفلتر للعرض بس.','digital-team')
S='digital-team-server-chat.js'
frule(S,'مثال: سارة من التسويق|مين المسؤول أو أي مشروع؟ (اختياري)','اكتب مين المسؤول عن المهمة أو المشروع اللي تخصه، لو تعرف.','digital-team')
frule(S+'|patient360.js','بحث في المحادثات|ابحث في المحادثات',CHAT_SEARCH,'digital-team')
frule(S,'الوكيل المطلوب','اختار الوكيل اللي عايز يرد على رسالتك.','digital-team')
frule(S,'سؤالك|اكتب سؤالك عن الداشبورد…','اكتب سؤالك عن استخدام الداشبورد. المساعد بيقرا بس ومابيغيرش أي بيانات.','digital-team')
frule(S,'اسم المحادثة','اسم يميز المحادثة الجديدة، زي موضوعها.','digital-team')
frule(S,'البحث عن مستخدم|ابحث عن مستخدم','اكتب اسم الزميل علشان تضيفه للمحادثة.','digital-team')
frule(S,'إتاحة السجل السابق للمشاركين الجدد','علّم عليها علشان المشاركين الجداد يشوفوا الرسايل القديمة. من غيرها بيشوفوا من الرسالة الجاية بس.','digital-team')
frule(S,'المحادثة','اختار المحادثة اللي عايز تصدرها، أو كل محادثاتك.','digital-team')
frule(S,'الصيغة','صيغة ملف التصدير: CSV يتفتح في Excel، أو نص عادي.','digital-team')
frule(S,'السماح للموظفين بسؤال سونو الذكي (Codex، قراءة فقط)','تشغيل أو إيقاف إمكانية إن الموظفين يسألوا المساعد الذكي. المساعد بيقرا بس، وفيه حد يومي لكل موظف.','digital-team')
frule('digital-team.js','اكتب المطلوب أو سؤالك بالتفصيل...','اكتب سؤالك أو تعليماتك للوكيل بالتفصيل. الرد استشاري.','digital-team')
frule('digital-team.js','اختر مهمة بها مرفق','اختار مهمة فيها ملف علشان الوكيل يراجعه. المراجعة قراءة بس ومابتغيرش حالة المهمة.','digital-team')
frule('employee-assistant.js','اكتب اللي مش عارف تعمله…','اكتب اللي مش عارف تعمله في الداشبورد. الرد بيعتمد على الشاشة اللي انت فيها وصلاحياتك ودليل التشغيل.','digital-team')
frule('employee-performance.js','فترة المتابعة','الفترة اللي مؤشر الأداء بيتحسب عليها، زي الشهر ده أو آخر 3 شهور.','indicators')
M='leads-missing-data-enhancement.js'
frule(M,'فلتر البيانات الناقصة','اعرض العملاء الناقصين بيان معين، زي الاسم أو التليفون أو الخدمة.','leads-guide')
frule(M,'بحث بالاسم أو رقم التليفون','اكتب جزء من اسم العميل أو رقمه.','leads-guide')
frule(M,'الاسم الثلاثي على الأقل','اكتب اسم العميل ثلاثي زي ما قاله، علشان يتطابق مع ملفه بعدين.','leads-guide')
frule(M,'الخدمة المهتم بها','الخدمة اللي العميل سأل عنها أو مهتم بيها.','leads-guide')
frule('render-metaads.js','الصق التوكن هنا','الصق توكن Meta اللي بصلاحية قراءة الإعلانات بس. بيتحفظ على السيرفر ومابيظهرش تاني لحد.','ads-guide')
frule('render-org-legal.js','اربطه بحساب البنك في الحسابات (اختياري)','اختار حساب البنك المقابل في شجرة الحسابات، علشان بيانات البنك هنا تتطابق مع الدفاتر.','org-legal')
frule('render-reports.js','الدكتور','فلتر بيقصر تقرير الإيرادات على دكتور واحد. «كل الدكاترة» بيعرض الكل. الفلتر للعرض بس ومبيغيّرش أي بيانات.','reports-center')
frule('render-reports.js','الدفع','فلتر بيفرّق بين الإيراد الكاش وإيراد التأمين في تقرير الإيرادات. «الكل» بيعرضهم مع بعض. للعرض بس.','reports-center')
frule('render-reports.js','الشهر','الشهر اللي التارجت بيتحط له (في لوحة التحكم) أو بيتعرض له (في تقرير التارجت). التارجت بيبقى لشهر كامل.','reports-center')
frule('render-reports.js','المؤشر','المؤشر اللي بيتقاس عليه التارجت: إيراد الفرع، الزيارات، الليدز الجديدة، تكلفة الليد، الحجوزات، محاولات التواصل، الليدز اللي اتحولت لحجز، أو متوسط أول رد. الفعلي بيتحسب لوحده من السيستم.','reports-center')
frule('render-reports.js','صاحبه','مين التارجت ده عليه: الفرع كله، أو دور كامل (مدير، سوشيال ميديا، كول سنتر، استقبال)، أو شخص بالاسم. التارجت بيستنى موافقة المالك قبل ما يتحسب.','reports-center')
frule('render-reports.js','التارجت','الرقم المطلوب للشهر. في المؤشرات اللي الأقل فيها أحسن (تكلفة الليد ووقت الرد) التحقيق بيتحسب بالعكس.','reports-center')
frule('render-reports.js','كود الحملة','كود الحملة الإعلانية زي PHY1 أو LZF1-F، بيظهر لما تختار مؤشر «تكلفة الحجز للحملة». التارجت هنا ثابت للحملة لحد ما يتغيّر، مش لشهر واحد.','reports-center')
frule('render-reports.js','PHY1','مثال لكود حملة إعلانية (علاج طبيعي). اكتب كود الحملة زي ما هو في خطة الإعلانات.','reports-center')
frule('render-org-legal.js','الملف (PDF أو صورة — لحد 15 ميجا)','اختار صورة المستند أو PDF لحد 15 ميجا. بيتحفظ في مكان خاص وبيتفتح بلينك مؤقت.','org-legal')
frule('render-performance.js','نطاق العرض','اعرض كل البوستات، أو آخر عدد معين، أو فترة من تاريخ لتاريخ.','indicators')
frule('render-performance.js','عدد البوستات','عدد آخر البوستات اللي عايز تشوف أداءها.','indicators')
P='render-publish.js'
frule(P,'خصوصية فيديو TikTok','مين يقدر يشوف الفيديو على TikTok. لازم تختار بنفسك قبل النشر.','publishing-guide')
frule(P,'عنوان فيديو يوتيوب (لحد ١٠٠ حرف)','عنوان الفيديو على يوتيوب، 100 حرف بالكتير.','publishing-guide')
frule(P,'الظهور على يوتيوب','عام يظهر للكل، أو بالرابط بس (Unlisted) يشوفه اللي معاه الرابط.','publishing-guide')
frule(P,'Client ID|Client Secret','بيانات تطبيق Google اللي بيربط قناة يوتيوب. بتتحفظ على السيرفر، وماتبعتهاش لحد في رسالة.','publishing-guide')
frule('render-tasks.js','سبب الاعتماد المباشر','الموظف ماسلمش المهمة رسمي. اكتب ليه بتقفلها، زي إن الشغل اتسلم في التعليقات.','tasks-guide')
frule('render-tasks.js','سبب الإلغاء','اكتب ليه المهمة اتلغت. الملغاة مابتتحسبش متأخرة ومابيجيش عنها تنبيهات.','tasks-guide')
frule('render-tasks.js','شخص تاني','اختار زميل معين يوصله التعليق غير المسؤول ومدير المشروع.','tasks-guide')
frule('finance-masa-payments.js','الطريقة','اختار طريقة الدفع اللي عايز تشوف إيصالاتها: نقدي، أو فيزا، أو المحافظ (انستا باي وفودافون كاش). «الكل» بيعرض كل الطرق.','masa-payments')
frule('reception-auto-book.js','ساعة تانية','لو الميعاد اللي جه من ماسا أو الواتساب مقدرش يتسجّل (متاخد أو برّه مواعيد الدكتور)، اختار ساعة تانية في نفس اليوم واضغط «سجّل في الساعة دي». اتفق مع المريض على الساعة الأول.','automatic-bookings')
frule('reception-doctor-payout.js','رفع الإيصال الممضي (اختياري)','ارفع صورة أو PDF لإيصال استلام النقدية بعد ما الدكتور يمضي عليه (لحد 10 ميجا). اختياري ويتعمل بعدين؛ الصرف نفسه اتسجل خلاص.','doctor-payout-desk')
frule('reception-doctor-payout.js','ملاحظة / سبب التعديل أو الرفض','للي بيعتمد بس: اكتب سبب تغيير المبلغ أو سبب الرفض (3 حروف على الأقل). الاعتماد بالمبلغ زي ما هو مش محتاج ملاحظة.','doctor-payout-approve')
frule('hr-overtime.js','المدة بالدقايق','عدد الدقايق اللي محتاج تقعدها بعد نهاية شيفتك (من 5 لـ 720). المحسوب في الآخر مايزيدش عن المعتمد ولا عن آخر ميعاد دكتور في اليوم.','hr-overtime')
frule('hr-overtime.js','ليه محتاج تقعد بعد الشيفت؟','اكتب السبب بوضوح (مهمة، جرد، استلام شحنة…). السبب بيظهر لمديرك والموارد البشرية في تقرير الساعات الإضافية.','hr-overtime')
frule('hr-overtime.js','الوقت المتوقع للمهمة (دقايق)','للي بيوافق: الوقت اللي المهمة المفروض تاخده. المعتمد مايعديش المتوقع + نسبة السماح (20٪) إلا لو كتبت سبب الزيادة.','hr-overtime')
frule('hr-overtime.js','الدقايق المعتمدة','للي بيوافق: الدقايق اللي هتتحسب للموظف في اليوم ده. بتبدأ بالمطلوب وتقدر تقللها.','hr-overtime')
frule('hr-overtime.js','ملاحظة / سبب الرفض','ملاحظة على الموافقة، أو سبب الرفض (لازم في حالة الرفض). بتظهر للموظف.','hr-overtime')
frule('hr-overtime.js','شهر التقرير','اختار الشهر اللي عايز تشوف تقرير ساعاته الإضافية.','hr-overtime')
frule('hr-overtime.js','سماح المهمة ٪','النسبة المسموحة فوق الوقت المتوقع للمهمة من غير سبب مكتوب (المالك حددها 20٪).','hr-overtime')
frule('hr-overtime.js','تنبيه لو قعد بدون إذن أكتر من (دقيقة)','القعدة بعد الشيفت من غير طلب متوافق عليه أكتر من الرقم ده بتتعلّم في التقرير.','hr-overtime')
frule('hr-overtime.js','عدد المرات في الشهر علشان يتعلّم للموارد البشرية','لو الموظف قعد من غير إذن العدد ده من المرات أو أكتر في الشهر بيظهر في تنبيه للموارد البشرية تقرر؛ مفيش خصم أوتوماتيك.','hr-overtime')
frule('staff-profile.js','الصورة','اختار صورتك الشخصية: JPG أو PNG أو WebP لحد 8 ميجا. بتتصغر وتظهر جنب اسمك.','personal')
# --- «النوع» on non-patient screens: replace the generic patient-file wording ---
frule('hr-custody.js|hr-insurance.js|hr-attendance-reports.js','النوع','في الموارد البشرية «النوع» بيصنّف السجل حسب الشاشة: نوع العهدة (جهاز أو مفاتيح أو بطاقة أو أدوات أو مستند)، أو نوع التأمين (اجتماعي أو طبي)، أو حالة الحضور في تقرير الحضور. في الفلاتر بيعرض نوع معين بس.','hr-manage')
frule('hr-offboarding.js','النوع','نوع البند في المخالصة: مستحق للموظف، أو مستحق عليه، أو عهدة ماتسلمتش، أو مستند أو عقد معاه.','hr-offboarding')
frule('hr-payroll-workspace.js','النوع','نوع البند: مكافأة، أو خصم، أو نسبة خدمة. في النسبة املا الخدمة والقيمة والنسبة بدل المبلغ.','hr-payroll')
frule('accountant-workspace.js','النوع','نوع الحساب في الشجرة: أصول أو خصوم أو حقوق ملكية أو إيرادات أو مصروفات. لازم يطابق نوع الحساب الأب.','ledger-guide')
frule('digital-team-server-chat.js','النوع',MSG_KIND,'digital-team')
frule('peer-handover.js','سلّم لـ','اختار زميلك اللي فاتح وردية تحصيل دلوقتي. لو مش ظاهر في القايمة يبقى لسه ما فتحش ورديته.','peer-cash-handover')
frule('peer-handover.js','جزء من التحصيل (وأكمّل ورديتي)','تسلّم مبلغ من الكاش اللي معاك وتفضل ورديتك مفتوحة. المبلغ مايعدّيش الكاش المتاح في ورديتك.','peer-cash-handover')
frule('peer-handover.js','إنهاء ورديتي وتسليم كل الكاش','بتعدّ الفلوس فئة فئة وتسلّمها كلها لزميلك، وورديتك بتقف عن التحصيل. بعد ما زميلك يأكد، ورديتك بتتقفل لوحدها، وأي فرق في العد بيروح للمراجعة من غير خصم تلقائي.','peer-cash-handover')
frule('peer-handover.js','المبلغ اللي عدّيته','عدّ الفلوس اللي زميلك سلّمهالك واكتب المبلغ. لازم يطابق المبلغ اللي هو كتبه بالظبط، ولو فيه فرق دوس «رفض» واكتب السبب.','peer-cash-handover')
frule('peer-handover.js','ملاحظة / سبب الرفض','ملاحظة اختيارية مع الاستلام. لو هترفض لازم تكتب السبب (مثلاً: المبلغ ناقص 50).','peer-cash-handover')
PX='reception-patient-extras.js'
frule('reception-overbook.js','التاريخ (بتوقيت القاهرة)','يوم الموعد الإضافي. الافتراضي النهارده.','reception-overbook')
frule('reception-overbook.js','الوقت (بتوقيت القاهرة)','وقت الموعد الإضافي، حتى لو الدكتور محجوز فيه. لازم يكون جوه مواعيد تواجد الدكتور في اليوم ده.','reception-overbook')
frule('reception-overbook.js','تفاصيل السبب (إجباري لو «سبب تاني»)','اكتب ليه الموعد اتسجل فوق الجدول. إجباري لما تختار «سبب تاني»، واختياري مع باقي الأسباب.','reception-overbook')
frule('month-end-accounts.js','شهر الحسابات','الشهر اللي عايز تشوف حساباته. المستحق والسداد والطلبات كلها للشهر ده.','month-end-accounts')
frule('month-end-accounts.js','المتفق عليه','الرقم النهائي اللي اتفقنا عليه مع المنصة: مبلغ، أو نسبة من رقمنا. لو أقل من رقمنا الفرق «خصم مراجعة».','platform-audit')
frule('month-end-accounts.js','سبب الاتفاق','ليه الرقم المتفق عليه مختلف (أو زي) رقمنا ورقمهم — بيتحفظ مع المراجعة.','platform-audit')
frule('month-end-accounts.js','مثلاً: حجزين اتلغوا ومتحسبين عندهم','اكتب سبب الاتفاق بوضوح — بيتحفظ مع المراجعة.','platform-audit')
frule('partner-accounts.js','كاش ولا بنك؟','كاش من الخزينة الرئيسية (لازم ورديتها تكون مفتوحة) أو البنك. الشريك بيتعامل مع الخزينة الرئيسية بس.','partner-accounts')
frule('partner-accounts.js','مثلاً: توريد لدفع إيجار المركز','اكتب الفلوس دي ليه — بتظهر في كشف حساب الشريك.','partner-accounts')
DR='drawer-requests.js'
frule(DR,'المورد / الصيدلية','المورد أو الصيدلية اللي هتدفعلها. لازم يكون متسجل في الموردين — المحاسب بيسجل فاتورته بأصنافها قبل الموافقة.','drawer-requests')
frule(DR,'📷 صورة فاتورة المورد (إجباري)','صوّر فاتورة المورد. من غيرها الطلب مش هيتبعت، والمحاسب بيراجع عليها.','drawer-requests')
frule(DR,'المبلغ (جنيه)','المبلغ اللي محتاج يطلع من درجك. بعد الموافقة لازم الكاش اللي في الدرج يكفيه وقت «اتصرف».','drawer-requests')
frule(DR,'مثلاً: سلفة شخصية — تتخصم من مرتب الشهر','اكتب الطلب ليه بالظبط — بيظهر للي هيوافق.','drawer-requests')
ED='employee-debt.js'
frule(ED,'الموظف (المديونية عليه)','الموظف اللي المبلغ هيتسجل عليه ويتخصم من مرتبه. بيظهر بس الموظفين الشغالين اللي المريض هو نفسه أو قريبهم من الدرجة الأولى.','employee-debt')
frule(ED,'مرة واحدة','المبلغ كله يتخصم من مرتب شهر واحد (الشهر اللي تختاره في «أول خصم من مرتب»).','employee-debt')
frule(ED,'أقساط','المبلغ يتقسم على كذا شهر بالتساوي، وكل شهر القسط بيتخصم لوحده من المرتب.','employee-debt')
frule(ED,'عدد الشهور','عدد الأقساط من 2 لـ 12 شهر. القسط = المبلغ ÷ عدد الشهور (آخر قسط بياخد كسور القروش).','employee-debt')
frule(ED,'أول خصم من مرتب','الشهر اللي هيبدأ فيه الخصم — الشهر ده أو الـ 3 شهور الجايين. الافتراضي الشهر الجاي.','employee-debt')
frule(ED,'مثلاً: كشف ابن الموظف — يتخصم من المرتب','اكتب السبب (3 حروف على الأقل) — بيظهر للمدير المالي أو المالك وقت الموافقة.','employee-debt')
frule(ED,'دوّر على الإيصال','اكتب رقم الزيارة أو اسم المريض أو المبلغ، والقايمة اللي تحت بتتفلتر على طول.','employee-debt')
frule(ED,'رقم الزيارة أو اسم المريض أو المبلغ','اكتب أي جزء من رقم الزيارة أو الاسم أو المبلغ عشان تلاقي الإيصال بسرعة.','employee-debt')
frule(ED,'دوّر في الطلبات','اكتب اسم الموظف أو رقم الزيارة أو اسم اللي طلب، والجدول بيتفلتر.','employee-debt')
frule(ED,'اسم الموظف أو رقم الزيارة أو اللي طلب','أي جزء من الاسم أو الرقم — الجدول بيبين اللي فيه الكلمة دي بس.','employee-debt')
frule(ED,'الإيصال النقدي','الإيصال النقدي اللي اتسجل بالغلط ومادخلش فلوس (آخر 14 يوم، والمريض موظف أو قريبه). بيبان معاه الزيارة والمبلغ واسم اللي حصّل وحالة الوردية.','employee-debt')
A='employee-debt-reschedule'
frule(ED,'المديونية','لو الموظف عليه أكتر من مديونية، اختار اللي عايز تغيّر أقساطها.',A)
frule(ED,'تأجيل قسط','تأخير قسط واحد لشهر بعد آخر قسط. في الشهر بتاعه مش هيتخصم حاجة من المرتب، والمبلغ الكلي زي ما هو.',A)
frule(ED,'تغيير عدد الأقساط','الباقي من المديونية يتقسم من جديد على عدد شهور تختاره (من 1 لـ 12).',A)
frule(ED,'القسط اللي هيتأجل','قسط لسه ماتخصمش ومش في مرتب متجهز. الأقساط اللي اتخصمت مابتظهرش هنا.',A)
frule(ED,'يتأجل لحد','شهر بعد آخر قسط في الجدول، لحد 6 شهور بعده.',A)
frule(ED,'عدد الأقساط الجديد (للباقي)','عدد الشهور اللي الباقي هيتقسم عليها (1 = الباقي كله مرة واحدة). آخر قسط بياخد كسور القروش.',A)
frule(ED,'من مرتب','الشهر اللي يبدأ منه الجدول الجديد — الشهر ده أو الـ 3 شهور الجايين، ومش شهر قسطه في مرتب متجهز.',A)
frule(ED,'السبب (إجباري)','اكتب سبب التغيير (3 حروف على الأقل) — بيظهر للي هيوافق وبيتسجل في السجل.',A)
frule(ED,'مثلاً: ظروف عائلية — بطلب الموظف','اكتب سبب التأجيل أو تغيير الأقساط باختصار.',A)
SX='reception-shift-expenses.js'
frule(SX,'المبلغ (جنيه)','المبلغ اللي اتصرف فعلاً من فلوس الوردية. مينفعش يزيد عن حد المصروف الواحد ولا الباقي من الهامش ولا نقدية الوردية.','shift-expenses')
frule(SX,'اشتريت من مين / المورد','اسم المحل أو الشركة اللي اتدفعلها (اختياري) — بيساعد الحسابات في المراجعة.','shift-expenses')
frule(SX,'مثلاً: ٢ كرتونة مناديل + صابون للحمام','اكتب اتصرف على إيه بالظبط.','shift-expenses')
frule(SX,'السبب / التفاصيل','اتصرف على إيه وليه (إجباري). بيظهر للحسابات جنب الإيصال.','shift-expenses')
frule(SX,'📷 صورة الفاتورة أو الإيصال (إجباري)','صوّر الفاتورة أو الإيصال بالموبايل أو ارفع صورتها. من غيرها المصروف مش هيتسجل.','shift-expenses')
frule('reception-booking-plus.js','جلسة استكمال لعلاج اتعمل قبل كده (بتحجز وقت الدكتور من غير فاتورة جديدة — الخدمة اتحاسب عليها في الجلسة الأولى)','فعّلها لما المريض جاي يكمّل علاج اتحاسب عليه قبل كده (زي حشو بياخد جلستين). هيظهر جلساته السابقة للخدمة دي في آخر ٦ شهور، تختار منها، والجلسة بتتسجل بصفر جنيه مربوطة بالأولى.','reception-booking-qty')
frule('reception-booking-plus.js','الممرض/ة','الممرض أو الممرضة اللي هينفّذ الخدمة. القايمة فيها موظفين التمريض بس، والحجز بياخد وقته/وقتها فمينفعش زيارتين متداخلين.','reception-booking-nurse')
frule('reception-booking-plus.js','وقت الطريق (رايح وجاي)','للكشف المنزلي بس: وقت الطريق للطبيب رايح وراجع (30 أو 60 أو 90 أو 120 دقيقة، الافتراضي 60). الحجز بياخد 15 دقيقة كشف + الوقت ده، فالطبيب والممرض/ة اللي معاه مش بيتحجزلهم حاجة تانية فيه.','home-consult-split')
frule('reception-booking-plus.js','عدد الخدمة','عدد مرات الخدمة في الحجز ده (مثلاً ٣ طرابيش). بيوصل للفاتورة لما المريض يحضر: السعر × العدد. من ١ لـ ٩٩.','reception-booking-qty')
frule(PX,'ملاحظة دائمة للمريض (اختياري — بتظهر في كل حجز، ومسحها بعد كده بيحتاج اعتماد المدير)|مثلاً: بيحب المواعيد بعد العصر · عليه باقي حساب معمل','ملاحظة بتفضل على ملف المريض وتظهر في كل حجز ليه، زي مواعيد بيفضلها أو باقي حساب. بتتكتب لو مفيش ملاحظة، وتعديلها أو مسحها بعد كده بطلب يعتمده مدير الاستقبال.','home-visit-notes')
frule(PX,'الملاحظة الحالية','الملاحظة الدائمة المكتوبة دلوقتي على ملف المريض — للعرض بس.','home-visit-notes')
frule(PX,'الملاحظة الجديدة (سيبها فاضية لو عايز تمسحها)','النص اللي عايزه بدل الملاحظة الحالية. لو سبتها فاضية يبقى طلب مسح. مش بتتغيّر غير لما المدير يعتمد.','home-visit-notes')
frule(PX,'مثلاً: الحساب اتدفع','اكتب سبب التعديل أو المسح عشان المدير يراجعه، زي «الحساب اتدفع».','home-visit-notes')
frule('reception-workspace.js','خدمة إضافية','خدمة زيادة في نفس الحجز. لو سبت الطبيب «نفس الطبيب» بتتحجز ورا الخدمة اللي قبلها على طول (بعد الـ٥ دقايق). كل خدمة بتتسجل حجز لوحدها بسعرها.','reception-booking-extras')
frule('reception-workspace.js','الوقت','وقت الخدمة الإضافية مع الطبيب التاني. القايمة فيها أوقاته الفاضية بعد الخدمة اللي قبلها، أو اختار «وقت تاني» واكتبه بإيدك.','reception-booking-extras')
frule('reception-workspace.js','الوقت اللي تختاره (بتوقيت القاهرة)','اكتب أي وقت بإيدك (مثلاً 8:47). السيستم بيرفض لو الوقت خارج مواعيد الدكتور أو متعارض مع حجز تاني أو داخل الـ٥ دقايق اللي بين الحجوزات.','reception-booking-extras')
frule('today-operations-queue.js','اسم الغرفة','اسم الغرفة زي ما الموظفين هيشوفوه في الطابور والنداء، مثلاً «عيادة ١» أو «غرفة الأشعة».','queue-tickets')
frule('today-operations-queue.js','حرف الترقيم (اختياري: L أو R)','حرف واحد قبل رقم الدور في غرف الأقسام: L لسحب العينات و R للأشعة. اتركه فاضي للعيادات لأن أرقام الدكاترة أرقام عادية.','queue-tickets')
frule('nursing-day-ops.js','ملاحظات التمريض','ملاحظة حرة من التمريض للدكتور عن حالة المريض النهارده (مثلاً دواء أخده الصبح أو شكوى جانبية). بتظهر في شريط الفحص قبل الكشف.','nursing-triage')
frule('nursing-day-ops.js','لو أخرى، اكتب هنا','لو المرض المزمن مش من الأزرار (سكر، ضغط، قلب، ربو، غدة) اكتب اسمه هنا. الدكتور هو اللي يقرر لاحقًا يضيفه للملف الطبي أو لا.','nursing-triage')
frule('nursing-day-ops.js','حساسية','اكتب أي حساسية يقولها المريض (دواء أو أكل أو مادة). بتظهر للدكتور بلون أحمر. سيبها فاضية لو مفيش.','nursing-triage')
frule('nursing-day-ops.js','الشكوى الرئيسية','اكتب بكلام المريض سبب الزيارة النهارده. بتظهر للدكتور بين علامتي تنصيص في شريط الفحص قبل الكشف.','nursing-triage')
frule('clinical-drafts.js','مكان العلاج','اكتب مكان الجسم اللي اتعالج في الجلسة (مثلاً الركبة اليمين أو أسفل الضهر). بيظهر للدكتور في المراجعة.','clinical-drafts')
frule('clinical-drafts.js','المدة (بالدقائق)','اكتب مدة الجلسة بالدقايق، رقم بس. بتتسجل مع المسودة وبتدخل التقرير بعد اعتماد الدكتور.','clinical-drafts')
frule('clinical-drafts.js','ملاحظات الجلسة','اكتب اللي حصل في الجلسة بكلامك. ده مسودة بس ومش بيدخل الملف الرسمي لحد ما الدكتور يعتمد.','clinical-drafts')
frule('clinical-drafts.js','36 — سفلي أيمن|السن','اكتب رقم السن ومكانه، مثلاً «36 — سفلي أيمن». الدكتور بيراجعه قبل الاعتماد.','clinical-drafts')
frule('clinical-drafts.js','الإجراء','اختار الإجراء اللي اتعمل من القايمة (أسنان كبار أو أسنان أطفال). اختيار إجراء أطفال بيفعّل «أسنان أطفال» لوحده، واختيار «أشعة مطلوبة» بيفعّل خانة الأشعة.','clinical-drafts')
frule('clinical-drafts.js','مثال: MTA — بتختلف من حالة لحالة|الماتريال / الخامة','اكتب الخامة المستخدمة في الإجراء (زي MTA). بتظهر مع حشو العصب والتاج والكراون وحشو عصب الأطفال، وبتختلف من حالة لحالة.','clinical-drafts')
frule('clinical-drafts.js','اكتب مكان السن|مكان السن المخلوع','بتظهر مع «حافظ مسافات» بس: اكتب مكان السن اللي اتخلع واتحط مكانه الحافظ.','clinical-drafts')
frule('render-patients.js','صاحب الرقم','الرقم ده بتاع مين: المريض نفسه ولا الزوج/الزوجة/الأم/الأب ولا حد تاني. لازم تختاره لما الرقم يكون متسجّل على ملف تاني — بيظهر جنب الرقم في الملف («رقم الأم»).','patient')
frule('render-patients.js','مثلاً: الأخ، الجدة','لما تختار «أخرى» في صاحب الرقم: اكتب صلته بالمريض (مثلاً: الأخ، الجدة).','patient')
frule('reception-auto-book.js','مثلاً: الأخ، الجدة','لما تختار «أخرى» في صاحب الرقم للملف الجديد: اكتب صلته بالمريض.','automatic-bookings')
frule('reception-auto-book.js','وقت تاني في نفس اليوم','لو الساعة اللي عايزها مش في الأوقات الفاضية: اكتبها هنا (بتوقيت القاهرة، في نفس يوم الحجز) واضغط «سجّل في الوقت ده» أو «حجز إضافي فوق الجدول» أو «ميعاد يدوي». لو اخترت وقت من الأزرار سيب الخانة دي فاضية.','automatic-bookings')
frule('reception-follow-ups.js','من مواعيد النهارده (اختياري)','اختار زيارة من مواعيد النهارده عشان المريض والدكتور يتملوا لوحدهم — أو سيبها واختارهم بنفسك.','follow-ups')
frule('reception-follow-ups.js','ملاحظة للمتابعة (اختياري)','اللي محتاج يتعمل في المتابعة (مثلاً: إعادة تحليل قبل الكشف). بتظهر للريسبشن في قايمة المتابعات وفي الحجز.','follow-ups')
frule('reception-follow-ups.js','مثلاً: إعادة تحليل سكر تراكمي قبل الكشف','اكتب سبب المتابعة أو المطلوب قبلها.','follow-ups')
frule('reception-workspace.js','المناطق (اختياري)','لما المريض يعمل أكتر من منطقة في نفس الزيارة: اكتب المناطق (مثلاً: الوش + الإبط). بتتسجّل مع الطلب.','reception-booking-qty')
frule('reception-workspace.js','مثلاً: الوش + الإبط','اكتب المناطق اللي هتتعمل في الزيارة دي.','reception-booking-qty')
frule('clinical-drafts.js','الخطة','اكتب خطة العلاج للزيارة الجاية. بتتضاف لخطة العلاج في الملف بعد اعتماد الدكتور.','clinical-drafts')
frule('clinical-drafts.js','اكتب اللي محتاج يتعدّل|سبب الرجوع للتعديل (إجباري لو هترجّعه)','السبب إجباري لو هترجّع المسودة. بيوصل للممرضة أو المساعدة في شريط أحمر وفي تنبيه، وبيتسجل في سجل المراجعة.','clinical-drafts')
frule('reception-booking-discount.js','خصم على الحجز ده (اختياري)|خصم (نقابة / نادي / فيزيتا / كارت العيلة / خاص) (اختياري)','علّمها لو المريض له خصم نقابة أو نادي أو خصم خاص. لو مش متعلمة الحجز بيتعمل بسعره العادي.','reception-booking-discount')
frule('reception-payer-kind.js','طريقة الدفع','إجباري في أول الحجز: كاش، أو تأمين / تعاقد (جهة بتغطي جزء بسعر عقدها)، أو نقابات / نوادي (كاش بخصم ٣٠٪).','reception-payer-kind')
frule('reception-payer-kind.js','الجهة (العقود المتفعّلة بس)','الجهات اللي عقدها وقايمة أسعارها متفعّلين بس، وجنب كل واحدة سعر الخدمة في عقدها. لو فاضية: الحسابات تفعّل العقد الأول.','reception-payer-kind')
frule('reception-payer-kind.js','رقم الكوبون / الكارنيه','رقم كوبون أو كارنيه المريض عند الجهة — إجباري. بيتسجّل مع ربط المريض بعقد الجهة.','reception-payer-kind')
frule('reception-payer-kind.js','رقم موافقة التغطية','رقم الموافقة اللي الجهة أدتها للخدمة دي — إجباري، وبيروح على المطالبة.','reception-payer-kind')
frule('reception-payer-kind.js','نسبة تحمّل الجهة ٪','النسبة اللي الجهة بتدفعها من سعر العقد، من الموافقة والكارت الطبي للمريض (من 0 لـ 100). المريض بيدفع الباقي.','reception-payer-kind')
frule('reception-payer-kind.js','صورة الموافقة','صوّر موافقة التغطية — إجباري، والحجز مش بيتحفظ من غيرها.','reception-payer-kind')
frule('reception-payer-kind.js','النقابة / النادي|اسم النقابة / النادي|مثلاً نادي الصيد','اختار النقابة أو النادي اللي المريض جاي بكارنيهها، أو «أخرى» واكتب الاسم. الخصم ثابت ٣٠٪.','reception-payer-kind')
frule('reception-payer-kind.js','رقم كارنيه النقابة / النادي','رقم كارنيه النقابة أو النادي — إجباري.','reception-payer-kind')
frule('reception-payer-kind.js','كارنيه النقابة / النادي ساري لحد','آخر يوم الكارنيه ساري فيه — لازم يكون يوم الزيارة أو بعده.','reception-payer-kind')
frule('reception-payer-kind.js','صورة الكارنيه','صوّر كارنيه النقابة أو النادي — إجباري.','reception-payer-kind')
frule('reception-referrer.js','الطبيب المحوِّل','اختياري: لو المريض جاي محوَّل من دكتور. «من جوه المركز» تختاره من القايمة، «من بره المركز» تكتب اسمه. بيطلع في الفاتورة.','reception-referring-doctor')
frule('reception-referrer.js','اختار الطبيب','طبيب المركز اللي حوّل المريض.','reception-referring-doctor')
frule('reception-referrer.js','اسم الطبيب|د. …','اسم الطبيب اللي حوّل المريض من بره المركز — إجباري لو اخترت «من بره المركز».','reception-referring-doctor')
frule('reception-referrer.js','تخصص الطبيب المحوِّل','تخصص الطبيب اللي حوّل المريض (اختياري) — بيطلع جنب اسمه في الفاتورة.','reception-referring-doctor')
frule('reception-referrer.js','العيادة / المستشفى','عيادة أو مستشفى الطبيب المحوِّل (اختياري).','reception-referring-doctor')
frule('reception-referrer.js','تليفون الطبيب المحوِّل','رقم الطبيب المحوِّل لو معاك (اختياري) — مش بيطلع في الفاتورة.','reception-referring-doctor')
frule('service-select-search.js','ابحث باسم الخدمة أو الكود أو القسم|ابحث عن الخدمة','اكتب جزء من اسم الخدمة أو كودها أو قسمها — القايمة تحتها بتصغر للنتايج، ولو نتيجة واحدة بتتختار لوحدها.','reception-service-search')
frule('reception-booking-discount.js','اسم النقابة|مثلاً نقابة المهندسين','اسم الجهة اللي المريض جاي بخصمها (نقابة أو نادي أو جهة تانية). بيظهر على كارت الموعد والفاتورة.','reception-booking-discount')
frule('reception-booking-discount.js','رقم الكارنيه','رقم كارنيه النقابة أو النادي — إجباري.','reception-booking-discount')
frule('reception-booking-discount.js','الكارنيه ساري لحد','آخر يوم الكارنيه ساري فيه. لازم يكون يوم الزيارة أو بعده، ولو خلص قبل الحضور تسجيل الحضور بيقف.','reception-booking-discount')
frule('reception-booking-discount.js','سبب الخصم|مثلاً قريب موظف','سبب الخصم الخاص — إجباري.','reception-booking-discount')
frule('reception-vezeeta-paste.js',r'الصق رسالة فيزيتا \(SMS\) هنا|Dear Doctor …','الصق رسالة الحجز اللي فيزيتا بعتها على تليفون المركز زي ما هي — السيستم يقرأ منها الدكتور والمريض واليوم والساعة.','reception-vezeeta-paste')
frule('reception-vezeeta-paste.js','أول معاد فاضي مع الدكتور|بدون معاد — بالدور|أختار الساعة بنفسي','رسالة فيزيتا شامل مفيهاش ساعة: اختار أول معاد فاضي مع الدكتور، أو بالدور (لو الحجز النهارده)، أو اختار الساعة بنفسك.','reception-vezeeta-paste')
frule('reception-booking-discount.js',r'الموظف \(المريض نفسه أو قريبه من الدرجة الأولى\)','«خصم العاملين بالمركز»: الموظف الشغال في الموارد البشرية — المريض نفسه (نفس رقم التليفون) أو قريبه من الدرجة الأولى المربوط في «أفراد العيلة». لو مفيش، الخصم ده مش متاح للمريض.','reception-staff-discount')
frule('reception-booking-discount.js','القريب','اختار ملف القريب اللي هيتربط بالمريض في «كارت العيلة». الربط بيتعمل مرة واحدة بمستند إثبات القرابة.','reception-booking-discount')
frule('reception-booking-discount.js','عدد زيارات كارت العيلة اللي العيلة خدتها على السيستم القديم','عدد زيارات كارت العيلة اللي العيلة كلها خدتها قبل الداشبورد (رقم صحيح ٠ أو أكتر). بيتحسب في خطوة الخصم بعد اعتماد السوبر أدمن أو المدير المالي بس.','reception-family-legacy-visits')
frule('reception-booking-discount.js','مثلاً: العيلة كانت ماشية بكارت العيلة قبل الداشبورد','السبب اللي بيوضح للي هيعتمد ليه العيلة ليها زيارات قديمة.','reception-family-legacy-visits')
frule('reception-booking-discount.js','…أو ملاحظة (مثلاً: دفتر الاستقبال صفحة كام)','لو مفيش مستند ترفعه، اكتب فين الإثبات (دفتر، كشف، رقم إيصال). لازم مستند أو ملاحظة.','reception-family-legacy-visits')
frule('leads-booking-funnel.js','لحد','آخر يوم في فترة «مؤشرات الحجز من الليدز». الليدز بتتحسب بتاريخ دخولها.','leads-booking')
frule('leads-booking-funnel.js','من','أول يوم في فترة «مؤشرات الحجز من الليدز» (الافتراضي أول الشهر).','leads-booking')
frule('leads-booking-funnel.js','حسب','اختار تقسيم المؤشرات: حسب الموظف، أو المصدر (واتساب / ماسنجر / فيسبوك…)، أو الحملة. الحجز بيتحسب على مصدر الليد وقت الحجز.','leads-booking')
frule('reception-service-later.js','الخدمة تتحدد عند الحضور','علّمها لو المريض لسه ماقررش الخدمة: بنحجز وقت الدكتور بس (٣٠ دقيقة مبدئياً)، والخدمة والسعر يتحددوا في «تسجيل حضور».','reception-booking-service-later')
frule('reception-service-later.js','الخدمة (إجباري)','الحجز ده من غير خدمة — اختار الخدمة اللي المريض قررها من خدمات قسم الدكتور. الحضور مش بيتسجل غير بعد الاختيار.','reception-booking-service-later')
frule('reception-manual-time.js','حجز بميعاد يدوي (متفق عليه مع الدكتور)|حجز بميعاد يدوي (متفق عليه مع الدكتور) لو الميعاد مش في القايمة: اكتب الساعة بإيدك.','علّمها لما الميعاد مش في القايمة (مثلاً «لا توجد مواعيد متاحة»): اكتب الساعة بإيدك واختار السبب. لو برّه مواعيد الدكتور بيتضاف الوقت ده لليوم ده بس.','reception-booking-manual-time')
frule('reception-manual-time.js','ملاحظة الاتفاق (اختياري)|مثلاً: الدكتورة قالت هتيجي 7 ونص','اكتب تفاصيل الاتفاق مع الدكتور. إجبارية لو السبب «أخرى».','reception-booking-manual-time')
frule('hr-job-catalog.js','اسم الوظيفة','اكتب اسم الوظيفة زي ما هو في العقود، مثل «ممرض / ممرضة». الاسم بيظهر في الدليل وفي ملحق العقد.','job-catalog')
frule('hr-job-catalog.js','الاسم بالإنجليزي','اختياري. اكتب اسم الوظيفة بالإنجليزي لو محتاجه في مستندات رسمية.','job-catalog')
frule('hr-job-catalog.js','الخبرة المطلوبة','اكتب سنين الخبرة المطلوبة نصًا، مثل «3–5 سنوات». بتظهر في وصف الوظيفة.','job-catalog')
frule('hr-job-catalog.js','الحافز (وصف)','اكتب الحافز بكلام بسيط، مثل «بونص شهري على تحقيق التارجت». ده وصف فقط ومش بيحسب مبالغ، وبيظهر للإدارة مش للموظف.','job-catalog')
frule('hr-job-catalog.js','أقل راتب في النطاق','أقل راتب مسموح للوظيفة. بيظهر للسوبر أدمن والحسابات بس، وبيتقارن بالراتب المعتمد في عقد الموظف كتنبيه من غير ما يمنع الحفظ.','job-catalog')
frule('hr-job-catalog.js','أعلى راتب في النطاق','أعلى راتب مسموح للوظيفة. لازم يكون أكبر من أو يساوي أقل راتب. بيظهر للسوبر أدمن والحسابات بس.','job-catalog')
frule('hr-job-catalog.js','الراتب المعتمد (لو متحدد)','لو الإدارة حددت رقم معتمد للوظيفة اكتبه هنا. اتركه فاضي لو لسه النطاق هو المرجع.','job-catalog')
frule('hr-job-catalog.js','ملاحظة على الراتب','ملاحظة قصيرة على الراتب، مثل «أساسي + عمولة». بتظهر للسوبر أدمن والحسابات بس.','job-catalog')
frule('hr-job-catalog.js','الوظيفة (منفصلة عن دور الدخول)','اختار وظيفة الموظف من دليل الوظائف. دي لا بتغيّر دوره ولا صلاحياته في الداشبورد. الأطباء برّه الدليل.','job-catalog')
frule('render-comments.js','دوّر باسم أو كلمة','اكتب اسم الشخص أو كلمة من الرسالة أو التعليق، والقايمة بتفلتر وانت بتكتب.','social-chat-inbox')
frule('render-comments.js','نص القالب (بالعربي، من غير متغيرات)','المالك بس: اكتب نص قالب واتساب بالعربي من غير متغيرات {{ }} ومن غير بيانات مريض أو أرقام تليفون أو أرقام ملفات (الحد 1024 حرف). بعد «تقديم لميتا» الوكيل بيقدّمه وميتا بتراجعه، وبعد الموافقة بيظهر في اختيار القوالب بعد 24 ساعة.','social-chat-inbox')
frule('render-leads.js','رسالة افتتاحية جاهزة','نص جاهز تبدأ بيه المحادثة مع الليد: اختار ليزر أو علاج طبيعي، عدّل النص براحتك، وبعدين «انسخ الرسالة» أو «افتح واتساب بالرسالة». مفيش حاجة بتتبعت من الداشبورد — إنت اللي بتدوس إرسال.','leads-guide')
def norm(v):
 v=re.sub(r'[\u064b-\u065f\u0670\u0640]','',v).lower();v=re.sub('[أإآٱ]','ا',v).replace('ى','ي').replace('ة','ه');v=re.sub(r'[^\w]+',' ',v).strip();return re.sub(r'(^| )ال',r'\1',v)
def canon(v):
 v=re.sub(r'\s*\([^)]*(?:اختياري|إن وجد|ان وجد)[^)]*\)','',v);v=re.sub(r'\s*(?:إن وجد|إن وجدت|اختياري)$','',v);return norm(v)
